    count = 17603,
    rows = {
        [23584] = "Збільшує шкоду зброї в лівій руці на $m1% і кількість люті, яку генерують атаки лівою рукою, на $m2%.",
        [24858] = "Перетворює друїда на місячного совуха, збільшуючи ймовірність спрацювання «Знамення ясності» на $s5%, внесок броні від предметів на $24905s1% і ймовірність критичного удару всіх членів групи в межах $24907a1 ярдів на $24907s1%; не поєднується з «Ватажком зграї». Також захищає заклинача від ефектів Перетворення та не дозволяє застосовувати закляття зцілення.\r\n\r\nЗміна форми звільняє заклинача від Перетворення та ефектів, що обмежують рух.",
        [78156] = "Прикликає Тотем тремтіння з $s1 здоров’я біля ніг заклинача. Він стрясає землю, знімаючи страх, причарування та сон з учасників групи в межах $8146a1 ярдів.",
        [434851] = "Відновлює $o мани протягом $d.",
        [437032] = "Вбивство не надто слабкої цілі, ураженої вашим «Висмоктуванням душі», збільшує відновлення мани на $m1% протягом $1242853d і дає змогу зберігати $m2% звичайного відновлення мани під час застосування заклять.",
        [440212] = "Завдає $?$pl>=25[$s1][${42+($pl-16)*8} до ${57+($pl-16)*8}] шкоди від криги в радіусі $a1 ярдів.",
        [1248377] = "$@spelldesc433 Якщо їсти щонайменше 10 с, ви насититеся й отримаєте $s2 витривалості на $1248406d. $@spelldesc1243969",
