        [1249920] = "$@spelldesc430 Якщо їсти щонайменше 10 с, ви насититеся й отримаєте $s2 сили зцілення на $1249927d. $@spelldesc1243969",
        [1249921] = "$@spelldesc431 Якщо їсти щонайменше 10 с, ви насититеся й отримаєте $s2 сили зцілення на $1249927d. $@spelldesc1243969",
        [1249922] = "$@spelldesc432 Якщо їсти щонайменше 10 с, ви насититеся й отримаєте $s2 сили зцілення на $1249927d. $@spelldesc1243969",
        [1249923] = "$@spelldesc1133 Якщо їсти щонайменше 10 с, ви насититеся й отримаєте $s2 сили зцілення на $1249927d. $@spelldesc1243969",
        [1249924] = "$@spelldesc1135 Якщо їсти щонайменше 10 с, ви насититеся й отримаєте $s2 сили зцілення на $1249927d. $@spelldesc1243969",
        [1249925] = "$@spelldesc1137 Якщо їсти щонайменше 10 с, ви насититеся й отримаєте $s2 сили зцілення на $1249927d. $@spelldesc1243969",
        [1250918] = "Випийте, щоб отримати $s1 спритності та інтелекту. Триває $d.",
        [1250920] = "Випийте, щоб збільшити максимальний запас здоров’я на $s1 і броню на $s2. Триває $d.",
        [1270825] = "Завдає поточній цілі $s1 фізичної шкоди й накладає ауру, що зменшує броню на $s2%.",
        [1288387] = "Поглинає $s1 шкоди, натомість витрачаючи ману. Витрачає $e мани за кожну одиницю поглинутої шкоди.",
        [1288558] = "Уражає ціль смертельним прокляттям, яке спрацьовує через $d. Після завершення завдає $1290040s1 шкоди від тіні та зменшує завдану ціллю шкоду на $1290040s2%.",
        [1288559] = "Уражає ціль отрутою, яка починає діяти через $d. Коли «Цвітіння» завершується, воно знерухомлює ціль і завдає значної шкоди від природи протягом $d.",
        [1288908] = "Рубає поточну ціль, завдаючи $s2 фізичної шкоди й зменшуючи її броню на $s1%.",
        [1289531] = "Збільшує час між атаками ворога на $s1% і швидкість застосування його заклять на $s2%, додаючи $h% ймовірності поширити заразу на союзника при отриманні удару.",
        [1290060] = "Завдає ворогові $s1 шкоди від природи кожні $t1 с і збільшує отримувану ним фізичну шкоду на $s2.",
        [1290800] = "Покращує спритність і гнучкість рук, збільшуючи швидкість виготовлення предметів на $w1%.",
        [1299346] = "Збільшує силу атаки дальнього бою членів групи в радіусі $a1 ярдів на $s1.",
        [1299348] = "Збільшує силу атаки дальнього бою членів групи в радіусі $a1 ярдів на $s1.",
        [1300180] = "Переходить у непомітність, даючи змогу крастися, але зменшує швидкість руху на $s2%. Можна використовувати лише поза боєм.",
        [1302301] = "Збільшує шкоду, яку цільовий елементаль отримує від ваших заклять, на $s1% протягом $d. Діє лише на ворогів рівня $v і нижче.",
        [1302309] = "Завдає $?$pl>=55[$s1][${340+($pl-46)*12} до ${459+($pl-46)*12}] шкоди від криги в радіусі $a1 ярдів.",
        [1302497] = "Відкидає ворогів поблизу в межах $a2 ярдів, завдаючи $s1 шкоди від природи та додатково $s3 шкоди від природи кожні $t3 с протягом $d.",
        [1302768] = "Жбурляє у ворога заряд темної магії, завдаючи $S1 шкоди від тіні.",
        [1303599] = "Поки підтримується це закляття, ваша мана відновлюється прискорено.",
        [1306578] = "Збільшує вашу ймовірність влучання на ${$s1/10}%.",
        [1306620] = "Заморожує ворожу ціль на місці на $d.",
        [1306798] = "Ваша навичка «$@spellname1306798»: $sk134/$<sc>.\r\n\r\nЦіль $PL рівня:\r\nВлучання, ухилення та парирування: ${$<hdp>}.1%\r\nКритичний удар: ${$<cr>}.1%\r\nШтраф ковзного удару: ${$<gp>}%\r\nЙмовірність ковзного удару: ${$<gc>}%\r\n$@expandkey[\r\nЦіль ${$PL+1} рівня:\r\nВлучання, ухилення та парирування: ${$<hdp1>}.1%\r\nКритичний удар: ${$<cr1>}.1%\r\nШтраф ковзного удару: ${$<gp1>}%\r\nЙмовірність ковзного удару: ${$<gc1>}%\r\n\r\nЦіль ${$PL+2} рівня:\r\nВлучання, ухилення та парирування: ${$<hdp2>}.1%\r\nКритичний удар: ${$<cr2>}.1%\r\nШтраф ковзного удару: ${$<gp2>}%\r\nЙмовірність ковзного удару: ${$<gc2>}%\r\n\r\nЦіль ${$PL+3} рівня:\r\nВлучання, ухилення та парирування: ${$<hdp3>}.1%\r\nКритичний удар: ${$<cr3>}.1%\r\nШтраф ковзного удару: ${$<gp3>}%\r\nЙмовірність ковзного удару: ${$<gc3>}%\r\n\r\n$@spelldesc1302929\r\n]",
        [1309054] = "Входить у непомітність, щоб крастися. Можна використовувати лише поза боєм.",
        [1310533] = "Ваш «Укус мангусти» також спричиняє кровотечу, що протягом $1310536d завдає шкоди в обсязі $s1% від шкоди «Укусу мангусти».",
        [1310687] = "Далекобійний постріл, що завдає шкоди дальнього бою плюс $s1 і збільшує дальність ваших наступних $n пострілів на $s2 ярдів протягом $d.",
        [1310785] = "Далекобійний постріл, що завдає шкоди дальнього бою плюс $s1 і збільшує дальність ваших наступних $n пострілів на $s2 ярдів протягом $d.",
        [1310786] = "Далекобійний постріл, що завдає шкоди дальнього бою плюс $s1 і збільшує дальність ваших наступних $n пострілів на $s2 ярдів протягом $d.",
        [1314412] = "Поглинає $w1 шкоди від вогню, зцілюючи на весь обсяг поглинутої шкоди.",
        [1316388] = "Може уразити поточну ціль ефектом «$@spellname1316387», зменшуючи її дух і витривалість на $1316387s1% протягом $1316387d.\r\n",
        [1316489] = "Зменшує швидкість руху ворога на $s1% і всю фізичну та магічну шкоду, яку він завдає, на $s2.",
        [1319311] = "$@spelldesc1129 Якщо їсти щонайменше 10 с, ви насититеся й отримаєте $s2 броні на $1319310d. $@spelldesc1243969",
        [1321586] = "Відновлює $s1 кожні $t1 с протягом $d.",
        [1321587] = "Надає вашим закляттям зцілення шанс додатково відновлювати $1321586s1 здоров’я кожні $1321586t1 с протягом $1321586d.",
        [768] = "Перетворює на котячу форму, збільшуючи силу атаки ближнього бою на $3025s1 плюс спритність.  Також захищає заклинача від ефектів Перетворення та дозволяє використовувати різні котячі здібності.\r\n\r\nПеретворення звільняє заклинача від Перетворення та ефектів, що обмежують рух.",
        [783] = "Перетворює друїда на похідну форму, збільшуючи швидкість руху на $5419s1%.  Також захищає заклинача від ефектів Перетворення.  Можна використовувати лише просто неба.\r\n\r\nПеретворення звільняє заклинача від Перетворення та ефектів, що обмежують рух.",
        [1066] = "Перетворює на водну форму, збільшуючи швидкість плавання на $5421s1% і дозволяючи друїду дихати під водою.  Також захищає заклинача від ефектів Перетворення.\r\n\r\nПеретворення звільняє заклинача від Перетворення та ефектів, що обмежують рух.",
        [2687] = "Генерує $/10;s1 люті ціною здоров’я, а потім ще $/10;29131o1 люті протягом $29131d.",
        [5487] = "Перетворює на ведмедя, збільшуючи силу атак ближнього бою на $1178s4, внесок броні від предметів на $1178s1% і здоров’я на $1178s2. Також захищає заклинача від ефектів Перетворення та дає змогу використовувати різні ведмежі здібності.\r\n\r\nЗміна форми звільняє заклинача від Перетворення та ефектів, що обмежують рух.",
        [8024] = "Насичує зброю шамана вогнем. Кожен удар завдає від ${$8026m1/77-1+($29469m1)} до ${$8026m1/25+($29469m1)} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. На основній руці скасовує вашу особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [8027] = "Насичує зброю шамана вогнем. Кожен удар завдає від ${$8028m1/77-1+($29470m1)} до ${$8028m1/25+($29470m1)} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. На основній руці скасовує вашу особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [8030] = "Насичує зброю шамана вогнем. Кожен удар завдає від ${$8029m1/77-1+($10444m1)} до ${$8029m1/25+($10444m1)} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. На основній руці скасовує вашу особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [8647] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [8649] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [8650] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [9453] = "Зменшує тривалість ефектів страху й дезорієнтації на вас на $s1%.",
        [9634] = "Перетворює на лютого ведмедя, збільшуючи силу атак ближнього бою на $9635s4, внесок броні від предметів на $9635s1% і здоров’я на $9635s3. Також захищає заклинача від ефектів Перетворення та дає змогу використовувати різні ведмежі здібності.\r\n\r\nЗміна форми звільняє заклинача від Перетворення та ефектів, що обмежують рух.",
        [11197] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [11198] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [13983] = "Надає $m1% шанс додати цілі очко серії після ухилення від однієї з її атак або повного опору одному з її заклять.",
        [14751] = "Після активації зменшує витрати мани на наступне закляття на $s1% і збільшує шанс його критичного ефекту на $s2%, якщо це неперіодичне закляття, здатне спричинити критичний ефект.",
        [15270] = "Надає $m1% шанс збільшити ваш дух на $15271s1% на $15271d після вбивства нетривіальної цілі або коли помирає ворог, уражений вашими «Вампіричними обіймами». Поки діє ефект, $15271S2% відновлення мани продовжується під час вимовляння заклять.",
        [16339] = "Наділяє зброю шамана вогнем. Кожен удар завдає від ${$10445m1/77-1+($10444m1)} до ${$10445m1/25+($10444m1)} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. Якщо накладено на основну руку, вимикає будь-яку особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [16341] = "Наділяє зброю шамана вогнем. Кожен удар завдає від ${$16343m1/77-1+($10444m1)} до ${$16343m1/25+($10444m1)} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. Якщо накладено на основну руку, вимикає будь-яку особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [16342] = "Наділяє зброю шамана вогнем.  Кожен удар завдає від ${$16344m1/77-1+($10444m1)} до ${$16344m1/25+($10444m1)} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. Якщо накладено на основну руку, вимикає будь-яку особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [17561] = "Перетворює Сутність землі на Сутність води.",
        [17768] = "Під час активації «Люті» ви отримуєте додатково ${$m1/10} люті, а під час активації «Мінливої сили» — додатково $m2 енергії.",
        [20116] = "Освячує землю під паладином, завдаючи ворогам, які входять у цю область, ${$1280346m1*8} шкоди від святості протягом $d. Перші $s3 вороги, що увійдуть в область, отримають додатково ${$1280346m2*8} шкоди протягом $d.",
        [20922] = "Освячує землю під паладином, завдаючи ворогам, які входять у цю область, ${$1280347m1*8} шкоди від святості протягом $d. Перші $s3 вороги, що увійдуть в область, отримають додатково ${$1280347m2*8} шкоди протягом $d.",
        [20923] = "Освячує землю під паладином, завдаючи ворогам, які входять у цю область, ${$1280348m1*8} шкоди від святості протягом $d. Перші $s3 вороги, що увійдуть в область, отримають додатково ${$1280348m2*8} шкоди протягом $d.",
        [20924] = "Освячує землю під паладином, завдаючи ворогам, які входять у цю область, ${$1280349m1*8} шкоди від святості протягом $d. Перші $s3 вороги, що увійдуть в область, отримають додатково ${$1280349m2*8} шкоди протягом $d.",
        [26573] = "Освячує землю під паладином, завдаючи ворогам, які входять у цю область, ${$1280345m1*8} шкоди від святості протягом $d. Перші $s3 вороги, що увійдуть в область, отримають додатково ${$1280345m2*8} шкоди протягом $d.",
        [77746] = "Ваші вогняні тотеми збільшують силу заклять членів групи та рейду в межах $77747a1 м на $s1%.",
        [77747] = "Ваші вогняні тотеми збільшують силу заклять членів групи та рейду в межах $a1 м на $s1%.",
        [78159] = "Закликає Тотем шаленої бурі з $s1 здоров'я біля ніг заклинача. Тотем надає $8515s1% швидкості ближнього бою всім членам групи та рейду в межах $8515a1 м. Триває $d.",
        [400624] = "Ваші неперіодичні критичні удари «Вогняною кулею», «Крижановогняною стрілою», «Вогняним вибухом» та «Опіком» надають «Гарячу серію» на $400625d «Гаряча серія» зменшує час вимовляння «Вогняного спалаху» на $400625s1%, сумуючись до $400625s2 разів.",
        [400625] = "Ваші неперіодичні критичні удари «Вогняною кулею», «Крижановогняною стрілою», «Вогняним вибухом» та «Опіком» надають «Гарячу серію» на $400625d «Гаряча серія» зменшує час вимовляння «Вогняного спалаху» на $400625s1%, сумуючись до $400625s2 разів.\r\n",
        [407995] = "Кусає ціль, завдаючи $s2% звичайної шкоди плюс $s1",
        [1238069] = "Кусає ціль, завдаючи $s2% звичайної шкоди плюс $s1",
        [1238070] = "Кусає ціль, завдаючи $s2% звичайної шкоди плюс $s1",
        [1238073] = "Кусає ціль, завдаючи $s2% звичайної шкоди плюс $s1",
        [1238214] = "Зцілює ціль і її групу на $o1 протягом $d. Учасники групи мають бути в межах $a1 ярдів від цілі. На початку Дике зростання зцілює швидше, а ближче до завершення дії — повільніше.",
        [1238215] = "Зцілює ціль і її групу на $o1 протягом $d. Учасники групи мають бути в межах $a1 ярдів від цілі. На початку Дике зростання зцілює швидше, а ближче до завершення дії — повільніше.",
        [1240337] = "Дозволяє тестовому реміснику виготовляти предмети різних типів.",
        [1240345] = "Дозволяє шахтарю переплавити шматок мідної руди на мідний злиток.  Потребує горна.",
        [1240365] = "Дозволяє тестовому реміснику виготовляти базові пристрої з максимальною потенційною навичкою 75.  Потрібні інгредієнти, матеріали, а іноді навіть реагенти! [DNT]",
        [1240366] = "Дозволяє тестовому реміснику виготовляти базові пристрої з максимальною потенційною навичкою 150.  Потрібні інгредієнти, матеріали, а іноді навіть реагенти! [DNT]",
        [1240367] = "Дозволяє тестовому реміснику виготовляти базові пристрої з максимальною потенційною навичкою 225.  Потрібні інгредієнти, матеріали, а іноді навіть реагенти! [DNT]",
        [1240368] = "Дозволяє тестовому реміснику виготовляти базові пристрої з максимальною потенційною навичкою 300.  Потрібні інгредієнти, матеріали, а іноді навіть реагенти! [DNT]",
        [1240692] = "Прадавній Скверни спрямовує отруйні лози до ворога, завдаючи $1240706s1 шкоди від сил природи ворогам у межах 5 ярдів і створюючи на місці отруйні випари, що завдають $1263985s1 шкоди від сил природи кожні $1263985t1 с протягом $1240707d.",
        [1240750] = "Вражає ворога стрілою висмоктувальної таємної сили, що поглинає до $s1 мани.",
        [1240770] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240771] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240772] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240773] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240774] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240826] = "Накладає на ціль закляття, яке зцілює її на ${($m1+($bh*$bc))*$<mult>} наступного разу, коли вона отримає шкоду або неперіодичне зцілення. Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $401880a1 ярдів. Перескакує до $s2 разів і триває $401877d після кожного переходу. Одночасно один заклинач може накласти це закляття лише на одну ціль.",
        [1240827] = "Накладає на ціль закляття, яке зцілює її на ${($m1+($bh*$bc))*$<mult>} наступного разу, коли вона отримає шкоду або неперіодичне зцілення. Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $401880a1 ярдів. Перескакує до $s2 разів і триває $401877d після кожного переходу. Одночасно один заклинач може накласти це закляття лише на одну ціль.",
        [1240830] = "Висмоктування таємної сили.",
        [1240848] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду або зцілення.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $a1 ярдів.  Перескакує до $n разів і триває $d після кожного переходу.  Одночасно це закляття може бути накладене лише на одну ціль.",
        [1240849] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду або зцілення.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $a1 ярдів.  Перескакує до $n разів і триває $d після кожного переходу.  Одночасно це закляття може бути накладене лише на одну ціль.",
        [1240921] = "Вивільняє нестабільну ману в області, спрямованій на гравця, завдаючи $s1 шкоди від таємної магії.",
        [1241115] = "Показує розташування всієї нежиті поблизу на мінімапі до скасування. Одночасно можна використовувати лише один тип відстеження.",
        [1241523] = "Випускає насичену маною сферу в напрямку випадкового гравця; сфера летить уперед і повертається до місця походження. Вражені гравці отримують $s1 шкоди від таємної магії.",
        [1241797] = "Ваші завершальні прийоми, що завдають шкоди, зменшують залишок часу відновлення «Викиду адреналіну», «Шквалу клинків», «Ухилення», «Спринту» та «Зникнення» на $m1 с за кожне очко серії.",
        [1241821] = "Запакуйте $M1 руди на ваш вибір.",
        [1242393] = "Прикликає орла-супутника, який супроводжує заклинача, доки його не відкличуть.",
        [1242436] = "Повертає невмерлих прислужників до життя, щоб вони допомагали заклиначеві в бою. ",
        [1242853] = "Відновлення мани збільшено на $s1%, а $s2% відновлення мани продовжується під час вимовляння заклять.",
        [1242871] = "Завдає $s1 шкоди від вогню, а потім продовжує завдавати невеликої шкоди від сонячної магії кожні $t2 с.",
        [1242884] = "Реве на ворога, паралізуючи його жахом на $d і змушуючи всіх інших ворогів поблизу тікати в страху.",
        [1242907] = "Завдає поточній ворожій цілі $S1% фізичної шкоди.",
        [1242913] = "Завдає помірної шкоди від сонячної магії, а потім продовжує завдавати невеликої шкоди від сонячної магії кожні $t2 с.",
        [1242979] = "Накладає ауру, що зцілює на $p1% максимального здоров’я кожні $t1 протягом $d1 с. ",
        [1243081] = "Завдає поточній ворожій цілі $S1 шкоди від тіні.",
        [1243229] = "Завдає поточній ворожій цілі $S1 шкоди від тіні.",
