        [1301709] = "Зменшує час відновлення «Удару бурі» на ${$m1/-1000}.1 с.",
        [1301711] = "Зменшує час відновлення «Виверження лави» на ${$m1/-1000} с.",
        [1301713] = "Зменшує час відновлення «Бистрини» на ${$m1/-1000} с.",
        [1301721] = "Зменшує час відновлення «Безрозсудності» на ${$m1/-1000} с.",
        [1301722] = "Зменшує час відновлення «Стіни щитів» на ${$m1/-1000} с.",
        [1301928] = "Отримувану шкоду від вогню збільшено на $s1%.",
        [1301968] = "Викликає шип оскверненого вітру, що завдає шкоди від природи.",
        [1302066] = "$@spelldesc1127 Якщо їсти щонайменше 10 секунд, ви добре наїстеся й отримаєте $s2 сили протягом $1248422d. $@spelldesc1243969",
        [1302193] = "Після отримання удару в бою завдає нападникові $s1 шкоди від сил природи.",
        [1302205] = "Черпає силу з вашого розуму, відновлюючи $o1 мани протягом $d, але зменшуючи інтелект на $1302206s1 протягом $1302206d.",
        [1302227] = "Насичує меч магією на 1 годину, через що час відновлення «Вогняного вибуху» іноді скидається, коли вас уражає атака ближнього бою.",
        [1302306] = "Насичує посох магією на 1 годину, збільшуючи вашу ймовірність влучання закляттями на ${$1306578s1/10}.1%.",
        [1302308] = "Насичує кинджал магією на 1 годину, через що він іноді відновлює вашу ману при влучанні.",
        [1302310] = "Насичує посох магією на 1 годину, збільшуючи вашу ймовірність критичного удару закляттями на ${$1306583s1}.1%.",
        [1302345] = "Збільшує ймовірність успішного використання «Кишенькової крадіжки» та «Відволікання» на $s1%",
        [1302352] = "Прикликає Тотем лавового струменя біля ніг заклинача. Тотем існує $d і завдає ворогам поблизу $8265s1 шкоди від вогню кожні $8266t1 сек.",
        [1302356] = "Заряджає магнітний камінь на $d, посилюючи його магнітне тяжіння. Притягує зброю наступного нападника ближнього бою, який вас уразить, і роззброює його на $1302357d.",
        [1302359] = "Розвіює $1302360s1 корисний магічний ефект із цільового ворога та ще $1302360s1 магічний ефект кожні $t1 с протягом $d.",
        [1302362] = "Поглинає $s1 шкоди від тіні. Триває $d.",
        [1302375] = "Усі учасники групи в межах $a1 м благословляються, відновлюючи $s1 здоров'я кожні 5 с.",
        [1302380] = "Падіння здоров'я нижче $s1% надає «Повернути відправнику», відбиваючи наступне закляття, застосоване до вас протягом $1302378d. Може спрацьовувати лише раз на ${$proccooldown/60} хв.",
        [1302511] = "Поглинає $s1 шкідливих магічних $leffect:effects; із друга або $s1 корисних магічних $leffect:effects; із ворога.  Якщо ефект поглинуто, скверногончак зцілюється на $19735s1.",
        [1302698] = "Після удару в бою є $h% шанс зняти з себе ефект сповільнення. Може спрацьовувати лише раз на $proccooldown с.",
        [1302708] = "Після удару в бою є $h% шанс збільшити вашу швидкість руху на $1302707s1% протягом $1302707d. Може спрацьовувати лише раз на $proccooldown с.",
        [1302712] = "Після удару в бою є $h% шанс зняти з себе ефект укорінення. Може спрацьовувати лише раз на $proccooldown с.",
        [1302716] = "Коли вас уражає шкідливе закляття, є $h% шанс знемовити заклинача на $1302715d. Може спрацьовувати лише раз на $proccooldown с.",
        [1302717] = "Роззброює ворога на $d.",
        [1302718] = "Після удару в ближньому бою є $h% шанс роззброїти нападника на $1302717d. Може спрацьовувати лише раз на $proccooldown с.",
        [1302721] = "Після удару в бою є $h% шанс зняти з себе ефект роззброєння. Може спрацьовувати лише раз на $proccooldown с.",
        [1302759] = "@$@spelldesc1302764 ",
        [1302760] = "@$@spelldesc1302764 ",
        [1302833] = "Збільшує швидкість бігу на $s1% протягом $d. Поза боєм у пустельних місцевостях додатково збільшує швидкість бігу на $s2% і робить невидимим.",
        [1303140] = "Транслює загрозу всіх NPC поблизу в межах $1303135A1 м кожні $t1 с.\r\n",
        [1303209] = "Заражає ворога хворобою на $d, висмоктуючи $s1 мани кожні $t1 с і переносячи її до заклинача.",
        [1303264] = "Збільшує швидкість атак союзника на $s1% на $d, але також завдає йому $s2 шкоди від сил природи кожні $t2 сек.",
        [1303458] = "Відбиває $s1% шкідливих заклять від заклинача та союзників поблизу протягом $d.",
        [1303499] = "Запускає у ворога магічні снаряди, завдаючи шкоди від таємної магії щосекунди протягом $d.",
        [1303503] = "Вивільняє залишки мани елементаля в область, що відновлює істотам поблизу $1303505s1 мани кожні $1303505t1 с.",
        [1303598] = "Перетворює ворогів поблизу на тварин, змушуючи їх блукати протягом до $d. Під час блукання поліморфована ціль не може атакувати чи вимовляти закляття.",
        [1303853] = "Викиньте небезпечні матеріали на безпечній відстані від Штуковинська та іншого сміття.",
        [1303979] = "Збільшує швидкість атак заклинача на $s2% і завдану ним фізичну шкоду на $s1 на $d.",
        [1304277] = "Викиньте небезпечні матеріали на безпечній відстані від Штуковинська та іншого сміття.",
        [1304452] = "Збільшує ймовірність критичного удару заклять і атак на $s1%, силу атаки — на $s2, а шкоду й зцілення заклять — на величину до $s4 Триває $d.",
        [1304473] = "Проклинає ворога на $d, даючи йому $h% шанс отримати $6910s1 шкоди під час атаки.",
        [1304594] = "Збільшує здоров'я на 300. Надає 15% швидкості атак ближнього бою. Відновлює 10 мани кожні 5 секунд.",
        [1304678] = "Збільшує запас здоров’я на 300. Прискорює всі закляття й атаки на 15%. Відновлює 10 мани кожні 5 секунд.",
        [1304690] = "Збільшує шанс критичного удару ближнього бою, дальнього бою або закляттям на $s1% і всі характеристики на $s2 протягом $d.",
        [1304753] = "Загальна витривалість збільшується на $s1%.",
        [1304759] = "Сила атаки збільшується на $s1, а шкода та зцілення заклять — на величину до $s3.",
        [1306448] = "Збільшує ймовірність критичного ефекту вашого закляття «Мала хвиля зцілення» на $s1%.",
        [1306488] = "Скорочує час відновлення вашого закляття «Швидке відновлення» на ${$m1/-1000} с.",
        [1306675] = "Завдає $s1 шкоди від вогню.",
        [1306677] = "Завдає $s1 шкоди від природи.",
        [1306678] = "Завдає $s1 шкоди від тіні.",
        [1306679] = "Завдає $s1 шкоди від криги.",
        [1306681] = "Збільшує ймовірність влучання атаками другої руки на ${$s1}.1%.",
        [1306686] = "Збільшує дальність атак ближнього бою на $s2 м.",
        [1306786] = "«Правосуддя» проти звірів скорочує час відновлення «Святого удару» на ${$s1/-1000}.1 с.",
        [1306794] = "Елуна сповнює мисливицю люттю, завдаючи $s1 шкоди від аркани ворогам у межах $a м і завдаючи $1306811s1 шкоди від аркани кожні $t2 с.",
        [1306907] = "Назавжди збільшує навичку захисту на $ec1 і витривалість на $ec2 предмета, одягненого на нагрудник, ноги, руки або ступні. Можна застосовувати лише до предметів $ecim рівня й вище.",
        [1306908] = "Швидкість руху збільшено на $s1% у засніжених місцевостях.",
        [1307007] = "Наповнює блискавкою, завдаючи $1307008S1 шкоди від природи у випадкових місцях поблизу кожні $t1 с.",
        [1307019] = "Швидкість руху цілі зменшено, а час між її атаками збільшено.",
        [1307067] = "У спалаху сталі заклинач обертає зброю, завдаючи звичайної шкоди плюс $1307066s1 усім гравцям у межах $1307066A1 м.",
        [1307068] = "Дух збільшено на $s1.",
        [1307132] = "Переводить заклинача в режим непомітності на $d.",
        [1307208] = "Застосування шокових заклять до невмерлих скорочує час відновлення «Удару бурі» на ${$s1/-1000}.1 с.",
        [1307229] = "Встановлює табірний стілець, який дає вам та іншим гравцям, що сидять поблизу, $1229519s1% збільшення ймовірності критичного удару всіма закляттями й атаками; не поєднується з «Аурою совуха».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307234] = "Викликає зачаровану лютню, яка дає вам та іншим гравцям, що сидять поблизу, $?$PL<10[28]?$PL<20[71]?$PL<30[114]?$PL<40[163]?$PL<50[211]?$PL<60[260][$1230653s1 ] збільшення броні$?$PL<10[]?$PL<30[ та ][, ]$?$PL>59[$1230653s2]?$PL>49[12]?$PL>39[9]?$PL>29[7]?$PL>19[4]?$PL>9[2][]$?$PL>9[ до всіх характеристик][]$?$PL>59[, а також $1230653s3]?$PL>49[, а також 16]?$PL>39[, а також 12]?$PL>29[, а також 6][]$?$PL>29[ до всіх видів опору][], не поєднується зі «Знаком дикої природи».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307239] = "Розгортає прапор, який дає вам та іншим членам Альянсу, що сидять поблизу, $?$PL<40[14]?$PL<50[19]?$PL<60[27][$1229718s1] додаткового духу; не поєднується з «Божественним духом».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307240] = "Розгортає прапор, який дає вам та іншим членам Орди, що сидять поблизу, $?$PL<40[14]?$PL<50[19]?$PL<60[27][$1229718s1] додаткового духу; не поєднується з «Божественним духом».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307243] = "Розміщує польовий довідник, який гравці можуть прочитати, щоб отримати «Вистежування звірів», і надає всі переваги табірного стільця. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх табірного стільця, замінивши його.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307244] = "Розпаковує аптечку першої допомоги, яка дає вам та іншим гравцям, що сидять поблизу, $?$PL<12[3]?$PL<24[8]?$PL<36[21]?$PL<48[34]?$PL<60[45][$1230124s1] додаткової витривалості; не поєднується зі «Словом сили: Стійкість».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307245] = "Розміщує невеликий акваріум, який дає вам та іншим гравцям, що сидять поблизу, $1230098s1% збільшення характеристик; не поєднується з «Благословенням королів».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307246] = "Розміщує рибальську хатину, що дає змогу ловити рідкісну рибу протягом $1280342d, надає принади до навички рибальства та всі переваги акваріума. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх акваріума, замінивши його.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307247] = "Розміщує рибальську стійку, що дає змогу ловити незвичайну рибу протягом $1280341d, надає принади до навички рибальства та всі переваги акваріума. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх акваріума, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307251] = "Запалює пахощову свічку, яка дає вам та іншим гравцям, що сидять поблизу, $?$PL<14[2]?$PL<28[6]?$PL<42[12]?$PL<56[18][$1229513s1] додаткового інтелекту; не поєднується з «Арканічним інтелектом».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307254] = "Встановлює магнітний камінь, який дає вам та іншим гравцям, що сидять поблизу, $?$PL<12[12]?$PL<22[20]?$PL<32[32]?$PL<42[49]?$PL<52[67][$1230164s1] додаткової сили атаки ближнього бою; не поєднується з «Благословенням могутності».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307259] = "Будує криницю мани, яка дає вам та іншим гравцям, що сидять поблизу, відновлення $?$PL<24[10]?$PL<34[15]?$PL<44[20]?$PL<54[24][$1230587s1] мани кожні 5 с; не поєднується з «Благословенням мудрості».\n\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307265] = "Розміщує лабораторію чумного лікаря з цілющими зіллями й припарками та надає всі переваги аптечки першої допомоги. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх аптечки першої допомоги, замінивши її. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307288] = "Завдає цілі $s1 шкоди від тіні та висмоктує $s3 мани. Завдає невмерлим у $s2 рази \r\nбільше шкоди.",
        [1307392] = "Будує точильний круг, який дає вам та іншим гравцям, що сидять поблизу, $?$PL<24[6]?$PL<38[11]?$PL<52[20][$1230172s1] додаткової сили; не поєднується з «Тотемом сили землі».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307396] = "Розміщує дослідження токсинів із цілющими зіллями та протиотрутою й надає всі переваги аптечки першої допомоги. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх аптечки першої допомоги, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307397] = "Розміщує верстак мисливця з 1 пасткою та надає всі переваги табірного стільця. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх табірного стільця, замінивши його.\r\n\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307411] = "Випийте мене. Я смачний!",
        [1307508] = "Коли вас вражають у бою, нападник отримує $s1 шкоди від природи та $1307509s1 шкоди від аркани.",
        [1307520] = "Укорінює ціль на місці й завдає $o2 шкоди від природи протягом $d. Отримана шкода може перервати ефект.",
        [1307760] = "Сила збільшена на $1307762s1, поки ваш інвентар заповнений.",
        [1307943] = "Збільшує ймовірність успішного використання «Кишенькової крадіжки» та «Відволікання» на $s1%",
        [1307944] = "Збільшує ймовірність успішного використання «Кишенькової крадіжки» та «Відволікання» на $s1%",
        [1307945] = "Збільшує ймовірність успішного використання «Кишенькової крадіжки» та «Відволікання» на $s1%",
        [1308024] = "Збільшує зцілення заклять і ефектів на величину до $s1, а їхню шкоду — на величину до $s2.",
        [1308463] = "Розщеплює ціль надвоє, завдаючи $o1 шкоди від тіні протягом $d. Завдає у $s2 рази більше шкоди, якщо застосовано спереду від цілі.",
        [1308473] = "Заклинач покриває зброю шкідливою отрутою, через що атаки зброєю можуть завдати додатково $s1 шкоди від природи.",
        [1308652] = "Телепортує заклинача до Даларана.",
        [1308910] = "Знімає $s1 ефект отрути.",
        [1308913] = "Ваші атаки ближнього бою можуть відновити ману.",
        [1309073] = "Кидає м'яч дружньому гравцеві. Якщо в його сумці є вільне місце, він його зловить!",
        [1309283] = "Збільшує швидкість бігу назад на $s1% протягом $d1.",
        [1309369] = "Швидкість руху збільшено на $s1% у Срібнохвойному лісі та Гіллзбрадському передгір’ї.",
        [1309420] = "Клацніть правою кнопкою миші, щоб викликати або відкликати вашого [PH] Пачімару.",
        [1309598] = "Слово темних пут, що завдає цілі шкоди від тіні.  Якщо ціль не загине від Слова Тіні: Смерть, заклинач отримує стільки ж шкоди, скільки було завдано цілі.",
        [1309678] = "[NYI] Надає щит, що поглинає до $s1 шкоди протягом $d. Поки щит активний, отримана шкода від вогню зменшена на $s2%.",
        [1309728] = "Збільшує швидкість бігу на $s1% протягом $d1.",
        [1309788] = "Причаровує ціль-звіра, зменшуючи завдану вам нею шкоду на $s1%.",
        [1309950] = "Зменшує витрати мани на «Пожираючу чуму» на $s1%.\r\n\r\nЦілі, що помирають під дією «Пожираючої чуми», поширюють її на ворога поблизу в межах $s2 м на залишок тривалості.\r\n",
        [1310015] = "Швидкість руху збільшено на $s1% у Тернистій долині та Річкових галявинах.",
        [1310023] = "Зливається з тінями, зменшуючи ймовірність виявлення ворогами. Триває до скасування або початку руху",
        [1310087] = "Висмоктує $o1 здоров’я з ворога протягом $d і передає його заклиначеві.",
        [1310167] = "Випускає пиляльний диск у ціль, завдаючи $s1 шкоди й спричиняючи кровотечу на $o2 протягом$d.",
        [1310168] = "Випускає пиляльний диск у ціль, завдаючи $1310167s1 шкоди й спричиняючи кровотечу, що завдає $1310167o2 шкоди протягом $1310167d.",
        [1310222] = "Жорстока атака, що завдає $s2% шкоди зброї. Завдає додатково ${$s2*$s3}% шкоди зброї велетням, драконідам і верховим цілям. Верхові цілі спішуються.",
        [1310296] = "Дозволяє ходити по воді протягом $d.",
        [1310315] = "Зменшує витрати люті на ваші здібності «Розсічення» та «Вихор» на ${$m2/-10}.",
        [1310496] = "Скорочує час відновлення ваших здібностей-пасток та «Стримування» на $m1%.",
        [1310612] = "Збільшує ймовірність ухилення вашого вихованця на $s1% і скорочує час між його атаками на $s2%. Триває $d.",
        [1310627] = "Збільшує критичну шкоду ваших атак ближнього бою на $s1%, а шкоду зброї другої руки — на $s2%.",
        [1310661] = "Збільшує шкоду «Жала змії» на $s1%, скорочує час відновлення «Жала гадюки» на ${$m2/-1000} с і збільшує тривалість «Жала скорпіда» на ${$m3/1000} с.",
        [1310703] = "Завершальний прийом, що збільшує шкоду ваших отрут на $m2% і ймовірність накладання отрут на $m4%. Триває довше за кожне очко серії:\r\n   1 очко  : 9 секунд\r\n   2 очки: 12 секунд\r\n   3 очки: 15 секунд\r\n   4 очки: 18 секунд\r\n   5 очок: 21 секунда",
        [1310735] = "Зменшує витрати мани на печатки на $s1%, а коли ви замінюєте «Печатку наказу», «Печатку праведності», «Печатку люті» або «Печатку справедливості» іншою печаткою, отримуєте Відлуння попередньої. Наступна атака ближнього бою застосовує ефекти заміненої печатки й поглинає Відлуння.",
        [1310897] = "Надає несприйнятливість до ефектів мовчання та переривання. Триває $d.",
        [1310909] = "Наступний «Святий шок» заклинача по цій цілі активує «Варту Світла», зцілюючи ціль та її групу на $1310912s1.",
        [1310911] = "Накладає на ціль «Варту Світла» на $1310909d. Наступний «Святий шок» по ній не спричиняє відновлення й завдає ворогам $1310914s1 шкоди від святості та повертає $s2% витрат мани «Варти Світла», або зцілює групу союзної цілі на $1310912s1. Паладин може мати лише одну активну «Варту Світла» на групу.",
        [1310912] = "Активується «Святим шоком». Зцілює ціль та її групу на $s1. Учасники групи мають бути в межах $a1 м від цілі.",
        [1311015] = "Після активації надає щит, що поглинає шкоду в обсязі $s1% від вашого максимального здоров’я протягом $d. Накладає «Стриманість» на $25771d. Не можна застосувати під дією «Стриманості».",
        [1311022] = "Збільшує ймовірність влучання зброєю в другій руці на $s1%.",
        [1311034] = "Збільшує загрозу від «Святого удару» на $m1%. Поки діє «Праведна лють», «Святий удар» також зменшує отриману вами шкоду на $m2% протягом $1311033d.",
        [1311084] = "Збільшує шкоду й зцілення ваших заклять на величину до $m1% від вашого інтелекту.",
        [1311590] = "Накладає на ціль «Варту Світла» на $1311593d. Наступний «Святий шок» по ній не спричиняє відновлення й завдає ворогам $1311592s1 шкоди від святості та повертає $s2% витрат мани «Варти Світла», або зцілює групу союзної цілі на $1311591s1. Паладин може мати лише одну активну «Варту Світла» на групу.",
        [1311591] = "Активується «Святим шоком». Зцілює ціль та її групу на $s1. Учасники групи мають бути в межах $a1 м від цілі.",
        [1311593] = "Наступний «Святий шок» заклинача по цій цілі активує «Варту Світла», зцілюючи ціль та її групу на $1311591s1.",
        [1311595] = "Накладає на ціль «Варту Світла» на $1311597d. Наступний «Святий шок» по ній не спричиняє відновлення й завдає ворогам $1311598s1 шкоди від святості та повертає $s2% витрат мани «Варти Світла», або зцілює групу союзної цілі на $1311596s1. Паладин може мати лише одну активну «Варту Світла» на групу.",
        [1311596] = "Активується «Святим шоком». Зцілює ціль та її групу на $s1. Учасники групи мають бути в межах $a1 м від цілі.",
        [1311605] = "Зцілено на $s1",
        [1311649] = "Сповнює паладина божественною люттю на $d, через що атаки ближнього бою завдають додатково $1311647s1 шкоди від святості. Зі спорядженим щитом кожна атака також надає щит, що поглинає шкоду в обсязі $m2% від завданої святої шкоди. Одночасно на паладині може діяти лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки завдає ворогу $1311650s1 шкоди від святості й провокує ціль атакувати вас протягом $20232d.",
        [1311656] = "Сповнює паладина божественною люттю на $d, через що атаки ближнього бою завдають додатково $1311654s1 шкоди від святості. Зі спорядженим щитом кожна атака також надає щит, що поглинає шкоду в обсязі $m2% від завданої святої шкоди. Одночасно на паладині може діяти лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки завдає ворогу $1311655s1 шкоди від святості й провокує ціль атакувати вас протягом $20232d.",
        [1311676] = "Проклинає ціль на $d, зменшуючи її опір магії на $s1 і збільшуючи отриману магічну шкоду на $s2%. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.\r\n",
        [1311677] = "Проклинає ціль на $d, зменшуючи її опір магії на $s1 і збільшуючи отриману магічну шкоду на $s2%. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.\r\n",
        [1311680] = "Проклинає ціль на $d, зменшуючи її опір магії на $s1 і збільшуючи отриману магічну шкоду на $s2%. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [1311895] = "Швидкість руху збільшено на $s1% на Гіджалі.",
        [1312052] = "Завдає демону або звірові $443265o1 шкоди від вогню протягом $443265d і укорінює його на місці на $d. Отримана шкода може перервати ефект.",
        [1312233] = "Відкрийте, щоб отримати товари й спорядження відповідного рівня для допомоги в мандрах.\r\n\r\nПеред відкриттям переконайтеся, що в інвентарі достатньо місця. Надлишкові предмети можна забрати з поштової скриньки.",
        [1312869] = "Висмоктує з ворога $s1 здоров’я кожні $t1 с протягом $d та переносить його до заклинача.",
        [1312870] = "Завдає $s1 шкоди від природи ворогам у межах $a1 м від поточної цілі.",
        [1312955] = "Після отримання удару в бою завдає нападникові $s1 шкоди від вогню.",
        [1313379] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $41635a1 ярдів. Перескакує до $48113n разів і триває $48111d після кожного переходу. Одночасно це закляття може бути накладене лише на одну ціль.\r\n",
        [1313381] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $41635a1 ярдів. Перескакує до $48113n разів і триває $48111d після кожного переходу. Одночасно це закляття може бути накладене лише на одну ціль.\r\n",
        [1314065] = "Швидкість руху верхи збільшено на $s1%. Не поєднується з подібними ефектами.",
        [1314069] = "Вражає ворога, завдаючи $s1 шкоди від вогню.",
        [1314281] = "Завдає шкоди від вогню всім ворогам у вибраній області.",
        [1314415] = "Поглинута шкода від вогню зцілює користувача.",
        [1314842] = "Благословенний Великим Котячим Духом.",
        [1315080] = "Збільшує швидкість верхової їзди на $s1% у Східному та Західному Чумнозем’ї.",
        [1315212] = "Згоріть у багряному полум’ї, щоб повернутися до $z. Поговоріть з корчмарем в іншому місці, щоб змінити місце повернення.",
        [1315237] = "Видихає мерзотну гниль і розклад, завдаючи $S1 шкоди від природи всім гравцям у межах $r м.",
        [1315330] = "Уночі інтелект збільшено на $s1.",
        [1315408] = "Благословенний Великим Вітронесеним Котячим Духом.",
        [1315451] = "Клацніть правою кнопкою миші, щоб викликати або відкликати вашого малюка-кроколіска.",
        [1315557] = "Причаровує ціль, не даючи їй діяти протягом до $d. Будь-яка шкода знімає ефект. Діє лише на гуманоїдів.",
        [1315767] = "Зменшує силу атаки ворожої цілі на $s1 протягом $d.",
        [1315778] = "Збільшує швидкість верхової їзди на $s1% у Зимоключі.",
        [1315878] = "Надає $s1 спритності на $d. Якщо поблизу є елементаль, додатково надає $s2.",
        [1316039] = "Обпалює плоть цілі, завдаючи $s1 шкоди від вогню.",
        [1316382] = "Підіймає пил, завдаючи $s1 фізичної шкоди ворогам у межах $a1 м і зменшуючи їхню ймовірність влучання атаками на $s2%.",
        [1316480] = "Обплутує ворогів поблизу корінням, завдаючи $s2 шкоди від природи кожні $t2 с і знерухомлюючи до $d.",
        [1316697] = "Роздирає ціль зсередини, завдаючи $s1 шкоди від тіні кожні $t с і збільшуючи шкоду, яку вона отримує від інших ваших періодичних ефектів тіні, на $s2%. Триває $d.",
        [1316991] = "Зцілює на $s1 кожні $1316992t2 с протягом $1316992d.",
        [1317040] = "+$s1. сили.",
        [1317170] = "Викликає вогняного елементаля, який допомагатиме заклиначу в бою протягом $d.",
        [1317268] = "Завдає $s1 шкоди від святості цілям у радіусі $a1 м. Іноді може дати зворотний ефект і наділити цілі силою Світла.",
        [1317272] = "Сповнює ціль святим духом на $d, через що кожна атака ближнього бою завдає додаткової шкоди від святості. ",
        [1317486] = "Швидкість руху збільшено на $s1% у Бруднолипкій трясовині та Болоті скорбот.",
        [1317516] = "Зцілює союзника кожні $t1 с. протягом $d.",
        [1317692] = "Навчає «Дресируванню звіра», «Годуванню вихованця» та «Оживленню вихованця».",
        [1317695] = "Навчає «Дресируванню звіра», «Годуванню вихованця» та «Оживленню вихованця».",
        [1318244] = "Швидкість руху збільшено на $s1% у Степах і Кам’янистих горах.",
        [1318807] = "Вивільняє хмару млявості в радіусі $a1 м. Вороги, що атакують у хмарі, мають $1300240h% ймовірність заснути на $1300241d. Триває $d.",
        [1319257] = "Освячує зброю заклинача, додаючи $s1 шкоди до її наступної атаки. Уся завдана шкода належить до святої магії.",
        [1319259] = "Завдає ворогу $s1 шкоди й збільшує отриману ним шкоду від святості на $s2 за кожен «Удар хрестоносця». Може накладатися до 2 разів. Триває $d.",
        [1319260] = "Збільшує швидкість на $s1% усім союзникам у межах $r м.",
        [1319310] = "Поживна їжа надала вам ефект ситості, збільшуючи броню..",
        [1319378] = "Завдає $s1 шкоди від аркани.",
        [1319423] = "Швидкість руху збільшено на $s1% у Тернистій долині та Річкових галявинах.",
        [1319426] = "Швидкість руху збільшено на $s1% у Тернистій долині та Річкових галявинах.",
        [1319427] = "Швидкість руху збільшено на $s1% у Тернистій долині та Річкових галявинах.",
        [1319611] = "Спілкується зі Смарагдовим Сном, щоб підкорити Нітуса.",
        [1320095] = "Обплутує ворога корінням, завдаючи шкоди від сил природи кожні $t2 с. і знерухомлюючи його на час до $d.",
        [1320183] = "Викликає Біса, який супроводжує заклинача, доки його не буде відпущено.",
        [1320643] = "Дає змогу затримувати дихання під водою на $s1% довше.",
        [1320726] = "Дикий бій збільшено на +$s1.",
        [1320824] = "Ранить ціль, змушуючи її кровоточити й отримати $o1 шкоди протягом $d.",
        [1321337] = "Телепортує заклинача до Орґріммара.",
        [1321339] = "Телепортує заклинача до Орґріммара.",
        [1321343] = "Телепортує заклинача до Орґріммара.",
        [1321558] = "Відновлює $s1 мани кожні $t с.",
        [1321560] = "Коли мана опускається нижче $s1%, відновлює $1321558o1 мани протягом $1321558d. У примарних і пустельних місцевостях відновлює вдвічі більше мани. Ефект може спрацювати лише раз на ${$proccooldown/60} хв.",
        [1322218] = "Запалює ціль полум’ям Великої Кузні, завдаючи $s1 шкоди священним вогнем. Завдає у $s2 рази більше шкоди елементалям вогню та землі.",
        [1322303] = "Розрубує навпіл труп гуманоїда або невмерлого поблизу, відновлюючи $1322305s1 здоров’я, $1322305s2 мани та ${$1322305s3/10} люті.",
        [1322304] = "Завдає потужного кришталевого удару, що завдає $s1 фізичної шкоди в конусі та відкидає всі уражені цілі.",
        [1322305] = "Відновлює $s1 здоров’я, $s2 мани та ${$s3/10} люті.",
        [1322311] = "Не може отримати користь від «Висмоктування могили».",
        [1322312] = "Збільшує швидкість приготування їжі на $s1%.",
        [1322318] = "Атаки ближнього бою мають шанс завдати додатково $s1 шкоди від тіні.",
        [1322587] = "Чизкейк робить вас щасливим.",
        [1322605] = "Миттєво перетворює $c мани на $s2 енергії. Вартість «Мінливої сили» зменшується ефектами, що зменшують вартість перевтілення.",
        [1322670] = "Зменшує час відновлення вашого закляття «Мінлива сила» на ${$m1/-1000} с.",
        [1323075] = "Подає Кайлу його обід!",
        [1323184] = "Плавання в небезпечних водах може привабити акул Темного Списа поблизу!\r\n\r\nУкус завдаватиме вам шкоди в розмірі $1286850s1% вашого здоров’я кожні $t1 с.\r\n",
        [1323209] = "Відкидає ворогів поблизу.",
        [1323243] = "Спричиняє дощ зі стріл у місці розташування випадкової цілі, завдаючи $S1% фізичної шкоди кожні $T1 с.",
        [5] = "Миттєво вбиває ціль.  Сподіваюся, тепер ти задоволений собою.....",
        [10] = "Крижані уламки засипають вибрану ділянку, завдаючи ${$1279976m1*$d*$<frostdamage>} шкоди від криги протягом $d.",
        [17] = "Прикликає силу душі члена групи, щоб захистити його щитом, який поглинає $?a14748[${$s1*(1+$14748s1/100)}][$s1] шкоди.  Триває $d.  Поки щит тримається, отримана шкода не перериває застосування заклинань.  Після накладання щита ціль не можна захистити ним знову протягом $6788d.",
        [45] = "Відкидає ворогів поблизу.",
        [53] = "Завдає цілі удару в спину, спричиняючи $s2% шкоди від зброї плюс $s1 шкоди.  Потрібно перебувати позаду цілі.  Потребує кинджала в основній руці.  Дає $s3 $lpoint:очко:очки; серії.",
        [56] = "Приголомшує ціль на $d.",
        [65] = "Збільшує швидкість атаки на $s1% протягом $d.",
        [66] = "Робить заклинача невидимим на $d, однак це заклинання нестабільне й може завершитися раніше.",
        [71] = "Захисна бойова стійка.  Зменшує отриману шкоду на $7376s1%, а завдану шкоду — на $7376s2%.  Збільшує всю створювану загрозу на $?a12792[${($7376s3+100)*($12792s1/100+1)-100)}.1%][$7376s3%].",
        [72] = "Б’є ціль щитом, завдаючи $s2 шкоди.  Також перериває застосування заклинань і не дозволяє застосовувати заклинання цієї школи протягом $d.",
        [75] = "Автоматично стріляє в ціль, доки дію не буде скасовано.",
        [78] = "Потужна атака, що збільшує шкоду в ближньому бою на $s1 і створює багато загрози.",
        [81] = "Дає шанс ухилитися від атак ближнього бою ворога.",
        [87] = "Швидкість атаки збільшено на $s1%\r\nШвидкість руху збільшено на $s2%",
        [89] = "Калічить ціль, зменшуючи швидкість руху на $s3%, збільшуючи час між атаками ближнього бою на $s1% і час між атаками дальнього бою на $s2%.  Триває $d.",
        [96] = "Збільшує шкоду наступної атаки ближнього бою на $s1 і змушує ціль кровоточити",
        [99] = "Друїд реве, зменшуючи силу атаки ближнього бою ворогів поблизу на $s1.  Триває $d.",
        [100] = "Кидається на ворога, генерує $/10;s2 люті та приголомшує його на $7922d.  Не можна використовувати в бою.",
        [101] = "Підсікає ворожого гуманоїда, завдаючи $s2 шкоди й збиваючи його з ніг на $d.  Дає $s3 очко серії.",
        [107] = "Дає шанс блокувати атаки ближнього й дальнього бою ворога.",
        [113] = "Утворює навколо ворога крижані ланцюги, приковуючи ціль до місця на $d.",
        [116] = "Запускає у ворога крижану стрілу, що завдає від ${$m2$*$<frostdamage>} до ${$M2*$<frostdamage>} шкоди від криги та зменшує швидкість руху на $s1% протягом $d.",
        [118] = "Перетворює ворога на вівцю, змушуючи її блукати до $d.  У такому стані вівця не може атакувати чи застосовувати заклинання, але дуже швидко відновлює здоров’я.  Будь-яка шкода поверне цілі звичайну форму.  Одночасно можна перетворити лише одну ціль.  Діє лише на звірів, гуманоїдів і малих істот.",
        [120] = "Цілі в конусі перед заклиначем отримують від ${$m2$*$<frostdamage>} до ${$M2*$<frostdamage>} шкоди від криги, а їхня швидкість руху зменшується на $s1% протягом $d.",
        [122] = "Уражає ворогів біля заклинача, завдаючи від ${$m1*$<frostdamage>} до ${$M1*$<frostdamage>} шкоди від криги та примерзаючи їх до місця на час до $d.  Завдана шкода може перервати ефект.",
        [126] = "Викликає Око Кілроґґа й пов’язує з ним ваш зір.  Око швидко рухається, але дуже крихке.",
        [128] = "Знімає із заклинача всі магічні ефекти й поглинає $s2 магічної шкоди протягом $d.",
        [130] = "Зменшує швидкість падіння на $d.",
        [131] = "Дозволяє цілі дихати під водою протягом $d.",
        [132] = "Дозволяє дружній цілі виявляти слабшу невидимість протягом $d.",
        [133] = "Жбурляє вогняну кулю, що завдає $s1 шкоди від вогню та додатково $o2 шкоди від вогню протягом $d.",
        [134] = "Оточує союзника полум’яним щитом, який завдає ворогам поблизу $3052s1 шкоди від вогню кожні $t1 с.  Триває $d.",
        [136] = "Зцілює вашого вихованця на $s1 здоров’я щосекунди, доки ви зосереджуєтесь.  Триває $d.",
        [139] = "Зцілює ціль на $o1 протягом $d.",
        [143] = "Жбурляє вогняну кулю, що завдає $s1 шкоди від вогню та додатково $o2 шкоди від вогню протягом $d.",
        [145] = "Жбурляє вогняну кулю, що завдає $s1 шкоди від вогню та додатково $o2 шкоди від вогню протягом $d.",
        [168] = "Збільшує броню на $s1.  Коли ворог влучає в заклинача, його швидкість руху може зменшитися на $6136s1%, а час між атаками — збільшитися на $6136s2% протягом $6136d.  Одночасно на магові може діяти лише одне заклинання броні.  Триває $d.",
        [172] = "Оскверняє ціль, завдаючи $o1 шкоди від тіні протягом $d.",
