        [945] = "Заклинача оточують $n куль блискавки.  Коли заклинача вражає заклинання, атака ближнього чи дальнього бою, нападник отримує $26367s1 шкоди від сил природи.  Це витрачає одну кулю блискавки.  Спрацьовувати може не частіше ніж одна куля раз на кілька секунд.  Триває $d.",
        [950] = "Навчає Бомби розуму.",
        [952] = "Навчає Розплавленого вибуху (ранг 5).",
        [959] = "Зцілює дружню ціль на $s1.",
        [967] = "Навчає Групового астрального повернення.",
        [970] = "Слово темряви, що завдає $o1 шкоди від тіні протягом $d.",
        [973] = "Навчає Святого захисту.",
        [974] = "Захищає ціль земляним щитом, зменшуючи втрату часу застосування чи підтримання заклинань від шкоди на $s2% і змушуючи атаки зцілювати захищену ціль на $<heal>.  Ефект може спрацьовувати лише раз на кілька секунд.  $n зарядів.  Триває $d.  Земний щит можна накласти лише на одну ціль одночасно, і на цілі одночасно може діяти лише один щит стихій.",
        [976] = "Збільшує опір цілі заклинанням тіні на $s1 протягом $d.",
        [977] = "Навчає Захисту від тіні.",
        [980] = "Уражає ціль агонією, завдаючи $o1 шкоди від тіні протягом $d. Спочатку шкода завдається повільно, але посилюється з наближенням Кари до завершення. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.",
        [982] = "Воскрешає вашого вихованця з $s1% здоров’я.",
        [984] = "Карає ворога, завдаючи $s1 шкоди від святості.",
        [988] = "Розвіює магію на цілі, знімаючи $s1 шкідливі $lspell:заклинання:заклинання; із союзника або $s1 корисні $lspell:заклинання:заклинання; з ворога.",
        [990] = "Створює чарами $s1 $lloaf:буханець:буханці; житнього хліба, даючи магу та $ghis:його:її; союзникам їжу.\r\n\r\nСтворені чарами предмети зникають, якщо вийти з гри більш ніж на 15 хвилин.",
        [992] = "Слово темряви, що завдає $o1 шкоди від тіні протягом $d.",
        [994] = "Збільшує броню групи, доки не завершиться час дії або жрець не припинить молитися.",
        [996] = "Могутня молитва зцілює ціль і її групу на $s1. Члени групи мають бути в межах $a1 ярдів від цілі.",
        [999] = "Навчає Слова Тіні: Спотикання (ранг 2).",
        [1002] = "Дозволяє безпосередньо керувати вихованцем і бачити його очима протягом $d.",
        [1003] = "Навчає Слова Тіні: Збентеження (ранг 2).",
        [1004] = "Карає ворога, завдаючи $s1 шкоди від святості.",
        [1006] = "Спалах святої енергії наповнює заклинача, збільшуючи броню на $s1.  Кожне влучання атакою ближнього чи дальнього бою по жерцю витрачає один заряд.  Триває $d або доки не буде витрачено $n зарядів.",
        [1008] = "Підсилює магію, спрямовану на вибраного члена групи, збільшуючи шкоду від заклинань на величину до $s1, а зцілення від заклинань — на величину до $s2.  Триває $d.",
        [1009] = "Б’є ворога кулаком.",
        [1010] = "Проклинає ціль недоумством, зменшуючи інтелект і дух на $s1 кожні $t3 секунд, доки кожна характеристика не буде зменшена загалом на $*15;s1.  На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [1012] = "Збільшує навичку володіння мечами на 3.",
        [1014] = "Уражає ціль агонією, завдаючи $o1 шкоди від тіні протягом $d. Спочатку шкода завдається повільно, але посилюється з наближенням Кари до завершення. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.",
        [1020] = "Захищає паладина від усієї шкоди та заклинань протягом $d, але зменшує всю завдану ним шкоду на $s3%.  Накладає Стриманість на $25771d. Не можна застосувати, поки діє Стриманість.",
        [1022] = "Вибраний член групи захищений від усіх фізичних атак протягом $d, але в цей час не може атакувати чи використовувати фізичні здібності.  На гравцеві одночасно може діяти лише одне благословення від одного паладина.  Накладає Стриманість на $25771d. Не можна застосувати, поки діє Стриманість.",
        [1023] = "Навчає Печатки захисту (ранг 1).",
