        [1032] = "Надає членам групи в радіусі $a1 ярдів $s1 додаткової броні.  На гравцеві одночасно може діяти лише одна аура від одного паладина.",
        [1037] = "Навчає Печатки люті (ранг 1).",
        [1038] = "Накладає на члена групи Благословення, що зменшує всю створювану загрозу на $s1% протягом $d.  На гравцеві одночасно може діяти лише одне благословення від одного паладина.",
        [1042] = "Зцілює дружню ціль на $s1.",
        [1044] = "Накладає на дружню ціль Благословення, що надає несприйнятливість до ефектів, які обмежують рух, протягом $d.  На гравцеві одночасно може діяти лише одне благословення від одного паладина.",
        [1054] = "Зачаровує зброю вогнем.",
        [1058] = "Зцілює ціль на $o1 протягом $d.",
        [1062] = "Приковує ціль до місця й завдає $o2 шкоди від сил природи протягом $d.  Завдана шкода може перервати ефект.  Одночасно ви можете $?s17245[утримувати в корінні до ${$17245m1+1} $ltarget:ціль:цілі;][утримувати в корінні лише 1 ціль].",
        [1064] = "Зцілює дружню ціль на $s1, а потім перескакує на додаткові цілі поблизу.  Якщо застосовано до члена групи, зцілення перескакуватиме лише на інших членів групи.  Кожен стрибок має $?a415096[65%][50%] ефективності попереднього.  Зцілює загалом $x1 цілей.",
        [1070] = "Навчає Чарівного вогню (ранг 3).",
        [1075] = "На дружній цілі виростають шипи, які завдають нападникам $s1 шкоди від сил природи, коли ті влучають у ціль.  Триває $d.",
        [1079] = "Завершальний прийом, що завдає періодичної шкоди.  Шкода збільшується за кожне очко серії та від вашої сили атаки:\r\n   1 очко  : ${6*($m1+$b1)} шкоди протягом $d.\r\n   2 очки: ${6*($m1+2*$b1)} шкоди протягом $d.\r\n   3 очки: ${6*($m1+3*$b1)} шкоди протягом $d.\r\n   4 очки: ${6*($m1+4*$b1)} шкоди протягом $d.\r\n   5 очок: ${6*($m1+5*$b1)} шкоди протягом $d.",
        [1082] = "Дряпає ворога, завдаючи $s2% звичайної шкоди плюс $s1. Дає $s3 $lpoint:очко:очки; серії.",
        [1084] = "Уражає ціль, завдаючи $s1 шкоди від вогню.",
        [1086] = "Захищає заклинача, збільшуючи броню на $s1, опір тіні на $s2 та відновлення здоров’я на $s3 здоров’я кожні 5 с протягом $d.",
        [1088] = "Посилає у ворога тіньову стрілу, що завдає $s1 шкоди від тіні.",
        [1089] = "Навчає Тіньової стріли (ранг 4).",
        [1090] = "Присипляє ворожу ціль на час до $d.  Будь-яка завдана шкода пробуджує ціль.  Одночасно може спати лише одна ціль.",
        [1094] = "Обпалює ворога, завдаючи ${$m2*$<mult>} шкоди від вогню, а потім ще $o1 шкоди від вогню протягом $d.",
        [1096] = "Уражає ціль, завдаючи $s1 шкоди від вогню.",
        [1098] = "Підкорює демона до $m1 рівня, змушуючи його виконувати ваші накази.  Поки демон підкорений, час між його атаками збільшено на $s2%, а швидкість застосування заклинань зменшено на $s3%.  Триває до $d.  Повторне підкорення того самого демона з кожною спробою ускладнює контроль.",
        [1101] = "Навчає Переливання мани.",
        [1105] = "Навчає Печатки мудрості (ранг 3).",
        [1106] = "Посилає у ворога тіньову стрілу, що завдає $s1 шкоди від тіні.",
        [1107] = "Навчає Скверни (ранг 1).",
        [1108] = "Зменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [1109] = "Навчає Прокляття слабкості (ранг 2).",
        [1114] = "Збільшує шанс ухилення на $s1%.",
        [1120] = "Висмоктує душу цілі, завдаючи $o2 шкоди від тіні протягом $d. Нетруді цілі, уражені Висмоктуванням душі, можуть дати вам уламок душі. Нетруді цілі, вбиті Висмоктуванням душі, завжди дають уламок душі. Уламки душі потрібні для інших заклинань.",
        [1122] = "Викликає метеор із Крутіжу Порожнечі, що завдає $22699s1 шкоди від вогню та приголомшує всіх ворогів у ділянці на $20310d.  З кратера постає Інфернал, підкорений заклиначу на $20882d.  Після втрати контролю Інфернала потрібно Підкорити, щоб зберегти контроль.  Можна використовувати лише просто неба.",
        [1124] = "Уражає всіх ворогів у радіусі 10 ярдів, завдаючи $s1 шкоди від полум’я.",
        [1126] = "Збільшує броню дружньої цілі на $s1 протягом $d.",
        [1127] = "Відновлює $o1 здоров’я протягом $d.  Під час їжі потрібно залишатися сидячи.",
        [1129] = "Відновлює $o1 здоров’я протягом $d.  Під час їжі потрібно залишатися сидячи.",
        [1130] = "Накладає на ціль Мітку мисливця, збільшуючи силу атаки дальнього бою всіх нападників проти цієї цілі на $s2.  Крім того, мисливець завжди бачить ціль цієї здібності, навіть якщо вона входить у непомітність або стає невидимою.  Ціль також відображається на мінімапі.  Триває $d.",
        [1131] = "Відновлює $o1 здоров’я протягом $d.  Під час їжі потрібно залишатися сидячи.",
        [1133] = "Відновлює $o1 мани протягом $d.  Під час пиття потрібно залишатися сидячи.",
        [1135] = "Відновлює $o1 мани протягом $d.  Під час пиття потрібно залишатися сидячи.",
        [1137] = "Відновлює $o1 мани протягом $d.  Під час пиття потрібно залишатися сидячи.",
        [1138] = "Збільшує опір кризі та тіні на $s1 протягом $d.",
        [1139] = "Збільшує час між атаками цілі на $s2% і зменшує її швидкість руху на $s1% протягом $d.",
        [1152] = "Очищує дружню ціль, знімаючи $s1 ефект хвороби та $s2 ефект отрути.",
        [1159] = "Зцілює на $o1 протягом $d.",
        [1160] = "Зменшує силу атаки ближнього бою всіх ворогів у межах $a1 ярдів на $s1 протягом $d.",
        [1161] = "Змушує всіх ворогів поблизу в межах $a ярдів зосередити атаки на вас протягом $d.",
        [1181] = "Відновлює 12 здоров’я за хвилину.",
        [1182] = "Відновлює 24 здоров’я за хвилину.",
        [1183] = "Відновлює 36 здоров’я за хвилину.",
        [1243] = "Наповнює ціль силою, збільшуючи її витривалість на $s1 протягом $d.",
        [1244] = "Наповнює ціль силою, збільшуючи її витривалість на $s1 протягом $d.",
        [1245] = "Наповнює ціль силою, збільшуючи її витривалість на $s1 протягом $d.",
        [1299] = "Збільшує опір кризі на 4.",
        [1329] = "Миттєво атакує обома видами зброї, завдаючи $<percent>% шкоди від зброї плюс $5374s1 додаткової шкоди кожною зброєю.  Шкода по отруєних цілях збільшена на 20%.  Дає 2 очки серії.",
        [1366] = "Вивчає Виклик біса.",
        [1385] = "Вивчає Виклик пустотника.",
        [1403] = "Вивчає Виклик сукуби.",
        [1430] = "Зцілює ціль на $o1 протягом $d.",
        [1449] = "Спричиняє вибух таємної магії навколо заклинача, завдаючи $s1 шкоди від таємної магії всім цілям у межах $a1 ярдів.",
        [1454] = "Перетворює ${($m1+$SPI*1)*(1+$18182m1/100)} здоров’я на ${($m1+$SPI*1)*(1+$18182m1/100)} мани. Дух збільшує перетворену кількість.",
        [1455] = "Перетворює ${($m1+$SPI*1)*(1+$18182m1/100)} здоров’я на ${($m1+$SPI*1)*(1+$18182m1/100)} мани. Дух збільшує перетворену кількість.",
        [1456] = "Перетворює ${($m1+$SPI*1)*(1+$18182m1/100)} здоров’я на ${($m1+$SPI*1)*(1+$18182m1/100)} мани. Дух збільшує перетворену кількість.",
        [1459] = "Збільшує інтелект цілі на $s1 протягом $d.",
        [1460] = "Збільшує інтелект цілі на $s1 протягом $d.",
        [1461] = "Збільшує інтелект цілі на $s1 протягом $d.",
        [1462] = "Збирає відомості про вибраного звіра.  Підказка покаже шкоду, здоров’я, броню, особливі опори та раціон.",
        [1463] = "Поглинає $s1 фізичної шкоди, натомість витрачаючи ману.  Витрачає $e мани за кожну поглинуту одиницю шкоди.  Триває $d.",
        [1464] = "Завдає супротивнику удару, спричиняючи шкоду від зброї плюс $s1.",
        [1494] = "Показує на мінімапі місцезнаходження всіх звірів поблизу.  Одночасно може діяти лише один вид вистеження.",
        [1495] = "Контратакує ворога, завдаючи шкоди від зброї ближнього бою плюс $s1. Можна виконати лише після ухилення.",
        [1499] = "Встановлює крижану пастку, яка заморожує першого ворога, що наблизиться, і не дає йому діяти до $3355d.  Будь-яка шкода розіб’є кригу. Пастка існує $d. Одночасно може бути активна лише одна крижана пастка.",
        [1510] = "Безперервно обстрілює вибрану ділянку градом боєприпасів, завдаючи ворожим цілям у межах $a1 ярдів $1279721s1 шкоди від таємної магії кожні $t3 с протягом $d.",
        [1513] = "Лякає звіра, змушуючи його тікати в страху до $d.  Завдана шкода може перервати ефект.  Одночасно можна налякати лише одного звіра.",
        [1515] = "Починає приручення звіра, щоб зробити його вашим супутником.  Поки ви зосереджені на прирученні протягом $d, ваша броня зменшена на $s3%.  Якщо ви з будь-якої причини втратите увагу звіра, приручення провалиться.  Після приручення звір буде дуже нещасним і нелояльним.  Негайно нагодуйте вихованця, щоб підняти йому настрій.",
        [1516] = "Миттєво стріляє зі зброї, завдаючи $s1 додаткової шкоди.",
        [1528] = "Звільняє вашого господаря від будь-яких пут.",
        [1538] = "Заряджає Жезл Гелькулара під час використання біля трьох ритуальних вогнищ.",
        [1543] = "Виявляє всіх прихованих і невидимих ворогів у межах $a1 ярдів від вибраної ділянки протягом $d.",
        [1557] = "Збільшує швидкість руху на $s1",
        [1599] = "Збільшує опір вогню на 4.",
        [1608] = "Потужна атака, що збільшує шкоду в ближньому бою на $s1 і створює багато загрози.",
        [1630] = "Швидкість атаки збільшено на $s1%\r\nШвидкість руху збільшено на $s2%",
        [1671] = "Б’є ціль щитом, завдаючи $s2 шкоди.  Також перериває застосування заклинань і не дозволяє застосовувати заклинання цієї школи протягом $d.",
        [1672] = "Б’є ціль щитом, завдаючи $s2 шкоди.  Також перериває застосування заклинань і не дозволяє застосовувати заклинання цієї школи протягом $d.",
        [1680] = "У вихорі сталі ви атакуєте до $i ворогів у межах $a1 ярдів, завдаючи кожному шкоди від обох видів зброї ближнього бою.",
        [1698] = "Швидка розмашиста атака в конусі перед воїном, що вражає всіх ворогів поблизу, завдаючи шкоди від зброї плюс $s1.",
        [1706] = "Дозволяє заклиначу левітувати за кілька футів над землею. Під час левітації ви падаєте повільніше й можете пересуватися над водою. Використання верхової тварини або отримання шкоди скасовує ефект. Триває $d.",
        [1714] = "Змушує ціль говорити демонічною мовою, збільшуючи час застосування всіх заклинань на $s1%. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника. Триває $d.",
        [1715] = "Калічить ворога, завдаючи $s1 шкоди та зменшуючи його швидкість руху на $s2% протягом $d.",
        [1719] = "Воїн отримує на $s1% більше шансу критичного удару та несприйнятливість до ефектів Страху на наступні $d, але вся отримана шкода збільшується на $s2%.",
        [1725] = "Кидає відволікаючий предмет, привертаючи увагу всіх ворогів поблизу й зменшуючи їхню здатність виявляти непомітність так, ніби вони на ${$m2/-5} $Llevel:рівень:рівні; нижчі, протягом $s1 секунд. Не перериває непомітність.",
        [1735] = "Друїд реве, зменшуючи силу атаки ближнього бою ворогів поблизу на $s1.  Триває $d.",
        [1742] = "Пригинається, не завдаючи шкоди, але зменшуючи вашу загрозу, через що ворог рідше атакує вас.",
        [1752] = "Миттєвий удар, що завдає $s1 додаткової шкоди понад звичайну шкоду від зброї.  Дає $s2 $lpoint:очко:очки; серії.",
        [1753] = "Пригинається, не завдаючи шкоди, але зменшуючи вашу загрозу, через що ворог рідше атакує вас.",
        [1754] = "Пригинається, не завдаючи шкоди, але зменшуючи вашу загрозу, через що ворог рідше атакує вас.",
        [1755] = "Пригинається, не завдаючи шкоди, але зменшуючи вашу загрозу, через що ворог рідше атакує вас.",
        [1756] = "Пригинається, не завдаючи шкоди, але зменшуючи вашу загрозу, через що ворог рідше атакує вас.",
        [1757] = "Миттєвий удар, що завдає $s1 додаткової шкоди понад звичайну шкоду від зброї.  Дає $s2 $lpoint:очко:очки; серії.",
        [1758] = "Миттєвий удар, що завдає $s1 додаткової шкоди понад звичайну шкоду від зброї.  Дає $s2 $lpoint:очко:очки; серії.",
        [1759] = "Миттєвий удар, що завдає $s1 додаткової шкоди понад звичайну шкоду від зброї.  Дає $s2 $lpoint:очко:очки; серії.",
        [1760] = "Миттєвий удар, що завдає $s1 додаткової шкоди понад звичайну шкоду від зброї.  Дає $s2 $lpoint:очко:очки; серії.",
        [1766] = "Швидкий удар ногою, що завдає одній цілі $s1 шкоди.  Також перериває застосування заклинань і не дозволяє застосовувати заклинання цієї школи протягом $d.",
        [1767] = "Швидкий удар ногою, що завдає одній цілі $s1 шкоди.  Також перериває застосування заклинань і не дозволяє застосовувати заклинання цієї школи протягом $d.",
        [1768] = "Швидкий удар ногою, що завдає одній цілі $s1 шкоди.  Також перериває застосування заклинань і не дозволяє застосовувати заклинання цієї школи протягом $d.",
        [1769] = "Швидкий удар ногою, що завдає одній цілі $s1 шкоди.  Також перериває застосування заклинань і не дозволяє застосовувати заклинання цієї школи протягом $d.",
        [1776] = "Завдає $s1 шкоди, припиняє вашу атаку та виводить ціль із ладу на $d.  Ціль має дивитися на вас.  Будь-яка отримана шкода перерве ефект.  Дає $s2 $lpoint:очко:очки; серії.",
        [1777] = "Завдає $s1 шкоди, припиняє вашу атаку та виводить ціль із ладу на $d.  Ціль має дивитися на вас.  Будь-яка отримана шкода перерве ефект.  Дає $s2 $lpoint:очко:очки; серії.",
        [1784] = "Дозволяє розбійнику крастися, але зменшує вашу швидкість на $s3%.  Триває, доки не буде скасовано.",
        [1785] = "Дозволяє розбійнику крастися, але зменшує вашу швидкість на $s3%.  Триває, доки не буде скасовано.",
        [1786] = "Дозволяє розбійнику крастися, але зменшує вашу швидкість на $s3%.  Триває, доки не буде скасовано.",
        [1787] = "Дозволяє розбійнику крастися, але зменшує вашу швидкість на $s3%.  Триває, доки не буде скасовано.",
        [1804] = "Дозволяє відмикати замкнені скрині та двері.",
        [1822] = "Роздирає ціль, завдаючи $s1 шкоди та додатково $o2 шкоди протягом $d.  Дає $s3 $lpoint:очко:очки; серії.",
        [1823] = "Роздирає ціль, завдаючи $s1 шкоди та додатково $o2 шкоди протягом $d.  Дає $s3 $lpoint:очко:очки; серії.",
        [1824] = "Роздирає ціль, завдаючи $s1 шкоди та додатково $o2 шкоди протягом $d.  Дає $s3 $lpoint:очко:очки; серії.",
        [1825] = "Передає керування вашим вихованцем іншому гравцеві.",
        [1833] = "Приголомшує ціль на $d.  Потрібно перебувати в непомітності.  Дає $s2 $lpoint:очко:очки; серії.",
        [1834] = "Збільшує швидкість руху",
        [1842] = "Підкрадіться до пастки, щоб знешкодити її.  Не підходьте надто близько, інакше пастка спрацює.",
        [1850] = "Збільшує швидкість руху на $s1% протягом $d.  Не перериває крадькування.",
        [1852] = "Це інструмент ГМ для накладання мовчанки на гравців.  Заклинання лише слугує візуальним індикатором, щоб гравець і ГМ знали, що гравець зараз знемовлений.",
        [1853] = "Провокує ціль, підвищуючи ймовірність того, що істота зосередить атаки на вас.",
        [1856] = "Дозволяє розбійнику зникнути з поля зору, входячи в покращену непомітність на $11327d. Також знімає ефекти, що обмежують рух.",
        [1857] = "Дозволяє розбійнику зникнути з поля зору, входячи в покращену непомітність на $11329d.  Також знімає ефекти, що обмежують рух. Ефективніше за Зникнення (ранг 1).",
        [1860] = "Зменшує шкоду від падіння.",
        [1866] = "Миттєвий удар, що завдає $m2% шкоди від зброї плюс $s1 додаткової шкоди від святості.",
        [1905] = "Дозволяє Вартовому Анубісата передати свою особливу силу всім Вартовим Анубісата поблизу",
