        [7301] = "Збільшує броню на $s1.  Коли ворог влучає в заклинача, його швидкість руху може зменшитися на $6136s1%, а час між атаками — збільшитися на $6136s2% протягом $6136d.  Одночасно на магові може діяти лише одне заклинання броні.  Триває $d.",
        [7302] = "Збільшує броню на $s1 і опір кризі на $s3. Якщо ворог вдарить заклинача, його швидкість руху може зменшитися на $7321s1%, а час між атаками — збільшитися на $7321s2% протягом $7321d. Одночасно на магові може діяти лише одне закляття броні. Триває $d.",
        [7320] = "Збільшує броню на $s1 і опір кризі на $s3. Якщо ворог вдарить заклинача, його швидкість руху може зменшитися на $7321s1%, а час між атаками — збільшитися на $7321s2% протягом $7321d. Одночасно на магові може діяти лише одне закляття броні. Триває $d.",
        [7322] = "Запускає у ворога крижану стрілу, що завдає від ${$m2$*$<frostdamage>} до ${$M2*$<frostdamage>} шкоди від криги та зменшує швидкість руху на $s1% протягом $d.",
        [7327] = "Навчає «Печатки мудрості» (Ранг 1).",
        [7328] = "Повертає мертвого гравця до життя з $s1 здоров’я та $q1 мани.  Не можна застосувати в бою.",
        [7331] = "Зцілює паладина та учасників групи поблизу на $s1 з кожним тактом.",
        [7342] = "Завдає ворогам у конусі перед заклиначем звичайної шкоди та ще $s1.",
        [7353] = "Збільшує ваш дух на $s1.",
        [7357] = "Завдає ворогові $s3 шкоди від сил природи кожні $t3 сек., збільшуючи час між його атаками на $s1% і зменшуючи швидкість руху на $s2% на $d.",
        [7358] = "Збільшує ваш дух на $s1.",
        [7359] = "Розпалює багаття, що збільшує дух усіх поблизу на 8 і дає змогу готувати їжу.",
        [7363] = "Збільшує дух учасників групи поблизу на $M1.",
        [7365] = "Кидає у ворога пляшку отрути, завдаючи $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [7366] = "Приймає агресивну стійку, що генерує лють, коли воїн вражає супротивника. Триває $d.",
        [7367] = "Завдає ворогові $s1 шкоди від сил природи кожні $t1 сек. і збільшує отримувану ним фізичну шкоду на $s2 протягом $d.",
        [7369] = "Розмашиста атака, що завдає цілі шкоди від зброї плюс $s1 і вражає другого ворога поблизу.",
        [7371] = "Кидається на ворога, знерухомлює його на $7922d і додає $s2 сили атаки ближнього бою до наступної атаки вепра.",
        [7372] = "Калічить ворога, завдаючи $s1 шкоди та зменшуючи його швидкість руху на $s2% протягом $d.",
        [7373] = "Калічить ворога, завдаючи $s1 шкоди та зменшуючи його швидкість руху на $s2% протягом $d.",
        [7376] = "Зменшує шкоду від усіх джерел на $s1%. Зменшує завдану шкоду на $s2%.\r\nЗбільшує всю створювану загрозу на $?s12792[${($7376s3+100)*($12792s1/100+1)-100)}.1%][$7376s3%].",
        [7379] = "Миттєво контратакує ворога, завдаючи $s1 шкоди й створюючи значну загрозу. «Помста» можлива лише після блокування, ухилення або парирування.",
        [7381] = "Збільшує шанс критичного удару на $s1%. Збільшує всю отримувану шкоду на $s2%.",
        [7384] = "Миттєво долає захист ворога, завдаючи шкоди зброєю та ще $s1. Можна застосувати лише після ухилення цілі. «Перевагу» не можна заблокувати, уникнути чи спарирувати.",
        [7386] = "Розколює броню цілі, зменшуючи її на $s1 за кожен ефект «Розкол броні» та створюючи значну загрозу. Накладається до 5 разів. Триває $d.",
        [7389] = "Збільшує швидкість атак вихованця заклинача на $s1% на $d.",
        [7393] = "Зцілює ціль на $s1",
        [7394] = "Завдає звичайної шкоди та додатково $s1 усім ворогам поблизу.",
        [7395] = "Завдає $s1 шкоди від вогню всім ворогам у вибраній зоні.",
        [7396] = "Збільшує швидкість атаки на $s1% протягом $d.",
        [7399] = "Жахає ворога, змушуючи його тікати від страху протягом $d. Одночасно можна налякати лише 1 ціль.",
        [7400] = "Глузлива атака, що завдає $s1 шкоди, створює помірну загрозу та змушує ціль зосередити атаки на вас протягом $d.",
        [7402] = "Глузлива атака, що завдає $s1 шкоди, створює помірну загрозу та змушує ціль зосередити атаки на вас протягом $d.",
        [7405] = "Розколює броню цілі, зменшуючи її на $s1 за кожен ефект «Розкол броні» та створюючи значну загрозу. Накладається до 5 разів. Триває $d.",
        [7407] = "Збільшує шкоду гострої зброї на 2 протягом 30 хвилин.",
        [7411] = "Дає зачаровувачу змогу зачаровувати базові предмети до максимальної навички 75. Потребує пилу й есенцій, отриманих розпиленням магічних предметів.",
        [7412] = "Дає зачаровувачу змогу зачаровувати зброю та обладунки до максимальної навички 150.",
        [7413] = "Дає зачаровувачу змогу накладати майстерні чари на зброю та обладунки до максимальної навички 225.",
        [7418] = "Назавжди зачаровує наручі, збільшуючи витривалість носія на $7419s1.",
        [7420] = "Назавжди зачаровує нагрудний обладунок, збільшуючи витривалість носія на $7419s1.",
        [7426] = "Зачаровує нагрудний обладунок, даючи 2% шанс при отриманні удару поглинути 10 шкоди. Спрацьовує не частіше ніж раз на 5 сек.",
        [7428] = "Назавжди зачаровує наручі, збільшуючи навичку захисту носія на 3.",
        [7434] = "Насичує зброю ближнього бою, додаючи 4 шкоди проти звірів на 30 хвилин.",
        [7439] = "Насичує плащ, додаючи 4 опору всій магії на 60 хвилин.",
        [7443] = "Назавжди зачаровує нагрудний обладунок, збільшуючи інтелект носія на $7442s1.",
        [7448] = "Насичує нагрудний обладунок на 60 хвилин, даючи 5% шанс при отриманні удару поглинути 25 шкоди.",
        [7451] = "Насичує нагрудний обладунок відновлювальними властивостями, збільшуючи дух носія на 3 протягом 60 хвилин.",
        [7454] = "Назавжди зачаровує плащ, збільшуючи опір усім школам магії на $7452s1.",
        [7457] = "Назавжди зачаровує наручі, збільшуючи витривалість носія на 3.",
