        [7588] = "Посилає у ворога стрілу темної магії, завдаючи $s1 шкоди від тіні.",
        [7597] = "Збільшує шанс критичного удару атаками ближнього бою на ${$s1}.1%.",
        [7598] = "Збільшує шанс критичного удару атаками ближнього бою на ${$s1}.1%.",
        [7599] = "Збільшує шанс критичного удару атаками ближнього бою на ${$s1}.1%.",
        [7600] = "Збільшує шанс критичного удару атаками ближнього бою на ${$s1}.1%.",
        [7617] = "При отриманні удару в бою має $h% шанс завдати нападникові $16783s1 шкоди від тіні.",
        [7619] = "При отриманні удару в бою має $h% шанс завдати нападникові $16784s1 шкоди від тіні.",
        [7620] = "Спорядіть вудку й знайдіть водойму для риболовлі. Клацніть правою кнопкою миші на поплавці, коли він сіпнеться, щоб упіймати рибу. Вища навичка збільшує шанс успішної риболовлі у високорівневих місцевостях.\r\n",
        [7621] = "Перетворює ворога на Ненажеру з Тіньового Ікла та підкорює його волі заклинача на $d.",
        [7638] = "Зцілює союзника на $s1 через $t1 сек.",
        [7641] = "Посилає у ворога тіньову стрілу, що завдає $s1 шкоди від тіні.",
        [7645] = "Підкоряє гуманоїда-ворога до $s1 рівня на $d, але збільшує час між його атаками на $s2%.",
        [7646] = "Зменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [7648] = "Оскверняє ціль, завдаючи $o1 шкоди від тіні протягом $d.",
        [7651] = "Переносить $s1 здоров’я кожні $t1 сек. від цілі до заклинача. Триває $d.\r\n",
        [7655] = "Проклинає ворога, зменшуючи завдану ним фізичну шкоду на $8320s1 і магічну шкоду на $8320s2 протягом $8320d. Також прокляття збільшує фізичну шкоду заклинача на $7657s1 і його магічну шкоду на $7657s2 протягом $7657d.",
        [7658] = "Проклинає ціль безрозсудністю, зменшуючи її броню на $s2 протягом $d. Прокляті вороги не тікатимуть і ігноруватимуть ефекти Страху та Жаху. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [7659] = "Проклинає ціль безрозсудністю, зменшуючи її броню на $s2 протягом $d. Прокляті вороги не тікатимуть і ігноруватимуть ефекти Страху та Жаху. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [7669] = "Знімає Прокляття Воронячого Пазура.",
