        [8103] = "Вражає ціль на $s1 шкоди від тіні та створює значну загрозу.",
        [8104] = "Вражає ціль на $s1 шкоди від тіні та створює значну загрозу.",
        [8105] = "Вражає ціль на $s1 шкоди від тіні та створює значну загрозу.",
        [8106] = "Вражає ціль на $s1 шкоди від тіні та створює значну загрозу.",
        [8112] = "Збільшує дух цілі на $s1 на $d.",
        [8113] = "Збільшує дух цілі на $s1 на $d.",
