        [8115] = "Збільшує спритність цілі на $s1 на $d.",
        [8116] = "Збільшує спритність цілі на $s1 на $d.",
        [8117] = "Збільшує спритність цілі на $s1 на $d.",
        [8118] = "Збільшує силу цілі на $s1 на $d.",
        [8119] = "Збільшує силу цілі на $s1 на $d.",
        [8120] = "Збільшує силу цілі на $s1 на $d.",
        [8121] = "Навчає «Захисної стійки», «Розколу броні» (Ранг 1) і «Провокації» (Ранг 1).",
        [8122] = "Заклинач видає психічний крик, змушуючи $i ворогів у межах $a1 м тікати протягом $d. Завдана шкода може перервати ефект.",
        [8124] = "Заклинач видає психічний крик, змушуючи $i ворогів у межах $a1 м тікати протягом $d. Завдана шкода може перервати ефект.",
        [8129] = "Висмоктує з цілі $s1 мани. За кожну висмоктану одиницю мани ціль отримує 0.5 шкоди від тіні.",
        [8131] = "Висмоктує з цілі $s1 мани. За кожну висмоктану одиницю мани ціль отримує 0.5 шкоди від тіні.",
        [8134] = "Заклинача оточують $n куль блискавки. Коли заклинача вражає закляття, атака ближнього чи дальнього бою, нападник отримує $26369s1 шкоди від сил природи. Це витрачає одну кулю блискавки. Одна куля може спрацювати лише раз на кілька секунд. Триває $d.",
        [8137] = "Збільшує фізичну шкоду, яку отримує ворог, на $s1% на $d.",
        [8138] = "Зменшує витривалість ворога на $s1 протягом $d.",
        [8139] = "Зменшує інтелект ворога на $s1, а дух — на $s2 на $d.",
        [8140] = "Зменшує швидкість застосування заклинань ворога на $s1% протягом $d.",
        [8141] = "Використовує святий еліксир, щоб зцілити заклинача на $s1.",
        [8142] = "Завдає фізичної шкоди ворогам поблизу, збиваючи їх з ніг і знерухомлюючи на $d.",
        [8143] = "Прикликає Тотем тремтіння з $s1 здоров’я біля ніг заклинача. Він стрясає землю, знімаючи страх, причарування та сон з учасників групи в межах $8146a1 м. Триває $d.",
        [8147] = "Завдає ворогам поблизу $s1 шкоди від сил природи, збільшуючи час між їхніми атаками на $s3% і зменшуючи швидкість руху на $s2% на $d.",
        [8148] = "Завдає $s1 шкоди від сил природи будь-якій істоті, що атакує учасника групи поблизу. На гравцеві одночасно може діяти лише одна аура від одного паладина. Аура триває $d.",
        [8150] = "Завдає ворогам поблизу $s1 шкоди від сил природи та приголомшує їх на $d.",
        [8151] = "Під час атаки з непомітності завдає ворогові звичайної шкоди та ще $s1, приголомшуючи ціль на $d.",
        [8152] = "Переводить заклинача в непомітність, але зменшує швидкість руху на $s2%. Триває до скасування.",
        [8153] = "Перетворює друїда на летючу форму, збільшуючи швидкість руху.",
        [8154] = "Прикликає Тотем кам’яної шкіри з $s1 здоров’я біля ніг заклинача. Тотем захищає учасників групи в межах $8156a1 м, зменшуючи отримувану фізичну шкоду на $8156s1. Триває $d.",
        [8155] = "Прикликає Тотем кам’яної шкіри з $s1 здоров’я біля ніг заклинача. Тотем захищає учасників групи в межах $8157a1 м, зменшуючи отримувану фізичну шкоду на $8157s1. Триває $d.",
        [8160] = "Прикликає Тотем сили землі з $s1 здоров’я біля ніг заклинача. Тотем збільшує силу учасників групи в межах $8162a1 м на $8162s1. Триває $d.",
        [8161] = "Прикликає Тотем сили землі з $s1 здоров’я біля ніг заклинача. Тотем збільшує силу учасників групи в межах $8163a1 м на $8163s1. Триває $d.",
        [8166] = "Прикликає Тотем очищення від отрути з $s1 здоров’я біля ніг заклинача, який намагається зняти 1 ефект отрути з учасників групи в межах $8168a1 м кожні $8167t1 секунд. Триває $d.",
        [8170] = "Прикликає Тотем очищення від хвороб з $s1 здоров’я біля ніг заклинача, який намагається зняти 1 ефект хвороби з учасників групи в межах $8171a1 м кожні $8172t1 секунд. Триває $d.",
        [8176] = "Прикликає скверногона-вартового, який захищатиме вас протягом $d.",
        [8177] = "Прикликає Тотем заземлення з $s1 здоров’я біля ніг заклинача, який кожні $8179t1 секунд перенаправляє на себе одне шкідливе закляття, спрямоване на учасника групи поблизу. Не перенаправляє закляття по області. Триває $d.",
        [8181] = "Прикликає Тотем опору кризі з $s1 здоров’я біля ніг заклинача на $d. Тотем збільшує опір кризі учасників групи й рейду в межах $8182a1 м на $8182s1.",
        [8184] = "Прикликає Тотем опору вогню з $s1 здоров’я біля ніг заклинача на $d, який збільшує опір вогню учасників групи й рейду в межах $8185a1 м на $8185s1.",
        [8190] = "Прикликає Тотем магми з $s1 здоров’я біля ніг заклинача на $d, який завдає істотам у межах $8187a1 м $8187s1 шкоди від вогню кожні $8188t1 секунд.",
        [8191] = "Спалах енергії наповнює заклинача, збільшуючи $ghis:her; шкоду на $s1 і броню на $s2 на $d.",
        [8192] = "Заспокоює ціль, зменшуючи відстань, з якої вона атакуватиме вас, на $s1 ярдів.  Діє лише на гуманоїдів рівня $v або нижче.  Триває $d.",
        [8198] = "Вражає ворогів поблизу громом, збільшуючи час між їхніми атаками на $s2% на $d і завдаючи $s1 шкоди. Вражає до $i цілей.",
        [8199] = "Навчає «Тотема кам’яної шкіри» (Ранг 1).",
        [8200] = "Навчає «Тотема пекучого полум’я» (Ранг 1).",
        [8201] = "Навчає «Тотема цілющого потоку» (Ранг 1).",
        [8202] = "Дає шаманові змогу бачити духів стихій.",
        [8204] = "Вражає ворогів поблизу громом, збільшуючи час між їхніми атаками на $s2% на $d і завдаючи $s1 шкоди. Вражає до $i цілей.",
        [8205] = "Вражає ворогів поблизу громом, збільшуючи час між їхніми атаками на $s2% на $d і завдаючи $s1 шкоди. Вражає до $i цілей.",
        [8209] = "Створює $s1 Вибухову вівцю, яка $lcharges:charge; до найближчого $lenemy:enemies; і $lexplodes:explode;. Вибухові вівці нестабільні й самознищаться через $d.",
        [8210] = "Прикликає $s1 $lSavannah Cub:Savannah Cubs; на допомогу заклиначеві в бою на $d.",
        [8211] = "Вражає ворога антимановою стрілою, що перескакує на іншого ворога поблизу. За кожну поглинуту одиницю мани ціль отримує $e1 шкоди. Закляття вражає до $x1 цілей.",
        [8212] = "Ваш розмір збільшується, а сила зростає на $s1 відповідно до нового розміру. Триває $d.",
        [8213] = "З’їж мене.",
        [8227] = "Прикликає Тотем язика полум’я з $s1 здоров’я біля ніг заклинача. Тотем зачаровує вогнем зброю в основній руці всіх учасників групи в межах $8230a1 м. Кожен удар завдає від ${$8253m1/77*$<mult>-1} до ${$8253M1/25*$<mult>} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди за удар. Триває $d.",
        [8232] = "Насичує зброю шамана вітром. Кожен удар має 20% шанс надати $8233s2 додаткові $lattack:attacks; з $8233s1 додаткової сили атаки ближнього бою. На основній руці скасовує вашу особисту користь від Тотема люті вітру. Триває 60 хвилин.",
        [8235] = "Насичує зброю шамана вітром. Кожен удар має 20% шанс надати $8236s2 додаткові $lattack:attacks; з $8236s1 додаткової сили атаки ближнього бою. На основній руці скасовує вашу особисту користь від Тотема люті вітру. Триває 60 хвилин.",
        [8242] = "Завдає ворогові $s2 шкоди й приголомшує його на $d.",
        [8245] = "Зменшує броню ворогів поблизу на $s1 на $d.",
        [8246] = "Вражає ворога блискавкою, завдаючи $s1 шкоди від сил природи.",
        [8249] = "Прикликає Тотем язика полум’я з $s1 здоров’я біля ніг заклинача. Тотем посилює атаки ближнього бою всіх учасників групи в межах $8250a1 м. Кожен удар основною рукою завдає від ${$8248m1/77*$<mult>-1} до ${$8248M1/25*$<mult>} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди за удар. Триває $d.",
        [8255] = "Завдає ворогові та його найближчим союзникам звичайної шкоди й додатково $s1, вражаючи до $x1 цілей і збільшуючи час між їхніми атаками на $s2% на $d.",
        [8256] = "Завдає ворогу $s1 шкоди від сил природи кожні $t1 с протягом $d.",
        [8257] = "Завдає ворогові $s2 шкоди від сил природи, а потім ще $s1 шкоди кожні $t1 сек. протягом $d.",
        [8258] = "Надає учасникам групи поблизу $s1 додаткової броні на $d. На гравцеві одночасно може діяти лише одна аура від одного паладина.",
        [8259] = "Завдає звичайної шкоди та додатково $s1 усім ворогам поблизу.",
        [8260] = "Збільшує швидкість руху заклинача на $s1% на $d. і додає $s2 шкоди до його першої атаки.",
        [8262] = "Прикликає Тотем захисту від стихій біля ніг заклинача. Тотем існує $d. і збільшує опір шкідливій магії учасників групи поблизу.",
        [8264] = "Прикликає Тотем лавового струменя біля ніг заклинача. Тотем існує $d. і завдає ворогам поблизу $8265s1 шкоди від вогню кожні $8266t1 сек.",
        [8267] = "Зменшує інтелект ворогів поблизу на $s1 на $d.",
        [8269] = "Збільшує швидкість атак заклинача на $s2% і завдану ним фізичну шкоду на $s1 на $d.",
        [8270] = "Прикликає $s1 $lStone Rumbler:Stone Rumblers; супроводжувати заклинача, доки їх не відкличуть.",
        [8271] = "Прикликає $s1 $lWind Howler:Wind Howlers; супроводжувати заклинача, доки їх не відкличуть.",
        [8272] = "Зменшує швидкість застосування заклинань ворога на $s1% протягом $d.",
        [8274] = "Прикликає $s1 $lTamed Battleboar:Tamed Battleboars; супроводжувати заклинача, доки їх не відкличуть.",
        [8275] = "Завдає ворогові звичайної шкоди та додатково $s2, а потім ще $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [8276] = "Прикликає $s1 $lTamed Hyena:Tamed Hyenas; супроводжувати заклинача, доки їх не відкличуть.",
        [8277] = "Фізична шкода, яку завдає ціль, зменшується на $s1 на $d.",
        [8281] = "Завдає ворогам поблизу звичайної шкоди та ще $s1, не даючи їм застосовувати закляття протягом $d.",
        [8282] = "Збільшує отримувану ворогом фізичну шкоду на $s1 протягом $d.",
        [8283] = "Для використання на Ховрасі-винюхувачі.",
        [8285] = "Завдає ворогам поблизу звичайної шкоди та ще $s1, приголомшуючи їх на $d.",
        [8286] = "Прикликає $s1 $lBoar Spirit:Boar Spirits; на допомогу заклиначеві в бою на $d.",
        [8288] = "Висмоктує душу цілі, завдаючи $o2 шкоди від тіні протягом $d. Нетруді цілі, уражені Висмоктуванням душі, можуть дати вам уламок душі. Нетруді цілі, вбиті Висмоктуванням душі, завжди дають уламок душі. Уламки душі потрібні для інших заклинань.",
        [8289] = "Висмоктує душу цілі, завдаючи $o2 шкоди від тіні протягом $d. Нетруді цілі, уражені Висмоктуванням душі, можуть дати вам уламок душі. Нетруді цілі, вбиті Висмоктуванням душі, завжди дають уламок душі. Уламки душі потрібні для інших заклинань.",
        [8292] = "Вражає ворога блискавкою, що перескакує на іншого ворога поблизу. Закляття вражає до $x1 цілей, завдаючи кожній $s1 шкоди від сил природи.",
        [8293] = "Створює хмару блискавок на $d., що вражає всіх ворогів у вибраній зоні на $s1 шкоди від сил природи та завдає ще $s2 шкоди кожні $t2 сек.",
        [8296] = "Дає шахтарю змогу виплавити 10 шматків мідної руди в 10 мідних зливків. Для виплавки міді потрібне горно.",
        [8312] = "Знерухомлює ціль на $d.",
        [8313] = "Отруює ціль, завдаючи $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [8316] = "Оточує ціль вогняним щитом.  Кожен удар по цілі завдає нападнику $s1 шкоди від вогню.  Триває $d.  Ваш вихованець не може застосувати Вогняний щит на себе.",
        [8317] = "Оточує ціль вогняним щитом.  Кожен удар по цілі завдає нападнику $s1 шкоди від вогню.  Триває $d.  Ваш вихованець не може застосувати Вогняний щит на себе.",
        [8331] = "Динаміт для неінженерів, який майже завжди долітає до цілі! Завдає $s1 шкоди від вогню в радіусі 5 м.",
        [8332] = "Завдає $s1 шкоди від вогню в радіусі 5 ярдів.",
        [8333] = "Завдає $s1 шкоди від вогню в радіусі 5 ярдів.",
        [8342] = "Кабелі запуску іноді можуть ударом струму повернути мертвого гравця до життя. Не можна використовувати в бою.",
        [8344] = "Дає змогу ненадовго контролювати механічну ціль. Може не спрацювати, лише знерухомити механізм або дуже-дуже його розлютити. Гномська інженерія у всій красі.",
        [8348] = "Зцілює носія на $o1 протягом $d.",
        [8355] = "Завдає ворогові звичайної шкоди та ще $s1, але лише під час атаки ззаду.",
        [8358] = "Відновлює ману заклинача.",
        [8361] = "Робить заклинача несприйнятливим до всіх атак і заклять на $d.",
        [8362] = "Зцілює союзника на $s1 кожні $t1 сек. протягом $d.",
        [8363] = "Завдає ворогові звичайної шкоди та додатково $s2, а потім ще $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [8364] = "Викликає хуртовину на $d., що завдає всім ворогам у вибраній зоні $s1 шкоди від криги кожні $t1 сек.",
        [8365] = "Збільшує фізичну шкоду союзника на $s1 на $d.",
        [8372] = "Прикликає $s1 $lAqua Guardian:Aqua Guardians; супроводжувати заклинача, доки їх не відкличуть.",
        [8374] = "Завдає лютого дугового удару, вражаючи ворогів у конусі перед заклиначем.",
        [8375] = "Назавжди зачаровує рукавиці, додаючи +$13838s1 до навички гірництва.",
