        [11675] = "Висмоктує душу цілі, завдаючи $o2 шкоди від тіні протягом $d. Нетруді цілі, уражені Висмоктуванням душі, можуть дати вам уламок душі. Нетруді цілі, вбиті Висмоктуванням душі, завжди дають уламок душі. Уламки душі потрібні для інших заклинань.",
        [11677] = "Обрушує вогняний дощ, що випалює ворогів у зоні дії, завдаючи ${4*$1282384m1} шкоди від вогню протягом $d.",
        [11678] = "Обрушує вогняний дощ, що випалює ворогів у зоні дії, завдаючи ${4*$1282385m1} шкоди від вогню протягом $d.",
        [11681] = "Завдає $s1 шкоди від вогню.",
        [11682] = "Завдає $s1 шкоди від вогню.",
        [11683] = "Підпалює ділянку навколо заклинача, завдаючи $s2 шкоди від вогню $ghimself:herself; і $11681s1 шкоди від вогню всім ворогам поблизу кожні $t2 с.  Триває $d.",
        [11684] = "Підпалює ділянку навколо заклинача, завдаючи $s2 шкоди від вогню $ghimself:herself; і $11682s1 шкоди від вогню всім ворогам поблизу кожні $t2 с.  Триває $d.",
        [11687] = "Перетворює ${($m1+$SPI*1)*(1+$18182m1/100)} здоров’я на ${($m1+$SPI*1)*(1+$18182m1/100)} мани. Дух збільшує перетворену кількість.",
        [11688] = "Перетворює ${($m1+$SPI*1)*(1+$18182m1/100)} здоров’я на ${($m1+$SPI*1)*(1+$18182m1/100)} мани. Дух збільшує перетворену кількість.",
        [11689] = "Перетворює ${($m1+$SPI*1)*(1+$18182m1/100)} здоров’я на ${($m1+$SPI*1)*(1+$18182m1/100)} мани. Дух збільшує перетворену кількість.",
        [11693] = "Відновлює вихованцеві заклинача $s1 здоров’я щосекунди протягом $d, доки заклинач підтримує заклинання. Створює менше загрози.",
        [11694] = "Відновлює вихованцеві заклинача $s1 здоров’я щосекунди протягом $d, доки заклинач підтримує заклинання. Створює менше загрози.",
        [11695] = "Відновлює вихованцеві заклинача $s1 здоров’я щосекунди протягом $d, доки заклинач підтримує заклинання. Створює менше загрози.",
        [11699] = "Переносить $s1 здоров’я кожні $t1 сек. від цілі до заклинача. Триває $d.\r\n",
