        [12687] = "Дозволяє знаходити додаткові самоцвіти в залізних, олов’яних і мідних жилах.",
        [12691] = "Дозволяє знаходити додаткові самоцвіти в мітрилових, залізних, олов’яних і мідних жилах.",
        [12693] = "Викрадає $s1 здоров’я у ворога.",
        [12699] = "Викликає дух верескуна з тіла долинного верескуна.",
        [12700] = "Збільшує шанс критичного удару сокирами й древковою зброєю на $s1%.",
        [12707] = "Збільшує тривалість Збивання на $/1000;s2 с. і дає йому $s1% шанс ошелешити ціль.",
        [12708] = "Надає Збиванню $s1% шанс ошелешити ціль.",
        [12709] = "Збирає радіоактивні опади.",
        [12710] = "Візуальний ефект вибуху самоцвітів під час події в Азшарі.",
        [12723] = "Ваші наступні $n замахів зброєю ближнього бою також уражають ще одного ворога поблизу.",
        [12731] = "Розколює землю й камінь, завдаючи $s1 фізичної шкоди. Завдає у $s2 рази більше шкоди Земним елементалям, големам і викуваним титанами.",
        [12732] = "Збільшує звичайне відновлення здоров’я та мани на 5.",
        [12733] = "Збільшує всі види опору на $s2 і надає несприйнятливість до Страху на $d.",
        [12734] = "Завдає фізичної шкоди ворогам поблизу й приголомшує їх на $d.",
        [12735] = "Використати, щоб наповнити Яйце Гаккара.",
        [12736] = "Мітриловий дракончик оживає й захищає вас протягом $d.",
        [12737] = "Завдає ворогам поблизу шкоди від криги й зменшує швидкість їхнього руху протягом $d.",
        [12738] = "Збільшує всю шкоду, яку отримує ворог, на $s1% протягом $d.",
        [12739] = "Жбурляє у ворога стрілу темної магії, завдаючи шкоди від тіні.",
        [12741] = "Зменшує фізичну шкоду, яку завдають вороги поблизу, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [12742] = "Обпалює ворога, а потім завдає додаткової шкоди від вогню кожні $t1 сек. протягом $d.",
        [12745] = "Вражає ворогів поблизу антимановими стрілами. За кожну поглинуту в цілі одиницю мани ця ціль отримує $e1 шкоди.",
        [12746] = "Викликає $s1 $lVoidwalker:Voidwalkers; супроводжувати заклинача, доки їх не буде відпущено.",
        [12747] = "Обплутує ворога корінням, завдаючи шкоди від сил природи кожні $t2 с. і знерухомлюючи його на час до $d.",
        [12748] = "Завдає ворогам поблизу шкоди від криги, знерухомлюючи їх на час до $d.",
        [12749] = "Активує вашого мітрилового механічного дракончика, який б’ється за вас протягом $d.  Перед повторним використанням йому потрібна година на охолодження.",
        [12765] = "Зменшує час відновлення Глузування на $/1000;s1 с.",
        [12766] = "Створює хмару отрути в радіусі $a1 ярдів навколо заклинача. Вороги всередині хмари отримують $1300240s1 шкоди від сил природи кожні $1300240t1 с.  Завдає тролям у $1300240s2 рази більше шкоди.  Триває $d.",
        [12768] = "$?$a446847[Навчає виготовляти гоблінську мортиру][]",
        [12787] = "Дає шанс виконати дві додаткові атаки.",
        [12790] = "Викликає демонічних слуг Гукку на допомогу йому в бою. Слуги залишаються, доки їх не буде відпущено.",
        [12792] = "Додатково збільшує всю створювану загрозу в Захисній стійці на $s1%, коли екіпіровано щит.",
        [12797] = "Збільшує шкоду від Помсти на $m1%.",
        [12802] = "Цю посудину слід наповнити водою з першого припливного басейну в Азшарі.",
        [12805] = "Цю посудину слід наповнити водою з другого припливного басейну в Азшарі.",
        [12806] = "Цю посудину слід наповнити водою з третього припливного басейну в Азшарі.",
        [12808] = "Цю посудину слід наповнити водою з четвертого припливного басейну в Азшарі.",
        [12809] = "Приголомшує ціль на $d.",
        [12822] = "+$s1 сили атаки проти демонів.",
        [12823] = "+$s1 сили атаки проти демонів.",
        [12824] = "Перетворює ворога на вівцю, змушуючи її блукати до $d.  У такому стані вівця не може атакувати чи застосовувати заклинання, але дуже швидко відновлює здоров’я.  Будь-яка шкода поверне цілі звичайну форму.  Одночасно можна перетворити лише одну ціль.  Діє лише на звірів, гуманоїдів і малих істот.",
        [12825] = "Перетворює ворога на вівцю, змушуючи її блукати до $d.  У такому стані вівця не може атакувати чи застосовувати заклинання, але дуже швидко відновлює здоров’я.  Будь-яка шкода поверне цілі звичайну форму.  Одночасно можна перетворити лише одну ціль.  Діє лише на звірів, гуманоїдів і малих істот.",
        [12826] = "Перетворює ворога на вівцю, змушуючи її блукати до $d.  У такому стані вівця не може атакувати чи застосовувати заклинання, але дуже швидко відновлює здоров’я.  Будь-яка шкода поверне цілі звичайну форму.  Одночасно можна перетворити лише одну ціль.  Діє лише на звірів, гуманоїдів і малих істот.",
        [12834] = "Ваші критичні удари спричиняють у ворога кровотечу, що завдає $m1% середньої шкоди вашої зброї ближнього бою протягом $412609d.",
        [12845] = "Робить заклинача невидимим на $d, однак це заклинання нестабільне й може завершитися раніше.",
        [12851] = "Викликає слідопита-скверногончака. Прочитайте інструкцію!",
        [12854] = "Зменшує витрати мани на всі закляття на $s1.",
        [12857] = "Збільшує бонус сили атаки ближнього бою від Бойового кличу на $s1%.",
        [12858] = "Збільшує бонус сили атаки ближнього бою від Бойового кличу на $s1%.",
        [12860] = "Збільшує бонус сили атаки ближнього бою від Бойового кличу на $s1%.",
        [12861] = "Збільшує бонус сили атаки ближнього бою від Бойового кличу на $s1%.",
        [12862] = "Зменшує загальний час відновлення й час застосування Удару з розмаху на ${$m1/-1000}.2 с. Крім того, Удар з розмаху більше не перериває й не затримує ваш замах ближнього бою, а його час відновлення зменшується на ${$m3/-1000}.1 с.",
        [12863] = "Зменшує час відновлення Внутрішньої люті на $/1000;s1 с.",
        [12864] = "Зменшує час відновлення Внутрішньої люті на $/1000;s1 с.",
        [12865] = "Зменшує час відновлення Внутрішньої люті на $/1000;s1 с.",
        [12866] = "Зменшує час відновлення Внутрішньої люті на $/60000;s1 хв.",
        [12876] = "Збільшує зменшення сили атаки ближнього бою від Деморалізуючого кличу на $s1%.",
        [12877] = "Збільшує зменшення сили атаки ближнього бою від Деморалізуючого кличу на $s1%.",
        [12878] = "Збільшує зменшення сили атаки ближнього бою від Деморалізуючого кличу на $s1%.",
        [12879] = "Збільшує зменшення сили атаки ближнього бою від Деморалізуючого кличу на $s1%.",
        [12881] = "Заклинач виглядає отруєним, доки ефект не буде скасовано.",
        [12882] = "Вражає ворогів у конусі перед заклиначем і відкидає їх назад.",
        [12883] = "Дозволяє бачити далеко вдалині.",
        [12884] = "Завдає ворогам у конусі перед заклиначем $s2 шкоди від сил природи та додатково $s1 шкоди кожні $t1 с. Триває $d.",
        [12885] = "Відправляє гравця на плато Разеліха.",
        [12886] = "Зменшує час відновлення Викличного кличу на $/60000;s1 хв.",
        [12887] = "Завдає ворогам у конусі перед заклиначем звичайної шкоди плюс $s1 і відкидає їх назад.",
        [12888] = "Тимчасово зводить ворога з розуму, збільшуючи швидкість його атак на $s2% і руху на $s3%, а також змушуючи атакувати власних союзників протягом $d.",
        [12889] = "Змушує ворогів поблизу говорити демонічною мовою, зменшуючи швидкість застосування їхніх заклять на $s1% протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [12890] = "Заколисує ворога в глибокий сон на $d., позбавляючи змоги діяти, але водночас роблячи його невразливим.",
        [12891] = "Завдає ворогам у конусі перед заклиначем $s2 шкоди від сил природи та додатково $s1 шкоди кожні $t1 с. Триває $d.",
        [12938] = "Послаблює слуг Разеліха Осквернителя. Для активації потрібно перебувати зовсім поруч із ціллю.",
        [12944] = "Дозволяє Блокуванню щитом заблокувати додаткову атаку й збільшує тривалість на $/1000;s2 с.",
        [12945] = "Дозволяє Блокуванню щитом заблокувати додаткову атаку й збільшує тривалість на $/1000;S2 с.",
        [12946] = "Зменшує силу ворогів поблизу на $s2 і спритність на $s3 протягом $d., а також не дозволяє їм застосовувати закляття.",
        [12947] = "Надає шанс накласти Зів’ялий дотик на ворога, коли вас уражає атака ближнього бою.",
        [12956] = "Збільшує захист на $s1, опір тіні на $s2 і звичайне відновлення здоров’я на 3.",
        [12962] = "Зменшує тривалість накладених на вас ефектів приголомшення та страху на $s1%.",
        [12963] = "Збільшує шанс критичного удару Перевершення на $s1%.",
        [12975] = "Після активації тимчасово надає вам $12976s1% від максимального запасу здоров’я на $12976d. Після завершення ефекту це здоров’я втрачається.",
        [12980] = "Створює на NPC, що застосовує ефект, вигляд наче він щойно прибув.",
        [12981] = "+$s1 сили атаки проти нежиті.",
        [13005] = "Приголомшує ворога, позбавляючи його можливості рухатися чи атакувати протягом $d.",
        [13006] = "Зменшує ціль, знижуючи її силу атаки на $13003s1.  Принаймні зазвичай саме так це й працює.....",
        [13007] = "Захищає заклинача від усіх атак і заклять протягом $d., але в цей час заклинач також не може атакувати чи застосовувати закляття.",
        [13008] = "Завдає $s1 шкоди від святості будь-якій істоті, що атакує учасника групи поблизу. На гравцеві одночасно може діяти лише одна аура від одного паладина. Аура діє до скасування.",
        [13009] = "Відкидає ворога назад.",
        [13013] = "Зменшує броню ворога на $s1% на $d.",
        [13018] = "Хвиля полум’я розходиться від заклинача, завдаючи всім ворогам у вибуху $s1 шкоди від вогню та сповільнюючи їхній рух на $s2% на $d.",
        [13019] = "Хвиля полум’я розходиться від заклинача, завдаючи всім ворогам у вибуху $s1 шкоди від вогню та сповільнюючи їхній рух на $s2% на $d.",
        [13020] = "Хвиля полум’я розходиться від заклинача, завдаючи всім ворогам у вибуху $s1 шкоди від вогню та сповільнюючи їхній рух на $s2% на $d.",
        [13021] = "Хвиля полум’я розходиться від заклинача, завдаючи всім ворогам у вибуху $s1 шкоди від вогню та сповільнюючи їхній рух на $s2% на $d.",
        [13022] = "Відбиває вогняні закляття та закляття таємної магії назад у заклинача",
        [13031] = "Миттєво оточує вас щитом, що поглинає $s1 шкоди. Триває $d. Поки щит тримається, отримання шкоди не перериває й не затримує застосування ваших заклять.\r\n",
        [13032] = "Миттєво оточує вас щитом, що поглинає $s1 шкоди. Триває $d. Поки щит тримається, отримання шкоди не перериває й не затримує застосування ваших заклять.\r\n\r\n",
        [13033] = "Миттєво оточує вас щитом, що поглинає $s1 шкоди. Триває $d. Поки щит тримається, отримання шкоди не перериває й не затримує застосування ваших заклять.\r\n\r\n",
        [13044] = "Відправляє гравця на плато Разеліха.",
        [13049] = "Викликає смарагдового дракончика, який ненадовго захищає вас у бою.",
        [13119] = "Ловить ціль сіткою на $13099d.  Та в сітці повно гачків, тож під час пострілу вона іноді чіпляється за одяг користувача......",
        [13120] = "Ловить ціль сіткою на $13099d.  Та в сітці повно гачків, тож під час пострілу вона іноді чіпляється за одяг користувача......",
        [13140] = "Завдає ворогові шкоди від вогню.",
        [13141] = "Ці черевики значно збільшують швидкість бігу на $d.  УВАГА:  їхній блок живлення та гіроскопи не завжди працюють як слід.",
        [13142] = "Відправляє гравця на плато Разеліха.",
        [13143] = "Використати біля Вівтаря Осквернителя, щоб викликати Разеліха Осквернителя.",
        [13159] = "Мисливець і члени групи в радіусі $a1 ярдів переймають аспект зграї гепардів, збільшуючи швидкість руху на $s1%.  Якщо член зграї отримує шкоду, його буде ошелешено на $15571d.  Одночасно може бути активним лише один Аспект.",
        [13161] = "Мисливець переймає аспект звіра, стає невідстежуваним і збільшує силу атаки ближнього бою на $s2. Одночасно може бути активним лише один Аспект.",
        [13163] = "Мисливець переймає аспект мавпи, збільшуючи шанс ухилення на $s1%.  Одночасно може бути активним лише один Аспект.",
        [13165] = "Мисливець переймає аспект яструба, збільшуючи силу атаки дальнього бою на $s1.  Одночасно може бути активним лише один Аспект.",
        [13166] = "Створює Бойову курку, яка битиметься за вас протягом $d або доки її не буде знищено.",
        [13168] = "Збільшує фізичну шкоду курки на $s1% і прискорює її атаки на $s2% протягом $d.",
        [13180] = "Вступає в ментальний двобій із гуманоїдом, намагаючись підкорити його розум.  Якщо все піде добре, ви контролюватимете розум цілі протягом $13181d .....",
        [13183] = "Завдає всім цілям у конусі перед інженером $13184s1 шкоди від вогню протягом $d. Завдає звірам у $s2 рази більше шкоди.  Якщо, звісно, воно не вибухне.....",
        [13184] = "Завдає $s1 шкоди від вогню кожні $13183t1 с.",
        [13198] = "+$s1 сили.",
        [13219] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, зменшуючи ефективність усього застосованого до нього зцілення на $13218s1 протягом $13218d.  Накопичується до $13218u разів на одній цілі.  $m2 зарядів.",
        [13220] = "Покриває зброю отрутою на ${$m2/60} хвилин.\r\nКожен удар має $13219h% шанс отруїти ворога, зменшуючи ефективність усього застосованого до нього зцілення на $13218s1 протягом $13218d.  Накопичується до $13218u разів на одній цілі.  $m3 зарядів.",
        [13225] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, зменшуючи ефективність усього застосованого до нього зцілення на $13222s1 протягом $13222d.  Накопичується до $13222u разів на одній цілі.  $m2 зарядів.",
        [13226] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, зменшуючи ефективність усього застосованого до нього зцілення на $13223s1 протягом $13223d.  Накопичується до $13223u разів на одній цілі.  $m2 зарядів.",
        [13227] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, зменшуючи ефективність усього застосованого до нього зцілення на $13224s1 протягом $13224d.  Накопичується до $13224u разів на одній цілі.  $m2 зарядів.",
        [13228] = "Покриває зброю отрутою на ${$m2/60} хвилин.\r\nКожен удар має $13225h% шанс отруїти ворога, зменшуючи ефективність усього застосованого до нього зцілення на $13222s1 протягом $13222d.  Накопичується до $13222u разів на одній цілі.  $m3 зарядів.",
        [13229] = "Покриває зброю отрутою на ${$m2/60} хвилин.\r\nКожен удар має $13226h% шанс отруїти ворога, зменшуючи ефективність усього застосованого до нього зцілення на $13223s1 протягом $13223d.  Накопичується до $13223u разів на одній цілі.  $m3 зарядів.",
        [13230] = "Покриває зброю отрутою на ${$m2/60} хвилин.\r\nКожен удар має $13227h% шанс отруїти ворога, зменшуючи ефективність усього застосованого до нього зцілення на $13224s1 протягом $13224d.  Накопичується до $13224u разів на одній цілі.  $m3 зарядів.",
        [13234] = "Силовий щит захищає вас від наступних $s1 шкоди протягом $d1. УВАГА: силове поле може перевантажитися від удару й тимчасово викинути власника з цього виміру.",
        [13237] = "Завдає $s1 шкоди від вогню й приголомшує цілі в радіусі $a1 ярдів на $d.",
        [13238] = "Завдає $s1 шкоди від вогню та $o2 шкоди протягом $d цілям у радіусі 10 ярдів.",
        [13240] = "Перезаряджає порожню гоблінську мортиру.",
        [13241] = "Після спрацювання вибухає, завдаючи $s1 шкоди від вогню всім ворогам поблизу та $s2 шкоди вам.",
        [13258] = "Створює рухому бомбу, яка кидається на найближчого ворога й вибухає, завдаючи $13259s1 шкоди від вогню.",
        [13261] = "Несправність. Завдає $s1 шкоди від вогню.",
        [13262] = "Вилучає магічні складники з доброякісної (зеленої) або кращої зброї чи обладунків.  Вибраний предмет буде ЗНИЩЕНО й повернути його буде неможливо.",
        [13278] = "Пристрій із часом заряджається вашою життєвою силою, а потім спрямовує сплеск енергії у ворога. Завдає гномам у $s2 рази більше шкоди.",
        [13281] = "Вражає ворога ударною силою, завдаючи шкоди від сил природи й перериваючи застосування закляття на $d.",
        [13298] = "Завдає ворогу шкоди від сил природи кожні $t1 с протягом $d.",
        [13318] = "Ранить ціль, змушуючи її кровоточити й отримати $o1 шкоди протягом $d.",
        [13321] = "Вражає ворога антимановою стрілою. За кожну поглинуту стрілою одиницю мани ціль отримує $e1 шкоди.",
        [13322] = "Завдає ворогові шкоди від криги та зменшує швидкість його руху на $d.",
        [13323] = "Перетворює ворога на вівцю, змушуючи його блукати до $d. Під час блукання вівця не може атакувати чи застосовувати закляття, але дуже швидко відновлюється. Будь-яка шкода поверне цілі звичайну форму. Одночасно можна перетворити лише одну ціль. Діє лише на звірів, драконів, велетнів, гуманоїдів і створінь.",
        [13326] = "Збільшує інтелект союзника на $s1 протягом $d.",
        [13327] = "Кидається на ворога, добряче оглушаючи його на $d. Також збиває вас із ніг, ненадовго приголомшуючи. Будь-яка завдана шкода пробудить ціль.",
