        [16454] = "Вражає ціль на $s1 шкоди від вогню та збільшує завдану цілі шкоду від вогню на $s2 протягом $d.",
        [16457] = "Викликає одного з друзів Сліма на допомогу, коли він вступає в бій.",
        [16458] = "Зменшує швидкість руху ворога на $s1% і всю фізичну та магічну шкоду, яку він завдає, на $s2. Триває $d.",
        [16460] = "Зменшує шанс ворога завдати критичного удару атакою ближнього бою на $s1% і закляттям на $s2%. Триває $d.",
        [16461] = "Зменшує витривалість ворога на $s1% протягом $d.",
        [16462] = "Збільшує шанс парирування на $s1%.",
        [16468] = "Отруює ворогів поблизу. Доки отруту повністю не виведе з крові досвідчений медик, вона періодично знерухомлюватиме отруєного та його союзників поблизу.",
        [16469] = "Позбавляє ціль змоги рухатися на $d",
        [16470] = "Збільшує броню на $s1 протягом $d1, але на час дії закляття не можна застосовувати закляття чи атакувати.",
        [16472] = "Лікує на цілі $s1 $leffect:ефект:ефекти; отрути.",
        [16487] = "Відновлює $m1% від загального запасу здоров’я протягом $16488d після отримання критичного удару або втрати більш ніж $m2% максимального здоров’я від однієї атаки.",
        [16493] = "Збільшує бонус критичної шкоди ваших здібностей на $s1%.",
        [16495] = "Висмоктує з ворога $s1 здоров’я, зцілюючи заклинача на величину до подвійної кількості.",
        [16496] = "Стріляє у ворога, завдаючи фізичної шкоди.",
        [16497] = "Жбурляє приголомшувальну бомбу, завдаючи всім ворогам у вибраній ділянці звичайної шкоди плюс $s1 і приголомшуючи їх на $d.",
        [16498] = "Зменшує броню ворога на $s1 на $d. Поки діє ефект, ціль не може переходити в непомітність або невидимість.",
        [16502] = "Випустіть кошеня Вінни біля оскверненого місячного колодязя.",
        [16508] = "Реве на ворога, паралізуючи його жахом на $d. і змушуючи всіх інших ворогів поблизу тікати в страху.",
        [16509] = "Завдає ворогові фізичної шкоди кожні $t1 с. протягом $d.",
        [16511] = "Миттєвий удар, що завдає $m4% шкоди зброєю ($m5%, якщо екіпіровано кинджал) і змушує ціль отримувати на $m3% більше шкоди від Розриву розбійника. Триває $d. Дає $s2 $lPoint:Points; серії.",
        [16513] = "Збільшує шкоду ваших отрут на $m1% і додатково дає їм $m3% шанс протистояти ефектам розвіювання.",
