        [18398] = "Вражає ціль, завдаючи $s1 шкоди від криги.",
        [18399] = "Обрушує стовп полум’я, що обпалює всіх ворогів у вибраній ділянці та завдає додаткової шкоди кожні $t2 с. протягом $d.",
        [18400] = "Змушує гравців поблизу танцювати.",
        [18427] = "Збільшує шкоду Підступного удару, Удару в спину та Потрошіння на $s1%.",
        [18432] = "Завдає $s1 шкоди від вогню ворогам поблизу.",
        [18435] = "Завдає $s1 шкоди від вогню ворогам у конусі перед заклиначем.",
        [18459] = "Збільшує шанс критичного удару Вогняного вибуху, Крижаного списа, Таємного вибуху та Обпалення на $s1%.",
        [18462] = "Дозволяє $s1% відновлення мани продовжувати діяти під час застосування заклять.",
        [18499] = "Воїн впадає в лють берсерка, стаючи несприйнятливим до ефектів Страху й недієздатності та генеруючи додаткову лють від отриманої шкоди.  Триває $d.",
        [18500] = "Завдає $s2 шкоди ворогам у конусі перед заклиначем і відкидає їх назад.",
        [18501] = "Збільшує фізичну шкоду заклинача на $s1 і прискорює його атаки на $s2% протягом $d.",
        [18502] = "Висмоктує $s1 мани з ворога кожні $t1 с. і передає її заклиначеві протягом $d.",
        [18503] = "Перетворює ворога на курку, позбавляючи його змоги атакувати чи застосовувати закляття протягом $d.",
        [18520] = "Підказка харизми.",
        [18530] = "Зменшує час застосування Кари, Священного вогню, Зцілення та Великого зцілення на $/1000;S1 с.",
        [18540] = "Починає ритуал, що жертвує випадковим учасником, щоб викликати Вартового Скверни.  Вартового Скверни потрібно негайно підкорити, інакше він атакуватиме учасників ритуалу.  Для завершення ритуалу потрібні заклинач і ще 4 члени групи.  Щоб узяти участь, усі гравці мають клацнути портал правою кнопкою й не рухатися до завершення ритуалу.",
        [18543] = "Обпалює ворога, а потім завдає додаткової шкоди від вогню кожні $t1 сек. протягом $d.",
        [18544] = "Збільшує шкоду заклять на $s2% і шанс критичного удару атакувальних заклять на $s1%.",
        [18545] = "Жалить ворога, зменшуючи його силу та спритність на $s1 протягом $d.",
        [18546] = "Знерухомлює заклинача, але збільшує швидкість його атаки на $s2% протягом $d.",
        [18547] = "Збільшує шкоду заклять на $s2% і шанс критичного удару атакувальних заклять на $s1%.",
        [18548] = "Збільшує шкоду заклять на $s2% і шанс критичного удару атакувальних заклять на $s1%.",
