        [20534] = "Телепортує ворога просто на розпечене вугілля.",
        [20535] = "Видихає блискавку у ворога, завдаючи шкоди від сил природи.",
        [20536] = "Видихає блискавку у ворога, завдаючи шкоди від сил природи.",
        [20537] = "Перериває вороже закляття, не даючи ворогові повторно застосувати його протягом $d. Створює велику кількість загрози.",
        [20539] = "Висмоктує з ворога $s1 здоров’я, зцілюючи заклинача на величину до подвійної кількості.",
        [20540] = "Переводить заклинача в непомітність, але зменшує швидкість руху на $s2%. Триває до скасування.",
        [20542] = "Завдає ворогам поблизу $s1 шкоди від сил природи кожні $t1 с і збільшує отримувану ними шкоду від сил природи на $s2 на $d.",
        [20543] = "Видихає блискавку у ворога, завдаючи шкоди від сил природи.",
        [20545] = "Оточує заклинача $n кулями блискавки, які мають $h% шанс уразити нападників ближнього або дальнього бою на $s1 шкоди. Після кожного спрацювання блискавичного щита одна куля розсіюється. Тож щит зникає через $d або після $n спрацювань.",
        [20549] = "Приголомшує до $i ворогів у межах $a1 м на $d.",
        [20550] = "Збільшує загальний запас здоров'я на $s1% і ймовірність влучання на $s2%.",
        [20552] = "Вирощує копію рослини поблизу, яку можна зібрати без навички травництва. Кожну рослину можна культивувати лише один раз.",
        [20554] = "Збільшує швидкість вимовляння заклять і атак на $s1% на $26635d.",
        [20555] = "Збільшує швидкість відновлення здоров'я на $s1%. Крім того, $s2% загального відновлення здоров'я триває під час бою.",
        [20557] = "Збільшує шкоду, завдану звірам, на $s1%.",
        [20559] = "Глузлива атака, що завдає $s1 шкоди, створює помірну загрозу та змушує ціль зосередити атаки на вас протягом $d.",
        [20560] = "Глузлива атака, що завдає $s1 шкоди, створює помірну загрозу та змушує ціль зосередити атаки на вас протягом $d.",
        [20565] = "Завдає ворогові $s1 шкоди від вогню.",
        [20566] = "Завдає ворогам поблизу $s1 шкоди від вогню та відкидає їх.",
        [20569] = "Розмашиста атака, що завдає цілі шкоди від зброї плюс $s1 і вражає другого ворога поблизу.",
        [20572] = "Збільшує силу атаки та силу заклять на $s1% на $d.",
        [20573] = "Зменшує тривалість ефектів приголомшення на вас на $s1%.",
        [20574] = "Збільшує ймовірність критичного удару всіма закляттями й здібностями на $s1%, коли ви озброєні сокирою або дворучною сокирою.",
        [20577] = "Після активації відновлює $20578s1% загального запасу здоров'я та $20578s2% загального запасу мани кожні $20578t1 с протягом $20578d. Діє лише на трупи гуманоїдів або нежиті в межах $a1 м. Будь-який рух, дія або отримана шкода під час канібалізму скасовує ефект.",
        [20580] = "Після активації ви зливаєтеся з тінями, зменшуючи ймовірність того, що вороги помітять вас. Триває до скасування або початку руху. Використання цієї здібності в бою відбиває у ворогів бажання атакувати вас, але збільшує час відновлення до 2 хв.",
        [20582] = "Ймовірність ухилення збільшується на $s1%, а швидкість руху — на $s2%. Нічних ельфів-розбійників і друїдів важче виявити в непомітності, наче вони на 1 рівень вищі.",
        [20585] = "Після смерті перетворює вас на вогника, збільшуючи швидкість руху на $20584s1%.",
        [20586] = "Завдає $s1 шкоди від сил природи кожні $t1 с протягом $d.",
        [20587] = "Збільшує витривалість на $s3 і зменшує отримувану фізичну шкоду на $s4 на $d. Водночас зменшує силу та спритність на $s1 і збільшує отримувану магічну шкоду на величину до $s5.",
        [20589] = "Миттєво знімає всі ефекти, що обмежують рух, і надає невразливість до них на $d.",
        [20591] = "Максимальний запас мани збільшується на $s1%.",
        [20593] = "Ваша гномська винахідливість зменшує ймовірність відмови або зворотного спрацювання інженерних пристроїв на $s1%.",
        [20594] = "Миттєво знімає всі ефекти кровотечі, отрути й хвороб та надає невразливість до них, а також зменшує всю отримувану фізичну шкоду на $s1% на $d.",
        [20597] = "Збільшує ймовірність критичного удару всіма закляттями й атаками на $s1%, коли ви озброєні мечем або дворучним мечем.",
        [20598] = "Дух збільшується на $s1%.",
        [20600] = "Значно покращує виявлення непомітності на $d.",
