        [21793] = "Завдає ворогам в області шкоди від сил природи протягом $d, сповільнюючи їхній рух на $s2% і збільшуючи час між їхніми атаками на $s3%.",
        [21794] = "Використайте, щоб надіти намордник на Крижаного Вовка. Поверніть тварину в наморднику доглядачеві стайні Крижаних Вовків.",
        [21807] = "Жбурляє у ворога блискавку, завдаючи шкоди від сил природи.",
        [21808] = "Закликає осколки Терадрімів кожні 2 секунди та приголомшує ворогів в області на $d.",
        [21831] = "Збільшує шкоду від кровотечі вашої здібності «Роздирання» на $s1 за кожен такт.",
        [21832] = "Жбурляє валун у ворога.",
        [21833] = "Завдає всім цілям у конусі перед інженером, що використовує зброю, $13184s1 шкоди від вогню протягом $d. Хіба що вона вибухне.....",
        [21834] = "Ставить на землю манекен-мішень, який змушує чудовиськ поблизу атакувати його.  Існує 3 хв.",
        [21838] = "Дає вам $h% шанс отримати додаткову одиницю люті щоразу, коли вам завдають шкоди.",
        [21841] = "Щоразу, коли ви завдаєте шкоди в ближньому бою, ви маєте $h% шанс зменшити силу атаки жертви на $21840s1 на $21840d.",
        [21848] = "Перетворює вас на щось більш доречне для зимового сезону. Для використання потрібна сніжка.",
        [21849] = "Надає «Дар дикої природи» всім членам групи та рейду, збільшуючи броню на $s1, усі характеристики на $s2 і всі опори на $s3 на $d.",
        [21850] = "Надає «Дар дикої природи» всім членам групи та рейду, збільшуючи броню на $s1, усі характеристики на $s2 і всі опори на $s3 на $d.",
        [21853] = "Після отримання удару в ближньому бою є $h% шанс, що ви застосуєте «Зникнення» на $21976d.",
        [21856] = "Збільшує загрозу, створювану вашими здібностями «Героїчний удар» і «Смертельний удар».",
        [21858] = "Спалює $s1 мани у ворогів поблизу, а половина спаленої мани завдається їм як шкода від вогню.",
        [21866] = "Використайте, щоб приручити альтерацького барана. Поверніть приручену тварину доглядачеві стайні Бурешпиля.",
        [21869] = "Реве на ворога, паралізуючи його жахом на $d. і змушуючи всіх інших ворогів поблизу тікати в страху.",
        [21870] = "Збільшує вашу ймовірність критичного удару закляттями сил природи на $s1%.",
        [21871] = "Збільшує тривалість вашого закляття «Омолодження» на $/1000;s1 с.",
        [21872] = "Зменшує час вимовляння вашого закляття «Відростання» на $/1000;S1 с.",
        [21873] = "Зменшує витрати мани на ваші закляття зміни форми на $s1.",
        [21874] = "Зменшує час відновлення вашої здібності «Зникнення» на $/1000;s1 с.",
        [21878] = "Збільшує ймовірність ухилення розбійника на $s1% на $d.",
        [21879] = "Зменшує загрозу, створювану вашими закляттями «Опік», «Таємні стріли», «Вогняна куля» та «Крижана стріла».",
        [21880] = "Збільшує шкоду від вашої здібності «Розрив» на $s1 за кожен такт.",
        [21881] = "Збільшує ймовірність накласти отруту на ціль на $s1%.",
        [21882] = "$h% шанс завдати $21889s1 додаткової шкоди від святості щоразу, коли ви завдаєте критичного удару в ближньому бою.",
        [21884] = "Наповніть в оранжевому кришталевому ставку в Мародоні.",
        [21885] = "Вилийте на лози Мерзостебла, щоб очистити їх від скверни.",
        [21890] = "$h% шанс після використання наступальної здібності, що потребує люті, що ваша наступна наступальна здібність коштуватиме на $/10;21887s1 люті менше.",
        [21891] = "+$s1 до ефекту тотемів «Сила землі» та «Благодать повітря».",
        [21892] = "Ви захищені від усіх фізичних атак і заклять протягом $d.",
        [21893] = "Після отримання атаки ближнього бою маєте $h% шанс отримати захист від усіх фізичних атак і заклять на $21892d.",
        [21894] = "Дозволяє $s1% відновлення мани продовжувати діяти під час застосування заклять.",
        [21895] = "Радіус ваших тотемів, що впливають на дружні цілі, збільшується до 30 ярдів.",
        [21896] = "Візуальний ефект закляття для події появи духа Заетара.",
        [21897] = "Після отримання атаки ближнього бою маєте $h% шанс налякати нападника, змусивши його тікати від вас протягом $21898d.",
        [21899] = "Збільшує зцілення «Ланцюгового зцілення» для цілей після першої на $s1%.",
        [21919] = "Надає додаткову атаку під час вашого наступного удару.",
        [21920] = "Збільшує шкоду від заклять криги на величину до $s1 на $d.",
        [21922] = "Ваш вихованець отримує $21921s1 витривалості та $21921s2 опору закляттям усіх шкіл магії.",
        [21926] = "Збільшує витривалість вашого вихованця на $21925s1 і всі його опори магії на $21925s2.",
        [21928] = "Збільшує витривалість вашого вихованця на $21927s1 і всі його опори магії на $21927s2.",
        [21931] = "Назавжди зачаровує зброю, збільшуючи шкоду заклять криги на величину до 15.",
        [21935] = "Дає досвідченому інженеру змогу перетворювати воду на сніжку. Снігомайстру потрібна доба, щоб накопичити достатньо холоду для заморожування наступної сніжки.",
        [21937] = "+$s1 до сили атаки проти велетнів.",
        [21938] = "Збільшує силу атаки вашого вихованця на $20988s1.",
        [21942] = "Збільшує запас здоров'я ваших вихованців на $s1%.",
        [21949] = "Ранить ціль, змушуючи її кровоточити й отримати $o1 шкоди протягом $d.",
        [21950] = "Клацніть правою кнопкою, щоб прочитати слова на сувої.",
        [21951] = "Відновлює $s1 мани. Відновлює в $s2 рази більше, якщо ви атакуєте елементаля землі, голема або викуваного титанами ворога.\r\n",
        [21952] = "Отруює ціль, завдаючи $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [21954] = "Знімає $m1 $leffect:effects; отрути.",
        [21955] = "Відновлює $o1 здоров'я та мани протягом $d.",
        [21956] = "Поглинає $s1 фізичної шкоди. Триває $d.",
        [21957] = "Вставляє всі п'ять самоцвітів ханів в Амулет духів.",
        [21958] = "Зменшує ймовірність влучання по вас ефектів приголомшення та страху на $s1%.",
        [21960] = "Змушує духів перших кентаврських ханів проявитися у фізичному світі.",
        [21961] = "Ранить ціль, завдаючи $s1 шкоди та зменшуючи її броню на $s2.",
        [21962] = "Прикликає $s1 $lForce of Nature:Forces of Nature; на допомогу заклиначеві в бою на $d.",
        [21963] = "Прикликає $s1 $lForce of Nature:Forces of Nature; на допомогу заклиначеві в бою на $d.",
        [21964] = "Прикликає $s1 $lForce of Nature:Forces of Nature; на допомогу заклиначеві в бою на $d.",
        [21965] = "Візуальний ефект, коли кентаврські хани повертаються до форми духів.",
        [21966] = "+$s1 до сили атаки проти драконідів.",
        [21967] = "Сила атаки збільшується на $s1.",
        [21968] = "Прикликає $s1 $lForce of Nature:Forces of Nature; на допомогу заклиначеві в бою на $d.",
        [21969] = "Після отримання удару в бою має $h% шанс збільшити всі характеристики на $21970s1 на $21970d1.",
        [21970] = "Збільшує всі характеристики на $s1 на $d.",
        [21971] = "Плює отрутою у ворога, завдаючи шкоди від сил природи, а потім додаткової шкоди кожні $t2 с протягом $d.",
        [21972] = "Збільшує тривалість ваших «Шипів» на $/1000;s1 с.",
        [21973] = "Зменшує час вимовляння вашого «Швидкого зцілення» на $/1000;S1 с.",
        [21975] = "Збільшує максимальний запас енергії на $s1.",
        [21976] = "Зникає з поля зору, зменшуючи бажання ворогів атакувати вас протягом $d.",
        [21978] = "Після влучання закляттям, що завдає шкоди, є шанс завдати $27860s1 шкоди від тіні та відновити вам $27860s2 мани.",
        [21979] = "Створює настанови Парії після вибору відповідної репліки діалогу.",
        [21987] = "Шмагає ворога, завдаючи шкоди від тіні. Заклинач має бути позаду цілі.",
        [21991] = "Після отримання удару в бою завдає нападникові $s1 шкоди від сил природи.",
        [21992] = "Вражає ворога блискавкою, завдаючи $s2 шкоди від сил природи, після чого блискавка перескакує на додаткових ворогів поблизу. Кожен стрибок зменшує опір сил природи цієї цілі на $s1. Вражає $x1 цілей. Основну ціль також охоплює циклон, що зменшує швидкість її атак на $27648s1% на $d.",
        [22007] = "$s1% шанс після застосування «Таємних стріл», «Вогняної кулі» або «Крижаної стріли», що ваше наступне закляття з часом вимовляння менше 10 секунд буде миттєвим.",
        [22010] = "Ваше «Велике зцілення» тепер також зцілює з часом на рівні «Оновлення» 5-го рангу.",
        [22047] = "Закликає випробувальний тотем із $s1 здоров'я біля ваших ніг на $d, який швидко атакує ворога в межах $22048r м, завдаючи $22048s1 шкоди від вогню.",
        [22051] = "Назавжди зачаровує наручі, надаючи $19984s1 сили.",
        [22052] = "Назавжди зачаровує наручі, надаючи $19985s1 витривалості.",
        [22053] = "Назавжди зачаровує наручі, надаючи $19986s1 духу.",
        [22054] = "Назавжди зачаровує наручі, надаючи $13825s1 інтелекту.",
        [22067] = "Дає заклиначу $s1% шанс відбити шкідливі заклинання протягом $d.",
        [22088] = "Завдає ворогові шкоди від вогню.",
        [22089] = "Назавжди зачаровує нагрудний обладунок, надаючи $19990s1 здоров'я.",
        [22090] = "Назавжди зачаровує нагрудний обладунок, надаючи +100 мани.",
        [22091] = "Назавжди зачаровує плащ, надаючи $19992s1 до всіх опорів.",
        [22092] = "Назавжди зачаровує плащ, надаючи 70 додаткової броні.",
        [22094] = "Назавжди зачаровує дворучну зброю ближнього бою, збільшуючи її шкоду на 9.",
        [22095] = "Назавжди зачаровує зброю ближнього бою, збільшуючи її шкоду на 5.",
        [22098] = "Назавжди зачаровує щит, надаючи $13827s1 витривалості.",
        [22099] = "Назавжди зачаровує щит, надаючи $13923s1 опору кризі.",
        [22100] = "Назавжди зачаровує щит, надаючи $19986s1 духу.",
        [22101] = "Назавжди зачаровує чоботи, надаючи $13823s1 спритності.",
        [22102] = "Назавжди зачаровує чоботи, надаючи $13368s1 духу.",
        [22103] = "Назавжди зачаровує чоботи, надаючи $13827s1 витривалості.",
        [22104] = "Назавжди зачаровує рукавиці, надаючи $13828s1 сили.",
        [22105] = "Назавжди зачаровує рукавиці, надаючи $13823s1 спритності.",
        [22106] = "Назавжди зачаровує рукавиці, надаючи бонус $13928s1 до швидкості атаки.",
        [22120] = "Здійснює ривок до ворога, завдаючи звичайної шкоди плюс $s3.",
        [22121] = "Стріляє у ворога, завдаючи фізичної шкоди.",
        [22127] = "Обплутує ворога корінням, завдаючи шкоди від сил природи кожні $t2 с. і знерухомлюючи його на час до $d.",
        [22128] = "На дружній цілі виростають шипи, які завдають нападникам $s1 шкоди від сил природи, коли ті влучають у ціль.  Триває $d.",
        [22167] = "Закликає святу магію, щоб зцілити союзника.",
        [22168] = "Зцілює союзника на $s1 кожні $t1 сек. протягом $d.",
        [22187] = "Огортає союзника щитом на час до $d., що поглинає максимум $s1 фізичної або магічної шкоди. Поки щит тримається, фізичні атаки не переривають закляття.",
        [22188] = "Навичка володіння арбалетами збільшується на $s1.",
        [22189] = "Вражає ворога антимановою стрілою. За кожну поглинуту стрілою одиницю мани ціль отримує $e1 шкоди.",
        [22206] = "Обпалює ворога таємною магією та завдає додаткової шкоди протягом $d.",
        [22270] = "Воскрешає вибраного гравця з $s1% здоров'я та мани. Можна використовувати після смерті.",
        [22271] = "Вивільняє вибухову хвилю магії, завдаючи ворогам поблизу шкоди від таємної магії.",
        [22272] = "Запускає у ворога магічні снаряди, завдаючи шкоди від таємної магії щосекунди протягом $d.",
        [22273] = "Запускає у ворога магічні снаряди, завдаючи шкоди від таємної магії.",
        [22274] = "Перетворює ворога на вівцю, змушуючи її блукати до $d. Під час блукання вівця не може атакувати чи вимовляти закляття, але дуже швидко відновлюється. Одночасно можна перетворити лише одну ціль. Діє лише на звірів, драконів, велетнів, гуманоїдів і звірят.",
        [22275] = "Обрушує стовп полум’я, що обпалює всіх ворогів у вибраній ділянці та завдає додаткової шкоди кожні $t2 с. протягом $d.",
        [22334] = "Бомбардує всіх ворогів у вибраній зоні, завдаючи шкоди від вогню.",
        [22335] = "Кидає у ворога пляшку отрути, завдаючи $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [22336] = "Жбурляє у ворога стрілу темної магії, завдаючи шкоди від тіні.",
        [22351] = "Завдає $s1 шкоди від сил природи кожній істоті, що атакує заклинача.",
        [22355] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній шкоди від сил природи.",
        [22356] = "Збільшує час між атаками ворогів поблизу на $s1% і сповільнює їхній рух на $s2% протягом $d.",
        [22357] = "Завдає ворогові шкоди від криги та приголомшує його на $d.",
        [22371] = "Зменшує магічну шкоду, яку завдає ціль, на $s1 на $d.",
        [22372] = "Відкриває портал у Крутоверть Порожнечі, який періодично викликає демонічних слуг на допомогу заклиначеві в бою протягом $d.",
        [22373] = "Зцілює союзника на фіксовану величину, а потім додатково зцілює кожні $t2 с. протягом $d.",
        [22411] = "Стріляє у ворога, завдаючи фізичної шкоди.",
        [22414] = "Вражає ворога блискавкою, завдаючи шкоди від сил природи.",
        [22415] = "Обплутує ворога корінням, завдаючи шкоди від сил природи кожні $t2 с. і знерухомлюючи його на час до $d.",
        [22416] = "Завдає ворогові звичайної шкоди та ще $s1, але лише під час атаки ззаду. ",
        [22417] = "Оточує заклинача щитом, сплетеним із магії тіні. Щит триває $d., поглинає до $s1 фізичної або магічної шкоди й завдає $s2 шкоди нападникам ближнього бою.",
        [22418] = "Випадково збільшує магічну шкоду заклинача на величину до $s1 на $d.",
        [22420] = "Зменшує витривалість ворогів поблизу на $s1 на $d.",
        [22423] = "Миттєво обпалює ворога, а потім завдає додаткової шкоди від вогню кожні $t2 с. протягом $d.",
        [22424] = "Вивільняє хвилю полум’я, завдаючи ворогам поблизу шкоди від вогню й зменшуючи швидкість їхнього руху протягом $d.",
        [22425] = "Завдає шкоди від вогню ворогам поблизу.",
        [22426] = "Б'є по броні ворога, зменшуючи її на $s1 за кожен ефект «Трощення броні». Сумується до 5 разів. Триває $d.",
        [22427] = "Жорстокий удар, що завдає шкоди зброї та приголомшує супротивника на $d.",
