        [24641] = "Завдає $24640o2 шкоди від сил природи протягом $24640d. Ефект сумується до 5 разів на одній цілі.",
        [24648] = "Обплутує ворога корінням, завдаючи шкоди від сил природи кожні $t2 с. і знерухомлюючи його на час до $d.",
        [24658] = "Збільшує шкоду ваших заклять на величину до 204 і зцілення на величину до 408 на $d. Після кожного застосованого закляття бонус зменшується на 17 шкоди заклять і 34 зцілення.",
        [24661] = "Збільшує вашу шкоду ближнього й дальнього бою на 40 на $d. Після кожного влучання цей бонус зменшується на 2.",
        [24664] = "Присипляє ворогів поблизу до $d. Будь-яка завдана шкода пробудить їх.",
        [24666] = "Збільшує шкоду від заклять і ефектів криги на величину до $s1.",
        [24667] = "Збільшує шкоду від заклять і ефектів криги на величину до $s1.",
        [24668] = "Жбурляє у ворога стрілу темної магії, завдаючи шкоди від тіні.",
        [24669] = "Обрушує розплавлений дощ, що обпалює всіх ворогів у вибраній ділянці на $s1 шкоди від вогню кожні $t1 с. протягом $d.",
        [24670] = "Викликає метеор із Крутіжу Порожнечі, що завдає $22699s1 шкоди від вогню та приголомшує всіх ворогів у ділянці на $20310d.  З кратера постає Інфернал, підкорений заклиначу на $20882d.  Після втрати контролю Інфернала потрібно Підкорити, щоб зберегти контроль.  Можна використовувати лише просто неба.",
        [24671] = "Завдає ворогові $s2 шкоди й приголомшує його на $d.",
        [24672] = "Збільшує швидкість атак союзника на $s1% на $d., але також завдає йому $s2 шкоди від сил природи кожні $t2 сек.",
        [24673] = "Збільшує отримувану ворогом фізичну шкоду на $s1 протягом $d.",
        [24674] = "Зменшує ефективність зцілення ворога на $s1% на $d.",
        [24680] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній наступній цілі більше шкоди від сил природи.",
        [24682] = "Завдає $s1 шкоди від сил природи ворогам у конусі перед заклиначем.",
        [24683] = "Створює хмару блискавок на $d., що вражає всіх ворогів у вибраній зоні на $s1 шкоди від сил природи та завдає ще $s2 шкоди кожні $t2 сек.",
        [24684] = "Вражає ворога антимановою стрілою, що перескакує на іншого ворога поблизу. За кожну поглинуту одиницю мани ціль отримує $e1 шкоди. Закляття вражає до $x1 цілей.",
        [24685] = "Вражає ворога ударною силою, завдаючи шкоди від сил природи й перериваючи застосування закляття на $d.",
        [24687] = "Завдає ворогам поблизу звичайної шкоди та ще $s1, не даючи їм застосовувати закляття протягом $d.",
        [24688] = "Плює отрутою у ворогів поблизу, завдаючи шкоди від сил природи, а потім додаткової шкоди кожні $t2 с. протягом $d.",
        [24694] = "+$s1 до сили атаки лише у формі кота, ведмедя та лютого ведмедя.",
        [24696] = "Клацніть правою кнопкою, щоб покликати або відіслати свого Муркі.",
        [24697] = "+$s1 до сили атаки лише у формі кота, ведмедя та лютого ведмедя.",
