        [27561] = "Коли вас уражає шкідливе закляття, його заклинач має $h% шанс бути змушеним замовкнути на $27559d.",
        [27564] = "Дає заклиначу $s1% шанс відбити шкідливі заклинання протягом $d.",
        [27565] = "Виганяє ворога, позбавляючи його можливості діяти, але роблячи невразливим до $d. Одночасно можна вигнати лише одну ціль.",
        [27567] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній шкоди від сил природи.",
        [27570] = "Клацніть правою кнопкою, щоб покликати або відіслати Кві К. Лапколюба.",
        [27571] = "Осипає ціль поблизу каскадом пелюсток троянд!",
        [27577] = "Здійснює ривок до ворога, завдаючи $20615s2 шкоди та приголомшуючи його на $20615d.",
        [27578] = "Воїн вигукує, збільшуючи силу атаки всіх членів групи в межах $a1 м на $s1. Триває $d.",
        [27579] = "Зменшує силу атаки всіх ворогів у межах $a1 м на $s1 на $d.",
        [27580] = "Жорстокий удар, що завдає шкоди зброєю плюс $s2 і ранить ціль, зменшуючи ефективність будь-якого зцілення на $s1% протягом $d.",
        [27581] = "Роззброює ворога на $d.",
        [27584] = "Калічить ворога, завдаючи $s1 шкоди та зменшуючи його швидкість руху на $s2% протягом $d.",
        [27602] = "Арканітовий дракончик оживає й захищає вас протягом $d.",
        [27603] = "Завдає всім цілям у конусі перед інженером, що використовує зброю, $27604s1 шкоди від вогню протягом $d. Хіба що вона вибухне.....",
        [27605] = "Слово темряви, що завдає $o1 шкоди від тіні протягом $d.",
        [27606] = "Зцілює ціль на $o1 протягом $d.",
        [27607] = "Прикликає силу душі члена групи, щоб захистити його щитом, який поглинає $s1 шкоди.  Триває $d.  Поки щит тримається, отримана шкода не перериває застосування заклинань.  Після накладання щита ціль не можна захистити ним знову протягом $6788d.",
        [27608] = "Зцілює дружню ціль на $s1.",
        [27609] = "Розвіює магію на цілі, знімаючи $s1 шкідливі $lspell:заклинання:заклинання; із союзника або $s1 корисні $lspell:заклинання:заклинання; з ворога.",
        [27610] = "Заклинач видає психічний крик, змушуючи $i ворогів у межах $a1 м тікати протягом $d. Завдана шкода може перервати ефект.",
        [27613] = "Б’є ворога ногою, завдаючи $s1 шкоди та перериваючи застосування закляття на $d.",
        [27615] = "Завершальний прийом, що приголомшує ціль.",
        [27616] = "Дає власникові змогу бачити привидів нещодавно померлих.",
        [27617] = "Дає розбійникові змогу зникнути з поля зору, переходячи в покращену непомітність на $11329d. Також знімає ефекти, що обмежують рух. Ефективніше за «Зникнення» (ранг 1).",
        [27618] = "Крижані уламки засипають вибрану область, завдаючи $o1 шкоди від криги протягом $d.",
        [27619] = "Вас ув'язнено в брилі криги, що захищає від усіх фізичних атак і заклять протягом $d, але в цей час ви не можете атакувати, рухатися чи вимовляти закляття.",
        [27620] = "Б’є ворога ногою, завдаючи $s1 шкоди та перериваючи застосування закляття на $d.",
        [27621] = "Закликає Тотем шаленої бурі з $s1 здоров'я біля ніг заклинача. Тотем зачаровує вітром зброю в правій руці всіх членів групи в межах $10611a1 м. Кожен удар має 20% шанс надати нападникові $10610s2 додаткові $lattack:attacks; із $10610s1 додаткової сили атаки. Триває $d.",
        [27623] = "Закликає Тотем вогняної нови з $s1 здоров'я на $d. Якщо його не знищити за $11311t1 с, тотем завдає $11307s1 шкоди від вогню ворогам у межах $11307a1 м.",
        [27624] = "Зцілює дружню ціль на $s1.",
        [27626] = "Розвіює з ворожої цілі $m1 корисний магічний $leffect:effects;.",
        [27632] = "Прицільний постріл, що збільшує шкоду дальнього бою на $s1.",
        [27633] = "Завдає $s2 шкоди та зменшує швидкість руху ворожої цілі на $s1% протягом $d.",
        [27634] = "Ошелешує ворога, зменшуючи швидкість його руху на $s1% протягом $d.",
        [27635] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [27636] = "Обрушує на голову ворога зоряні уламки, завдаючи $o1 шкоди від таємної магії протягом $d.",
        [27637] = "Зцілює союзника на фіксовану величину, а потім додатково зцілює кожні $t2 с. протягом $d.",
