        [401749] = "Вигравіюйте на шоломі руну «Смуга везіння»:\r\n\r\n$@spellicon400624\r\n$@spelldesc400624",
        [401752] = "Вигравіюйте на чоботах руну «Замороження мозку»:\r\n\r\n$@spellicon400731\r\n$@spelldesc400731",
        [401754] = "Вигравіюйте на шоломі руну «Посилені обереги»:\r\n\r\n$@spellicon412115\r\n$@spelldesc412115",
        [401757] = "Вигравіюйте на рукавицях руну «Таємний вибух»:\r\n\r\n$@spellicon400574\r\n$@spelldesc400574",
        [401759] = "Вигравіюйте на нагруднику руну «Вигорання»:\r\n\r\n$@spellicon412286\r\n$@spelldesc412286",
        [401760] = "Вигравіюйте на рукавицях руну «Крижаний спис»:\r\n\r\n$@spellicon400640\r\n$@spelldesc400640",
        [401761] = "Вигравіюйте на наручах руну «Перемотування часу»:\r\n\r\n$@spellicon401462\r\n$@spelldesc401462",
        [401762] = "Вигравіюйте на поясі руну «Крижано-вогняна стріла»:\r\n\r\n$@spellicon401502\r\n$@spelldesc401502",
        [401763] = "Вигравіюйте на поясі руну «Залп стріл»:\r\n\r\n$@spellicon400588\r\n$@spelldesc400588",
        [401764] = "Вигравіюйте на плащі руну «Перегрів»:\r\n\r\n$@spellicon400615\r\n$@spelldesc400615",
        [401765] = "Вигравіюйте на нагруднику або мантії руну «Пальці криги»:\r\n\r\n$@spellicon400647\r\n$@spelldesc400647",
        [401767] = "Вигравіюйте на нагруднику або мантії руну «Відновлення»:\r\n\r\n$@spellicon401417\r\n$@spelldesc401417",
        [401768] = "Вигравіюйте на штанях руну «Живе полум’я»:\r\n\r\n$@spellicon401556\r\n$@spelldesc401556",
        [401847] = "Поєднайте з 3 іншими частинами, щоб скласти повну мапу.",
        [401859] = "Накладає на ціль закляття, яке зцілює її на ${($m1+($bh*$bc))*$<mult>} наступного разу, коли вона отримає шкоду або неперіодичне зцілення. Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $401880a1 ярдів. Перескакує до $s2 разів і триває $401877d після кожного переходу. Одночасно один заклинач може накласти це закляття лише на одну ціль.",
        [401863] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $41635a1 ярдів. Перескакує до $48113n разів і триває $48111d після кожного переходу. Одночасно це закляття може бути накладене лише на одну ціль.\r\n",
        [401877] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду або зцілення.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $a1 ярдів.  Перескакує до $n разів і триває $d після кожного переходу.  Одночасно це закляття може бути накладене лише на одну ціль.",
        [401937] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [401946] = "Зцілює всіх учасників групи вибраного гравця в межах $a1 ярдів від нього на ${$<healpower>*$m1/100}–${$<healpower>*$M1/100}.",
        [401955] = "Слово темних пут, що завдає цілі від ${$<damagepower>*$m1/100} до ${$<damagepower>*$M1/100} шкоди від тіні.  Якщо ціль не загине від Слова Тіні: Смерть, заклинач отримує шкоду в розмірі $m2% від шкоди, яку мало бути завдано цілі.",
        [401962] = "Слово темних пут, що завдає цілі шкоди від тіні.  Якщо ціль не загине від Слова Тіні: Смерть, заклинач отримує стільки ж шкоди, скільки було завдано цілі.",
        [401969] = "Ваше Слово Тіні: Біль тепер також уражає до ${$m1-1} додаткових цілей поблизу в межах $s2 ярдів.",
        [401977] = "Створює тіньового демона, який атакує ціль.  Коли Тіньовий демон атакує, заклинач отримує $401988s1% мани. Триває $d.",
        [401984] = "Атаки Тіньового демона в ближньому бою висмоктують енергію з цілі й перетворюють її на ману для його господаря.",
        [401988] = "Атаки Тіньового демона в ближньому бою висмоктують енергію з цілі й перетворюють її на ману для його господаря.",
        [401990] = "Пробирається крізь тіні до ворожої цілі та збільшує шкоду Тіньового демона на $s2% протягом $d.",
        [402000] = "Зменшує час відновлення Слова сили: Щит на ${$m1/-1000} с і витрати мани на нього на $s2%.",
        [402004] = "Миттєво зменшує всю шкоду, яку отримує дружня ціль, на $s1% і підвищує опір механікам розвіювання на $s2% протягом $d.",
        [402010] = "Повертається до звичайної форми.",
        [402174] = "Випускає в ціль залп святого світла, що миттєво й кожні $402261t2 с протягом $402261d завдає ворогові $402284s1 шкоди від святості або зцілює союзника на $402289s1.",
        [402261] = "Завдає шкоди від святості кожні $t2 с.",
        [402277] = "Зцілення кожні $t2 с протягом $d.",
        [402284] = "Завдає $s1 шкоди від святості кожні $402261t2 с.",
        [402289] = "Зцілює на $s1 кожні $402277t2 с протягом $402277d.",
        [402308] = "Розшифруйте нотатки закляття за допомогою Оберега розуміння, щоб вивчити нове закляття гравіювання.",
        [402311] = "Розшифруйте нотатки закляття за допомогою Оберега розуміння, щоб вивчити нове закляття гравіювання.",
        [402319] = "Поєднайте 6 нотаток учня Азори, щоб створити новий рецепт гравіювання.",
        [402668] = "Накладає на ціль ваш талант Вампірські обійми, завдає їй ${$<damagepower>*$m2/100*5} шкоди від тіні протягом $d і змушує всіх учасників групи відновлювати ману в розмірі $s1% від шкоди тіньовими закляттями, яку ви завдаєте цілі.",
        [402779] = "$s1% отриманої шкоди від тіньових заклять відновлює ману групі жерця.",
        [402789] = "Викликає Око Порожнечі, яке битиметься за вас протягом $d. Око може накладати на вашу ціль різні прокляття.",
        [402790] = "Жбурляє у ворога стрілу темної магії, завдаючи шкоди від тіні.",
        [402791] = "Проклинає ціль на $d, зменшуючи її опір тіні й таємній магії на $s1 та збільшуючи отримувану шкоду від тіні й таємної магії на $s2%.  На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [402792] = "Проклинає ціль на $d, зменшуючи її опір вогню й кризі на $s1 та збільшуючи отримувану шкоду від вогню й криги на $s2%.  На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [402794] = "Змушує ціль говорити демонічною мовою, збільшуючи час застосування всіх заклять на $s1%.  На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.  Триває $d.",
        [402799] = "Відколює уламки вашої душі, оживляючи $s1 мініатюрних копій вас, які намагаються атакувати поточну ціль булавою, мечем і сокирою, відповідно зменшуючи швидкість атаки, силу атаки та броню будь-якої враженої цілі.",
        [402801] = "Оживляє $s1 скелетів, які атакують вашу поточну ціль булавою, мечем і сокирою, відповідно зменшуючи її швидкість атаки, силу атаки та броню.",
        [402802] = "Оживляє $s1 скелетів, які атакують вашу поточну ціль булавою, мечем і сокирою, відповідно зменшуючи її швидкість атаки, силу атаки та броню.",
        [402808] = "Збільшує час між атаками ворога на $s1%. Триває $d.",
        [402811] = "Зменшує силу атаки цілі на $s1. Триває $d.",
        [402818] = "Зменшує броню ворога на $s1. Триває $d.",
        [402832] = "Ви отримуєте здібність «Молитва відновлення»:\r\n\r\n$@spellicon401859\r\n$@spelldesc401859",
        [402833] = "Ви отримуєте здібність «Слово Тіні: Смерть»:\r\n\r\n$@spellicon401955\r\n$@spelldesc401955",
        [402834] = "Ви отримуєте здібність «Оберіг душі»:\r\n\r\n$@spellicon402000\r\n$@spelldesc402000",
        [402836] = "Ви отримуєте здібність «Гомункули»:\r\n\r\n$@spellicon402799\r\n$@spelldesc402799",
        [402837] = "Ви отримуєте здібність «Сполучене зцілення»:\r\n\r\n$@spellicon401937\r\n$@spelldesc401937",
        [402838] = "Ви отримуєте здібність «Спільний біль»:\r\n\r\n$@spellicon401969\r\n$@spelldesc401969",
        [402839] = "Ви отримуєте здібність «Придушення болю»:\r\n\r\n$@spellicon402004\r\n$@spelldesc402004",
        [402841] = "Ви отримуєте здібність «Вампірський дотик»:\r\n\r\n$@spellicon402668\r\n$@spelldesc402668",
        [402842] = "Ви отримуєте здібність «Коло зцілення»:\r\n\r\n$@spellicon401946\r\n$@spelldesc401946",
        [402843] = "Ви отримуєте здібність «Тіньовий демон»:\r\n\r\n$@spellicon401977\r\n$@spelldesc401977",
        [402844] = "Ви отримуєте здібність «Спокута»:\r\n\r\n$@spellicon402174\r\n$@spelldesc402174",
        [402846] = "Ви отримуєте здібність «Око Порожнечі»:\r\n\r\n$@spellicon402789\r\n$@spelldesc402789",
        [402848] = "Вигравіюйте на штанях руну «Молитва відновлення»:\r\n\r\n$@spellicon401859\r\n$@spelldesc401859",
        [402849] = "Вигравіюйте на рукавицях руну «Слово Тіні: Смерть»:\r\n\r\n$@spellicon401955\r\n$@spelldesc401955",
        [402850] = "Вигравіюйте на плащі руну «Оберіг душі»:\r\n\r\n$@spellicon402000\r\n$@spelldesc402000",
        [402852] = "Вигравіюйте на штанях руну «Гомункули»:\r\n\r\n$@spellicon402799\r\n$@spelldesc402799",
        [402853] = "Вигравіюйте на плащі руну «Сполучене зцілення»:\r\n\r\n$@spellicon401937\r\n$@spelldesc401937",
        [402854] = "Вигравіюйте на штанях руну «Спільний біль»:\r\n\r\n$@spellicon401969\r\n$@spelldesc401969",
        [402855] = "Вигравіюйте на чоботах руну «Придушення болю»:\r\n\r\n$@spellicon402004\r\n$@spelldesc402004",
        [402857] = "Вигравіюйте на плащі руну «Вампірський дотик»:\r\n\r\n$@spellicon402668\r\n$@spelldesc402668",
        [402859] = "Вигравіюйте на рукавицях руну «Коло зцілення»:\r\n\r\n$@spellicon401946\r\n$@spelldesc401946",
        [402861] = "Вигравіюйте на штанях руну «Тіньовий демон»:\r\n\r\n$@spellicon401977\r\n$@spelldesc401977",
        [402862] = "Вигравіюйте на рукавицях руну «Спокута»:\r\n\r\n$@spellicon402174\r\n$@spelldesc402174",
        [402864] = "Вигравіюйте на шоломі руну «Око Порожнечі»:\r\n\r\n$@spellicon402789\r\n$@spelldesc402789",
        [402877] = "Ви отримуєте лють від отриманої фізичної шкоди так, ніби не носите броні.",
        [402911] = "Лютий удар, що завдає $s1% шкоди зброєю, але його можна використати лише під дією Шаленства, Берсеркерської люті або Кривавої люті. Кожна інша здібність ближнього бою, використана під дією Шаленства, Берсеркерської люті або Кривавої люті, зменшує решту часу відновлення Лютого удару на $s3 с.",
        [402913] = "Зцілює вас на $o1% від максимального запасу здоров’я протягом $d, але може бути використано лише під дією Шаленства, Берсеркерської люті або Кривавої люті. Можна використовувати під час приголомшення.\r\n",
        [402922] = "Удар щитом тепер застосовується миттєво, але має час відновлення ${$m2/1000} с.",
        [402927] = "Миттєво атакує ціль, завдаючи ${1+$AP*$m3/100} шкоди та зцілюючи вас на $s2% від максимального запасу здоров’я.  Можна використати лише протягом $402975d після вбивства нетривіального ворога.",
        [402975] = "Стає доступним після вбивства ворога.",
        [403195] = "Поки ви перебуваєте в Захисній стійці та маєте споряджений щит, Розкол броні також завдає шкоди в розмірі $403196s1% від шкоди за секунду вашої спорядженої зброї, збільшеної на $403196s2% за кожен уже накладений на ціль ефект Розколу броні. Шкода Спустошення створює велику кількість загрози, поки ви перебуваєте в Захисній стійці.",
        [403196] = "Розкол броні також завдає $s1% шкоди зброєю, збільшеної на $s2% за кожен уже накладений на ціль ефект Розколу броні.",
        [403215] = "Воїн вигукує бойовий клич, збільшуючи витривалість усіх учасників групи в межах $a1 ярдів на $s1.  Триває $d.",
        [403218] = "Ви генеруєте на $s1% більше люті від усієї завданої вами шкоди.",
        [403219] = "Грім тепер додатково збільшує час між атаками на $s1%, може використовуватися в будь-якій стійці, завдає на $s4% більше шкоди та створює на $s3% більше загрози.",
        [403228] = "Кидає ланцюг із гаком, стримуючи ціль і притягуючи її до вас. Не діє на ворогів вище ${$PL+1} рівня або позначених як боси.",
        [403231] = "Кидає ланцюг із гаком, стримуючи ціль і притягуючи її до вас.",
        [403233] = "Кидає ланцюг із гаком, стримуючи ціль і притягуючи її до вас. Під час притягування ціль не може бути приголомшена.",
        [403332] = "Стріляє в ціль, завдаючи $s2% шкоди зброєю дальнього бою. Генерує ${$m3/10} люті.",
        [403344] = "Ви отримуєте здібність «Бичування»:\r\n\r\n$@spellicon402877\r\n$@spelldesc402877",
