        [416085] = "Вигравіювати на шоломі руну \"Захоплення цілі\":",
        [416086] = "Вигравіювати на поясі руну \"Фахівець з ближнього бою\":",
        [416089] = "Вигравіювати на чоботях руну \"Удар виверни\":",
        [416090] = "Вигравіювати на шоломі руну \"Швидке вбивство\":",
        [416091] = "Вигравіювати на штанях руну \"Снайперська підготовка\":",
        [416093] = "Вигравіювати на браслетах руну \"Лють раптора\":",
        [416288] = "Поєднайте з 3 іншими частинами, щоб скласти повну мапу.",
        [416304] = "Викопує скарб у позначеному місці.",
        [416861] = "Ваша здібність \"Приручення звіра\" також діє на гадюк (як на улюбленців-компаньйонів)",
        [417056] = "Викликає Собоза.",
