        [425273] = "Зцілює ціль на $o1 протягом $d.",
        [425274] = "Зцілює ціль на $o1 протягом $d.",
        [425275] = "Зцілює ціль на $o1 протягом $d.",
        [425276] = "Зцілює ціль на $o1 протягом $d.",
        [425277] = "Зцілює ціль на $o1 протягом $d.",
        [425302] = "Отримати здібність \"Підсилене оновлення\":",
