        [425312] = "Вигравіювати на чоботях руну \"Дух спокутника\":",
        [425314] = "Вигравіювати на чоботях руну \"Розчинення\":",
        [425336] = "Збільшує швидкість атаки на $s1% протягом $d.",
        [425339] = "Завдає $i ворогам перед вами від ${$<damagepower>*$m1/100+$m2/100*$AP} до ${$<damagepower>*$M1/100+$m2/100*$AP} шкоди від вогню. Ця здібність спричиняє велику кількість загрози. Періодична шкода \"Вогняного шоку\" з ймовірністю $s3% завершує відновлення \"Вибуху лави\".",
        [425340] = "Отримати здібність \"Вибух лави\":",
        [425341] = "Отримати здібність \"Покращений примарний вовк\":",
        [425343] = "Вигравіювати на штанях руну \"Покращений примарний вовк\":",
        [425344] = "Вигравіювати на рукавицях руну \"Вибух лави\":",
        [425412] = "Під час використання дворучної зброї, ваша швидкість атаки збільшується на $s1%, а удари в ближньому бою надають $s2 додаткової люті та ${$m2*2}, якщо удар критичний.",
        [425421] = "Ваші здібності \"Ривок\", \"Перехоплення\" та \"Втручання\" тепер можна використовувати під час бою та в будь-якій стійці, а при активації вони знімають ефекти обмеження руху.",
        [425428] = "Отримати здібність \"Швидкий удар\":",
        [425429] = "Отримати здібність \"Лютий удар\":",
        [425430] = "Отримати здібність \"Вісник війни\":",
