        [425759] = "Вигравіювати на нагруднику руну \"Удари кобри\":",
        [425760] = "Вигравіювати на штанях руну \"Зміїний розмах\":",
        [425762] = "Вигравіювати на штанях руну \"Фланговий удар\":",
        [425858] = "Критичні ефекти \"Хвилі зцілення\" та \"Малої хвиля зцілення\" викликають вам на допомогу духа пращурів, який миттєво зцілює учасника групи з найнижчим запасом здоров'я в радіусі 40 м на $s1% від ефекту зцілення.",
        [425864] = "Критичні ефекти \"Хвилі зцілення\" та \"Малої хвиля зцілення\" викликають вам на допомогу духа пращурів, який миттєво зцілює учасника групи чи рейду з найнижчим запасом здоров'я в радіусі 40 м.",
        [425874] = "Виклик тотема-приманки з 5 здоров'я біля цілі на 10 с, який перенаправляє на себе наступну атаку ближнього або дальнього бою, що мала вразити ціль. Тотем також надає цілі невразливість до ефектів обмеження руху на 10 секунд.",
        [425879] = "Отримати здібність \"Пробудження пращурів\":",
        [425881] = "Отримати здібність \"Тотем-приманка\":",
        [425882] = "Вигравіювати на чоботях руну \"Тотем-приманка\":",
        [425883] = "Вигравіювати на чоботях руну \"Пробудження пращурів\":",
        [425895] = "Завдає ворогу $s1 шкоди від криги.",
        [426173] = "Збільшує дальність вашого \"Присуду\" на 30 м і ваш шанс завдання удару всіма закляттями на 17%.",
        [426174] = "Отримати здібність \"Гнучкий захист\":",
        [426175] = "Вигравіювати на поясі руну \"Гнучкий захист\":",
        [426178] = "Вигравіювати на поясі руну \"Покрив Світла\":",
        [426179] = "Отримати здібність \"Вливання Світла\":",
        [426180] = "Вигравіювати на поясі руну \"Вливання Світла\":",
        [426199] = "Завдає $s1 шкоди від тіні кожні $t1 с.",
        [426243] = "При накладані ефекту \"Пошесті\", \"Жертовного вогню\", \"Прокляття агонії\", \"Нестабільної химороді\" або \"Витягування життя\" ви завдаєте миттєвої шкоди, що дорівнює шкоді одного такту ефекту. Поновлення цих ефектів на цілі менше, ніж за $s1 секунд до завершення дії завдасть шкоди, що дорівнює залишковій періодичній шкоді заклинання.",
        [426303] = "Збільшує всю завдану шкоду на $s1%.",
        [426359] = "Розшифруйте нотатки закляття за допомогою Оберега розуміння, щоб вивчити нове закляття гравіювання.",
        [426442] = "Отримати здібність \"Клятьба\":",
        [426443] = "Вигравіювати на поясі руну \"Клятьба\":",
        [426444] = "Отримати здібність \"Гримуар синергії\":",
        [426445] = "Вигравіювати на поясі руну \"Гримуар синергії\":",
        [426449] = "Отримати здібність \"Тінь і полум'я\":",
        [426452] = "Вигравіювати на поясі руну \"Тінь і полум'я\":",
        [426454] = "Отримати здібність \"Тіньове полум'я\":",
        [426467] = "Вигравіювати на чоботях руну \"Тіньове полум'я\":",
        [426469] = "Отримати здібність \"Помста\":",
        [426470] = "Вигравіювати на шоломі руну \"Помста\":",
        [426491] = "Вигравіювати на чоботях руну \"Підбадьорливий клич\":",
        [426492] = "Отримати здібність \"Підбадьорливий клич\":",
        [426606] = "Дозволяє розмовляти з мерцем, у якого залишилися незавершені справи в світі живих. Також може вилікувати розлад шлунку.",
        [426668] = "Прикликає $s1 $lStone Rumbler:Stone Rumblers; супроводжувати заклинача, доки їх не відкличуть.",
        [426821] = "Закликає сили природи, щоб зцілити союзника.",
        [427067] = "Отримати здібність \"Смак крові\":",
        [427068] = "Отримати здібність \"Пильність\":",
