        [427081] = "Вигравіювати на браслетах руну \"Шаленство\":",
        [427082] = "Вигравіювати на браслетах руну \"Мечем і щитом\":",
        [427084] = "Вигравіювати на браслетах руну \"Погром\":",
        [427712] = "Періодична шкода від ваших здібностей \"Пошесть\", \"Нестабільна химородь\", \"Прокляття агонії\", \"Жертовний вогонь\", \"Прокляття приречення\" та \"Витягування життя\" тепер може бути критичною.",
        [427726] = "Обпалює ворогів поблизу, завдаючи ${$<power>*$427725m1/100} шкоди щоразу, коли вас атакують в ближньому бою (але не частіше, ніж раз на секунду), зменшує всю отриману магічну шкоду на $s2% та збільшує вашу шкоду від вогню на $s3%. Діє до скасування.",
        [427733] = "Викликає вартового скверни, підкореного чорнокнижникові.\n\nВартовий скверни взаємодіє з усіма талантами та ефектами, що й ваші інші демони.",
        [427742] = "Провокує ціль, що збільшує ймовірність того, що вона атакуватиме вартового скверни.",
        [427744] = "Розмашиста атака, яка вражає ціль вартового скверни та одного її союзника, завдаючи збілььшену на $s1 шкоду від зброї.",
        [427774] = "Ви відчуваєте потойбічний тиск нищівної сили.",
        [428717] = "\"Вибуховий постріл\" та пастки завдають на $s1% більше шкоди. Окрім того, первинна шкода \"Вибухової пастки\" та періодична шкода \"Обпалюючої пастки\" збільшуються на $s3% від вашої сили атаки ближнього чи дальнього бою.",
        [428738] = "Збільшення сили вашого \"Щита мани\", \"Крижаного оберегу\" і \"Вогняного оберегу\" на $s1%, а також зменшення витрат мани на поглинання шкоди \"Щитом мани\" на $s2%.",
        [428861] = "Телепортує на місце використання останнього \"Блиму\", і завершує його відновлення. Може бути використано протягом 10 секунд після використання \"Блиму\".",
        [428863] = "Отримати здібність \"Заміщення\":",
        [429133] = "Збільшує запобігання шкоді вашого \"Благословення прихистку\" на $s1% і збільшує його шкоду на $s2% від вашого показника блокування щитом.",
        [429139] = "\"Освячення\" тепер може завдавати критичної шкоди, а заклинання \"Екзорцизм\", \"Священний шок\", \"Сонячне сяйво\", \"Священний гнів\" і \"Освячення\" отримують збільшену ймовірність завдання критичної шкоди на значення, що дорівнює вашій ймовірності завдання критичного удару в ближньому бою.",
        [429151] = "Кидає у ворога молот, що завдає від ${$m1*$<damagepower>+0.15*$SPH+0.15*$AP} до ${$M1*$<damagepower>+0.15*$SPH+0.15*$AP} шкоди святістю. Можна застосовувати лише проти ворогів, у яких не більше 20% здоров'я.",
        [429152] = "\"Молот гніву\" тепер вимовляється миттєво і його відновлення завершується щоразу, коли він завдає шкоди ворогу, у якого менше $s1% здоров'я.",
        [429242] = "Вигравіювати на браслетах руну \"Милість Світла\":",
        [429243] = "Отримати здібність \"Милість Світла\":",
        [429245] = "Отримати здібність \"Покращений прихисток\":",
        [429247] = "Вигравіювати на шоломі руну \"Покращений прихисток\":",
        [429248] = "Отримати здібність \"Гнів\":",
        [429249] = "Вигравіювати на шоломі руну \"Гнів\":",
        [429250] = "Отримати здібність \"Фанатизм\":",
        [429251] = "Вигравіювати на шоломі руну \"Фанатизм\":",
        [429254] = "Отримати здібність \"Сила очищення\":",
        [429255] = "Вигравіювати на браслетах руну \"Сила очищення\":",
