        [431468] = "Вигравіювати на браслетах руну \"Цвітіння\":",
        [431600] = "Отримати здібність \"Зосереджений вогонь\":",
        [431601] = "Вигравіювати на браслетах руну \"Зосереджений вогонь\":",
        [431610] = "Отримати здібність \"Тротил\":",
        [431611] = "Вигравіювати на браслетах руну \"Тротил\":",
        [431649] = "Отримати здібність \"Божественне заступництво\":",
        [431650] = "Вигравіювати на шоломі руну \"Божественне заступництво\":",
        [431655] = "Завдає цілі від ${$m1*$<damagepower>/100} до ${$M1*$<damagepower>/100} шкоди від крижаної тіні та збільшує ймовірність критичного удару наступного \"Вибуху розуму\" на $s2%. Ефект накопичується до $u разів.",
        [431662] = "Отримати здібність \"Пронизування розуму\":",
        [431663] = "Вигравіювати на поясі руну \"Пронизування розуму\":",
        [431666] = "Наступне закляття \"Кара\" або \"Швидке зцілення\" буде вимовлено миттєво.",
        [431668] = "Отримати здібність \"Сплеск світла\":",
        [431669] = "Вигравіювати на браслетах руну \"Сплеск світла\":",
        [431670] = "Періодична шкода ваших заклинань тепер може бути критичною, а критичні удари бойових заклять завдають ${$m2+100}% шкоди.",
        [431673] = "Вигравіювати на браслетах руну \"Відчай\":",
        [431675] = "Отримати здібність \"Відчай\":",
