        [463564] = "Збільшує показник блокування вашого щита на $s1 на $d.",
        [463620] = "Завдає $s1 шкоди від святості будь-якій істоті, що атакує учасника групи поблизу. На гравцеві одночасно може діяти лише одна аура від одного паладина. Аура діє до скасування.",
        [463621] = "Завдає $s1 шкоди від святості будь-якій істоті, що атакує учасника групи поблизу. На гравцеві одночасно може діяти лише одна аура від одного паладина. Аура діє до скасування.",
        [463864] = "Зачарована сигіла живих плинної води підсилює ваш рейд, збільшуючи шкоду та зцілення від заклинань на 30 та збільшуючи силу атаки на 30 протягом 1 години.",
        [463946] = "Вражає до 3 цілей на $s1 шкоди від сил природи.",
        [464250] = "Кидається на ворога, завдаючи $s3 шкоди цілі та її союзникам поблизу й відкидаючи їх усіх назад.",
        [464279] = "Завдає звичайної шкоди та додатково $s1 усім ворогам поблизу.",
        [464592] = "Завдає шкоди від вогню ворогам поблизу.",
        [464630] = "Викликає бурю мани на $d, що завдає всім ворогам у вибраній області $s1 шкоди від криги та висмоктує $s2 мани кожні $t1 с.",
        [464743] = "Зменшує силу атак ближнього й дальнього бою ворогів поблизу на $s1 протягом $d.",
        [464945] = "Перетворює «Тіньовий удар» на «Громовий удар».",
        [464946] = "Перетворює «Громовий удар» на «Тіньовий удар».",
        [465483] = "Завдає ворогові $s2 шкоди кожні $t2 с і сповільнює його рух на $s1% на $d.",
        [465725] = "Кидає у ворога бомбу. Через $t1 с бомба вибухає, завдаючи цілі та її союзникам поблизу $20476s1 шкоди від вогню.",
        [466071] = "Проходження випробування бронзових драконів. Час буде випадковим чином сповільнюватися і прискорюватися.",
        [466195] = "Отримує $s1 шкоди від вогню кожні $t1 секунди. Ефект накопичується.",
        [466211] = "Вражає ворогів у конусі перед заклиначем і відкидає їх назад.",
        [466219] = "Заклинача оточують тіні.  Коли заклинача вражає закляття, атака ближнього або дальнього бою, нападник отримує $28377s1 шкоди від тіні.  Нападник може отримати цю шкоду лише раз на кілька секунд.  Ця шкода не створює загрози.  $n зарядів.  Триває $d.",
        [466261] = "Проходження випробування червоних драконів. При отриманні поранень ви отримуватимете $s1 шкоди від вогню кожні $t1 секунди, доки не зцілитеся до 90% від максимального запасу здоров'я. Пряме зцілення прибирає 1 ефект.",
        [466266] = "Заклинача оточують тіні.  Коли заклинача вражає закляття, атака ближнього або дальнього бою, нападник отримує $28377s1 шкоди від тіні.  Нападник може отримати цю шкоду лише раз на кілька секунд.  Ця шкода не створює загрози.  $n зарядів.  Триває $d.",
        [466269] = "Заклинача оточують тіні.  Коли заклинача вражає закляття, атака ближнього або дальнього бою, нападник отримує $28377s1 шкоди від тіні.  Нападник може отримати цю шкоду лише раз на кілька секунд.  Ця шкода не створює загрози.  $n зарядів.  Триває $d.",
        [466277] = "Проходження випробування синіх драконів. Випадковим чином отримує арканічну бомбу, яка завдає великої шкоди, що розподіляється між усіма ураженими цілями.",
        [466416] = "Проходження випробування зелених драконів. Випадковим чином уражається потужною магією природи, завдаючи шкоди гравцям, що знаходяться неподалік, і залишаючи калюжу отрути.",
        [466435] = "Коли ефект завершить дію, завдасть великої шкоди усім гравцям неподалік і створить калюжу отрути.",
        [466448] = "Завдає $s1 шкоди від сил природи кожні $t1 с.",
        [466552] = "Перевтілитися у вбивцю-ніндзя.",
        [466583] = "Перевтілитися у вбивцю-ніндзя.",
        [466596] = "Перевтілитися у вбивцю-ніндзя.",
        [466662] = "Перевтілитися у вбивцю-ніндзя.",
        [466738] = "Створює хмару блискавок на $d., що вражає всіх ворогів у вибраній зоні на $s1 шкоди від сил природи та завдає ще $s2 шкоди кожні $t2 сек.",
        [466739] = "Оточує заклинача $n кулями блискавки, які мають $h% шанс уразити нападників ближнього або дальнього бою на $s1 шкоди. Після кожного спрацювання блискавичного щита одна куля розсіюється. Тож щит зникає через $d або після $n спрацювань.",
        [466740] = "Вражає ворога блискавкою, завдаючи шкоди від сил природи.",
        [466746] = "Перевтілитися у вбивцю-ніндзя.",
        [466749] = "Перевтілитися у вбивцю-ніндзя.",
