        [467531] = "Збільшує бонус до ймовірності блокування від \"Священного щита\" на $s1%.",
        [467536] = "Талант \"Воздаяння\" з ймовірністю $s1% за ранг спрацьовує, коли ви блокуєте.",
        [467539] = "Дозволяє $s1% відновлення мани продовжувати діяти під час застосування заклять.",
        [467544] = "Ваше періодичне зцілення з ймовірністю $h% дозволить миттєво вимовити наступне закляття з тривалістю вимови менше 10 с.",
        [467561] = "Плює отрутою у ворога, завдаючи шкоди від сил природи, а потім додаткової шкоди кожні $t2 с протягом $d.",
        [467562] = "Плює отрутою у ворога, завдаючи шкоди від сил природи, а потім додаткової шкоди кожні $t2 с протягом $d.",
        [467563] = "Плює отрутою у ворога, завдаючи шкоди від сил природи, а потім додаткової шкоди кожні $t2 с протягом $d.",
        [467566] = "Плює отрутою у ворога, завдаючи шкоди від сил природи, а потім додаткової шкоди кожні $t2 с протягом $d.",
        [467604] = "Зменшує час відновлення закляття \"Слово тіні: Смерть\" на ${$m1/-1000} с.",
        [467642] = "Ранить ціль, завдаючи $s1 шкоди.",
        [467667] = "Атаки Тіньового демона в ближньому бою висмоктують енергію з цілі й перетворюють її на ману для його господаря.",
        [467708] = "Здібності, що починають комбінацію прийомів, з ймовірністю $h% дозволять використати наступну здібність без витрат енергії.",
        [467737] = "Збільшує шкоду вашої зброї в правій руці на $s1% для здібностей, що продовжують комбінацію прийомів.",
        [467738] = "Ріже ворога, завдаючи $s1 шкоди від сил природи.",
        [467739] = "Зменшує час відновлення \"Зникнення\" до ${$m3/60000} хв. Не поєднується з \"Невловимістю\".",
        [467740] = "Посилає у ворога тіньову стрілу, завдаючи $s1 шкоди від тіні.",
        [467742] = "Наповнює заклинача благословенням Первісних богів. Сила дальньої та ближньої атаки збільшується на $s1 на $d.",
        [467746] = "\"Удар за ударом\" тепер активується щоразу, коли ви продовжуєте комбінацію прийомів.",
        [467797] = "\"Удар за ударом\" також збільшує броню від предметів на $s1% за кожен ефект (але не більше ${$s1*5}%).",
        [467803] = "Відновлення \"Удару лівицею\" завершується щоразу, коли ви ухиляєтесь чи парируєте.",
        [467804] = "Ваші неперіодичні критичні ефекти шкоди та зцілення з ймовірністю $h% активують ефект \"Водяного щита\", але не поглинають його та не починають його відновлення.",
        [467809] = "\"Ланцюгова блискавка\" також зцілює останню ціль вашого \"Щита землі\" на $s1% від завданої шкоди.",
        [467814] = "Збільшує ефективність \"Ланцюгового зцілення\" та шкоду \"Ланцюгової блискавки\" на $s1%.",
        [467818] = "Критичні удари ваших заклять з ймовірністю $h% спричинять ефект таланту \"Стихійна зосередженість\".",
        [467819] = "Під час удару ближнього бою є шанс обезголовити ціль, завдавши $24241s1 шкоди.",
        [467820] = "Намагається обезголовити ціль, завдаючи $s1 шкоди.",
        [467823] = "Ефект \"Вірний бета\" вашої здібності \"Дух альфа-вовка\" тепер збільшує шкоду від вогню, криги та природи на $s1%.",
        [467863] = "Поки діє ефект \"Ясномови\" ви завдаєте на $s2% більше нефізичної шкоди.",
        [467877] = "Шанс спрацювання \"Електростатики\" збільшується на $m1% (на ${$m1/2}% якщо тримаєте по зброї в кожній руці).",
        [467879] = "Збільшує шкоду зброї в правій руці для \"Штормового удару\" на $s1%.",
        [467882] = "Поки ви мажєте активну руну \"Електростатика\", ваш \"Блискавковий щит\" отримує заряд щоразу, коли ви вражаєте ціль \"Блискавкою\" чи \"Ланцюговою блискавкою\", накопичуючи до ${$432134m1+3} зарядів, а його шкода може бути критичною.",
        [467916] = "Щоразу, коли ви блокуєте атаку, ви з ймовірністю $h% отримаєте ефект \"Зброї Водоверті\".",
        [467917] = "Збільшує шкоду ваших заклять періодичної шкоди та вартового скверни на $s1%.",
        [467983] = "Періодична шкода заклять \"Тіньове полум'я\", \"Нестабільна химородь\" та \"Прокляття агонії\", а також шкода вартового скверни з ймовірністю $h% спричинить ефект \"Тінетрансу\".",
        [467988] = "\"Тіньова стріла\" завдає на $s1% більше шкоди за кожен ваш ефект на цілі, максимум до $s2%.",
        [468012] = "Завдає ворогам поблизу звичайної шкоди та ще $s1, не даючи їм застосовувати закляття протягом $d.",
        [468061] = "Надлишкове самозцілення перетворюється на щит, який поглинає шкоду. Цей щит може поглинути до $s1% від вашого максимального запасу здоров'я, а також підсилюється від подальшого самозцілення.",
        [468065] = "Ви отримуєте ${$468066m1/10} люті щоразу коли парируєте атаку чи вашу атаку парирують.",
        [468072] = "Критичні удари \"Здолання\" поновлюють тривалість ефекту \"Розриву\" на цілі до максимальної тривалості.",
        [468156] = "Вражає ворога блискавкою, завдаючи $s2 шкоди від сил природи, після чого блискавка перескакує на додаткових ворогів поблизу. Кожен стрибок зменшує опір сил природи цієї цілі на $s1. Вражає $x1 цілей. Основну ціль також охоплює циклон, що зменшує швидкість її атак на $27648s1% на $d.",
        [468165] = "+$s1 сили атаки проти звірів.",
        [468166] = "+$s1 до сили атаки проти драконідів.",
