        [1220738] = "Збільшує шкоду й зцілення магічними закляттями та ефектами на величину до $s1.",
        [1220744] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [1220746] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [1220747] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [1220748] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [1220749] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [1220750] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [1220751] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [1220770] = "Відновлює $s1 здоров’я кожні $t1 сек.",
        [1220853] = "Завдає ворогам поблизу $s2 шкоди від криги та зменшує швидкість їхнього руху на $s1% на $d.",
        [1220854] = "Завдає ворогові шкоди від криги та зменшує швидкість його руху на $d.",
        [1220855] = "Завдає ворогам поблизу шкоди від криги, знерухомлюючи їх на час до $d.",
        [1220862] = "Обрушує завірюху, що триває $d. і завдає $s1 шкоди від криги кожні $t1 с. усім ворогам поблизу.",
        [1220908] = "Візуальний ефект викликання предмета для завдання.",
        [1220927] = "Вивільняє хвилю полум’я, завдаючи ворогам поблизу шкоди від вогню й зменшуючи швидкість їхнього руху протягом $d.",
        [1220938] = "Завдає $s1 шкоди від вогню кожні $t1 с.",
        [1220980] = "Споряджено найсучаснішими моторошними сенсорами наглядача, що дозволяють бачити все, що завгодно! \n\nЗастереження: Окуляри можуть показати не так вже й багато.",
        [1221052] = "Миттєво вбиває ціль.  Сподіваюся, тепер ти задоволений собою.....",
        [1221073] = "Карає ворога, завдаючи шкоди від святості.",
        [1221309] = "Надягти відзнаку Багряного Походу. Надягнувши її з 4 предметами форми Багряного Походу або гербовою накидкою Багряного Анклаву, ви введете в оману багатьох мешканців Нового Авалону.",
        [1221337] = "Розгорнути екстрену схованку. Більшість ворогів з меншою ймовірністю помітять вас, поки ви стоїте біля неї. Спостережливих ворогів не так легко обдурити.\n\nНе можна використовувати в бою.",
        [1221341] = "Розгорнути екстрену схованку. Більшість ворогів з меншою ймовірністю помітять вас, поки ви стоїте біля неї. Спостережливих ворогів не так легко обдурити.\n\nНе можна використовувати в бою.",
        [1221379] = "Підкорює демона до $m1 рівня, змушуючи його виконувати ваші накази.  Поки демон підкорений, час між його атаками збільшено на $s2%, а швидкість застосування заклинань зменшено на $s3%.  Триває до $d.  Повторне підкорення того самого демона з кожною спробою ускладнює контроль.",
        [1221421] = "Дозволяє заклиначеві бачити очима цілі протягом $d.  Не працює, якщо ціль перебуває в іншій копії підземелля або на іншому континенті.",
        [1221422] = "Дозволяє заклиначеві бачити очима цілі протягом $d.  Не працює, якщо ціль перебуває в іншій копії підземелля або на іншому континенті.",
        [1221571] = "Вселяє у ворога страх, змушуючи його тікати в жаху протягом $d. Одночасно можна налякати лише 1 ціль.",
        [1222207] = "Завдає $s1% шкоди зброєю й ранить ціль, зменшуючи ефективність будь-якого зцілення на $s2% протягом $d.",
