        [1230944] = "Гра на дудці викликає випадкового звіра на допомогу, що збільшує ваші фізичні здібності на 30 с.  Можна використовувати лише під час бою.",
        [1231091] = "Засипте в пристрій довільну кількість пороху і натисніть на кнопку.\n\nВаша швидкість і ймовірність серйозного поранення чи смерті зростатимуть залежно від кількості доданого пороху.\n\nМожна використовувати тільки в Новому Авалоні.",
        [1231102] = "Атакує ворогів поблизу сталевим вихором протягом $d., завдаючи шкоди зброєю та ще $3231s1 кожні $t1 сек. Тимчасово робить заклинача несприйнятливим до магії.",
        [1231200] = "Завдає ворогові $s1 шкоди від вогню.",
        [1231264] = "Атакує ворогів поблизу у вихорі сталі протягом $d, завдаючи звичайної шкоди плюс $28335s1.",
        [1231314] = "Завдає $s1% шкоди зброєю й ранить ціль, зменшуючи ефективність будь-якого зцілення на $s2% протягом $d.",
        [1231335] = "Знімає з дружньої цілі $s1 $ldisease:хворобу:хвороби;.",
        [1231376] = "Завдає $s1 шкоди від вогню кожні $t1 с.",
        [1231381] = "Якщо ви перебуваєте у котячій подобі більше $t с, ваша швидкість відновлення енергії збільшується на $s1%, а шкода \"Безжалісного укусу\" збільшується на $s2%.",
        [1231402] = "Збільшує швидкість атаки на $s1% протягом $d1.",
        [1231579] = "Отримання періодичної шкоди після вживання безбарвного зілля лікування.",
        [1231580] = "Отримання періодичної шкоди після вживання безбарвного зілля лікування.",
        [1231604] = "Миттєво надає 3 ефекти \"Тятиви Долі\"",
        [1231612] = "Ваша наступна звичайна атака ближнього бою, виконана протягом 20 c, завдасть арканічної шкоди в обсязі 200% від вашої сили заклять і приспить ціль на 20 c.",
        [1231615] = "Переміщує гравця до Гномреґана.",
        [1231648] = "Спричиняє вибух таємної магії навколо заклинача, завдаючи $s1 шкоди від таємної магії всім цілям у межах $a1 ярдів.",
        [1231656] = "Дальність дії заклять \"Муки розуму\", \"Вогняний підрив\" і \"Висмоктування життя\" збільшується на 10 м, але \"Муки розуму\" більше не сповільнюють ворогів.",
        [1231681] = "Поки ви маєте більше 30% здоров'я, ефективність вашого зцілення збільшується на 200, але при цьому ви жертвуєте 5% запасу здоров'я від кожної вимови заклять. Під дією цього ефекту ви можете отримувати тільки пряме неперіодичне зцілення. (Ефект можна перемикати)",
        [1231694] = "Бойові закляття виносять ворогам вирок на 20 с. Щоразу, коли вони завдаватимуть шкоди, їхні цілі зцілюватимуться на 3% від максимального запасу здоров'я. Триває 20 сек або до 10 ударів. (Відновлення - 60 секунд)",
        [1231698] = "Якщо в межах 20 м навколо вас немає ворогів, ви будете зцілювати всім учасникам групи в межах 20 м 125 здоров'я кожні 3 c. Група може одночасно отримувати це зцілення лише від одного гравця.",
        [1231708] = "Якщо в межах 20 м навколо вас немає ворогів, ви будете зцілювати всім навколишнім учасникам групи 125 здоров'я кожні 3 c. Група може одночасно отримувати це зцілення лише від одного гравця.",
        [1231930] = "Карає ворога, завдаючи шкоди від святості.",
        [1232013] = "Сковує нежить на час до $d., не даючи їй застосовувати закляття, атакувати чи рухатися. Будь-яка шкода звільняє ціль. Одночасно можна скувати лише одну ціль.",
        [1232044] = "З ймовірністю 2% ви виконаєте 1 додаткову атаку після завдання удару в ближньому чи дальньому бою.",
        [1232052] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
