        [1235328] = "Зменшує магічну шкоду, яку завдає ціль, на $s1 на $d.",
        [1235421] = "Спричиняє вибух таємної магії навколо заклинача, завдаючи $s1 шкоди від таємної магії всім цілям у межах $a1 ярдів.",
        [1235493] = "Застосовує закляття, коли ви щось робите.",
        [1235538] = "Здійснює ривок до ворога, завдаючи звичайної шкоди плюс $s3 та приголомшуючи супротивника на $d.",
        [1235681] = "Збільшує шкоду \"Безжалісного укусу\" на $s1%.",
        [1235793] = "Зменшує шкоду від падіння.",
        [1236125] = "Завдає ворогу $s1 шкоди кожні $t1 с протягом $d.",
        [1236151] = "Зцілює ціль на $o1 протягом $d.",
        [1236153] = "Зцілює дружню ціль на $s1.",
        [1236154] = "Прикликає силу душі члена групи, щоб захистити його щитом, який поглинає $s1 шкоди.  Триває $d.  Поки щит тримається, отримана шкода не перериває застосування заклинань.  Після накладання щита ціль не можна захистити ним знову протягом $6788d.",
        [1236156] = "Розвіює магію на цілі, знімаючи $s1 шкідливі $lspell:заклинання:заклинання; із союзника або $s1 корисні $lspell:заклинання:заклинання; з ворога.",
        [1236172] = "Завдає ворогові шкоди від вогню.",
        [1236173] = "Завдає ворогові шкоди від вогню, а потім додаткової шкоди кожні $t2 с. протягом $d.",
        [1236174] = "Перетворює ворога на вівцю, змушуючи його блукати до $d. Під час блукання вівця не може атакувати чи застосовувати закляття, але дуже швидко відновлюється. Будь-яка шкода поверне цілі звичайну форму. Одночасно можна перетворити лише одну ціль. Діє лише на звірів, драконів, велетнів, гуманоїдів і створінь.",
        [1236175] = "Телепортує заклинача на 20 ярдів уперед, якщо ніщо не заважає. Також звільняє заклинача від усіх пут.",
        [1236176] = "Роззброює ворога на $d.",
        [1236177] = "Калічить ворога, завдаючи $s1 шкоди та зменшуючи його швидкість руху на $s2% протягом $d.",
        [1236179] = "Завдає ворогові $s2 шкоди й приголомшує його на $d.",
        [1236181] = "Закликає святу магію, щоб зцілити союзника.",
        [1236182] = "Завдає ворогові $s1 шкоди й збільшує отримувану ним шкоду від святості на $s2 за кожен Удар хрестоносця. Накопичується до 5 разів. Триває $d.",
        [1236183] = "Завдає ворогові та його найближчим союзникам шкоди зброєю плюс $s1, уражаючи до $x1 цілей.",
        [1236188] = "Прицільний постріл, що збільшує шкоду дальнього бою на $s1.",
        [1236190] = "Випускає град снарядів у ворога та його союзників поблизу, вражаючи до $x1 цілей звичайною шкодою плюс $s1.",
        [1236191] = "Ошелешує ворога, зменшуючи швидкість його руху на $s1% протягом $d.",
        [1236220] = "Збільшує час між атаками ворогів поблизу на $s1%, сповільнює їхній рух на $s2% та швидкість вимовляння заклять на $s3% на $d.",
        [1236266] = "Створює $s1 Вибухову вівцю, яка $lcharges:charge; до найближчого $lenemy:enemies; і $lexplodes:explode;. Вибухові вівці нестабільні й самознищаться через $d.",
        [1236269] = "Завдає $s1 шкоди від вогню всім ворогам у вибраній зоні.",
        [1236270] = "Завдає всім цілям у конусі перед інженером, що використовує зброю, $13184s1 шкоди від вогню протягом $d. Хіба що вона вибухне.....",
        [1236290] = "Перетворює ворога на вівцю, змушуючи його блукати до $d. Під час блукання вівця не може атакувати чи застосовувати закляття, але дуже швидко відновлюється. Будь-яка шкода поверне цілі звичайну форму. Одночасно можна перетворити лише одну ціль. Діє лише на звірів, драконів, велетнів, гуманоїдів і створінь.",
        [1236291] = "Завдає ворогові шкоди від вогню, а потім додаткової шкоди кожні $t2 с. протягом $d.",
        [1236307] = "Зцілює союзника кожні $t1 с. протягом $d.",
        [1236308] = "На дружній цілі виростають шипи, які завдають нападникам $s1 шкоди від сил природи, коли ті влучають у ціль.  Триває $d.",
        [1236879] = "Збільшує дух учасників групи поблизу на $M1.",
        [1237064] = "Назавжди встановлює приціл на лук або рушницю, збільшуючи ймовірність влучання на 3%.",
        [1237312] = "Запускає у ворога крижановогняну стрілу, завдаючи $s2 шкоди від крижаного вогню, сповільнюючи рух на $s1% і завдаючи додатково $o3 шкоди від крижаного вогню протягом $d. Закляття перевіряється проти меншого з опорів цілі кризі та вогню й вважається одночасно шкодою від криги та вогню.",
        [1237313] = "Запускає у ворога крижановогняну стрілу, завдаючи $s2 шкоди від крижаного вогню, сповільнюючи рух на $s1% і завдаючи додатково $o3 шкоди від крижаного вогню протягом $d. Закляття перевіряється проти меншого з опорів цілі кризі та вогню й вважається одночасно шкодою від криги та вогню.",
        [1237938] = "Плює отрутою у ворога, завдаючи шкоди від сил природи, а потім додаткової шкоди кожні $t2 с протягом $d.",
        [1238096] = "Дає шанс приголомшити ворога під час атаки. Триває $d.",
        [1238299] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $s2% більше шкоди.",
        [1238300] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $s2% більше шкоди.",
        [1238319] = "Завдає $s1 шкоди від тіні кожні $t1 с.",
        [1238373] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $408490s2% більше шкоди.",
        [1238376] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $408490s2% більше шкоди.",
        [1238787] = "Розподіляє шкоду порівну між усіма ураженими цілями.",
        [1239242] = "Зцілює дружню ціль на $s1, додатково на $o2 протягом $d і збільшує ефективність Ланцюгового зцілення, застосованого безпосередньо до цієї цілі, на $s3%.",
        [1239243] = "Зцілює дружню ціль на $s1, додатково на $o2 протягом $d і збільшує ефективність Ланцюгового зцілення, застосованого безпосередньо до цієї цілі, на $s3%.",
        [1239482] = "Карає ворога, завдаючи шкоди від святості.",
        [1239696] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [1239697] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [1239699] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [1239700] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [1240044] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
        [1240045] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
        [1240046] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
        [1240047] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
