        [436434] = "Воєначальник",
        [436435] = "Маршал",
        [436436] = "Генерал",
        [436437] = "Командир",
        [436438] = "Генерал-лейтенант",
        [436439] = "Лейтенант-командир",
        [436440] = "Чемпіон",
        [436441] = "Лицар",
        [436442] = "Кам’яний вартовий",
        [436443] = "Збільшує шкоду союзників поблизу на $s1% протягом $d.",
        [436444] = "Невблаганний, неупереджений і непроклятий. ",
        [436469] = "Удар має шанс збільшити силу на $436471s1 протягом $436471d.",
        [436471] = "Удар має шанс збільшити силу на $s1 протягом $d.",
        [436473] = "Добряче приголомшує ціль на $d1.",
        [436477] = "Вивільняє лютий вихор сталі й крові, завдаючи $s1 шкоди Тіньовим ударом усім ворогам у межах $a1 ярдів.",
        [436478] = "Вивільняє відкладений вибух крові й вогню, завдаючи $436479s1 шкоди тіньовим полум’ям усім цілям у межах $436479a1 ярдів.",
        [436479] = "Навколо заклинача відбувається відкладений вибух крові й вогню, завдаючи $s1 шкоди тіньовим полум’ям усім цілям у межах $a1 ярдів.",
        [436481] = "Завдає цілі та її найближчим союзникам додатково $s1 шкоди, вражаючи до $x1 цілей. Створює додаткову загрозу.",
        [436482] = "Додає $436481s1 шкоди «Удару бурі» до ваших атак ближнього бою, завдаючи шкоди цілі та її найближчим союзникам, до $436481x1 цілей. Створює додаткову загрозу. Триває $d.",
        [436516] = "$?a443369[Зцілює дружню ціль на ${$<healpower>*$436517m1/100}–${$<healpower>*$436517M1/100}.]\r\n\r\n[Поєднує таємну магію, вогонь і кригу, зберігаючи хрономантичну енергію для подальшого використання. Ви можете утримувати цю енергію до $d, після чого вона згорає та зникає. Після вивільнення зцілює дружню ціль на ${$<healpower>*$436517m1/100}–${$<healpower>*$436517M1/100}.\r\n\r\nДля взаємодії з іншими закляттями, талантами й ефектами це закляття належить до таємної магії, вогню та криги.]",
        [436534] = "Дякуємо за співпрацю.",
        [436545] = "Поєднайте з відповідним джерелом сили, щоб створити заряджене ядро Порожнечі.",
        [436641] = "Жага крові переповнює ваші чуття!",
        [436690] = "Збільшує ймовірність критичного удару вашого вихованця на 1%.",
        [436892] = "Збільшує швидкість руху на $s1% просто неба у формі кота та ймовірність ухилення у формі кота на $24864s1%.",
        [436893] = "Збільшує швидкість руху на $s1% просто неба у формі кота та ймовірність ухилення у формі кота на $24864s1%.",
        [436952] = "Вшануйте архіваріусів.",
        [437053] = "Вшануйте архіваріусів.",
        [437054] = "Вшануйте архіваріусів.",
        [437055] = "Вшануйте архіваріусів.",
        [437301] = "Заклинач зосереджує хмари дрімоти навколо цілей.",
        [437324] = "Дотик до хмари дрімоти присипляє ціль на $d, зменшуючи отримувану нею шкоду та зцілення на $s3%.",
        [437327] = "Приборкує приховану таємну енергію в повітрі поблизу, надаючи заряджене натхнення: витрати мани на всі закляття зменшуються на $M%, а шкода та зцілення збільшуються на величину до $s2 протягом $d.",
        [437340] = "Активує в шоломі протоколи зниження радіації, миттєво знімаючи всі активні ефекти отрути та надаючи несприйнятливість до всієї шкоди від сил природи на $d.",
        [437349] = "Спричиняє ґнейрологічний шок, миттєво завдаючи вам $s3 шкоди, але також збільшуючи швидкість атак ближнього й дальнього бою на $s1% протягом $d. ",
        [437353] = "Заклинач видихає на ціль хвилю їдкої магії, завдаючи $s1 шкоди від сил природи та зменшуючи її броню на $s2% протягом $d.",
        [437357] = "Надає ґнейромантичну медитацію, дозволяючи $s% відновлення мани продовжуватися під час вимовляння заклять і збільшуючи шкоду та зцілення закляттями на величину до $s2 протягом $d. ",
        [437362] = "Спричиняє гіперпровідний шок, миттєво завдаючи вам $s2 шкоди, але також збільшуючи швидкість вимовляння заклять на $s% протягом $d. ",
        [437367] = "Після успішного блокування обертові, гострі як бритва шестерні на цьому щиті завдають нападнику $s фізичної шкоди, а власнику — $437388s1 фізичної шкоди.",
        [437368] = "Дістає з пояса гіперпровідну монету й підкидає її. Орел: ймовірність критичного удару всіма закляттями й атаками збільшується на $437698s1% протягом $437698d. Решка: швидкість руху збільшується на $437699s1% протягом $437699d.",
        [437375] = "Завдає $s1 шкоди цілям позаду заклинача й відкидає їх.",
        [437377] = "Надає глибоку зосередженість, зменшуючи швидкість руху на $s%, але також збільшуючи опір закляттям усіх шкіл на 50 і швидкість атак ближнього бою на $s% протягом $d. ",
        [437382] = "Надає посилену силу волі, запобігаючи мовчанці, перериванню та затримці вимовляння заклять протягом $d.",
        [437390] = "Заклинач плює в гравців млявою отрутою, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $d. Ця отрута зменшує ймовірність влучання на $s2% і збільшує витрати на здібності на $s3%.",
        [437398] = "Заклинач розбиває свідомість усіх гравців, що не сплять, завдаючи їм $s1 шкоди від тіні.",
        [437410] = "Заклинач поринає в глибокий сон на $d, зменшуючи отримувану шкоду на $s1%.",
        [437424] = "Заклинач зосереджує хмари дрімоти навколо цілей.",
        [437425] = "Заклинач плює в гравців млявою отрутою, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $d. Ця отрута зменшує ймовірність влучання на $s2% і збільшує витрати на здібності на $s3%.",
