        [1219894] = "Назавжди насичує ваші наплічники Душею Істинної Альфи:\r\n\r\nКоли «Дух Альфи» застосовано до себе, він також збільшує ваше здоров’я на $1213939s1%, створювану загрозу на $1213939s2% і всю завдану шкоду на $1213939s3%.",
        [1219895] = "Назавжди насичує ваші наплічники Душею Хранителя тотемів:\r\n\r\nРадіус дії тотемів, що діють на союзників, збільшується до ${$m1+20} м.",
        [1219896] = "Назавжди насичує ваші наплічники Душею Предків:\r\n\r\nПісля вимови \"Хвилі зцілення\", \"Малої хвилі зцілення\" та \"Бистрини\" ви з ймовірністю $h% відновите ману в обсязі $s1% від базової вартості закляття.",
        [1219897] = "Назавжди насичує ваші наплічники Душею Ткача духів:\r\n\r\nВаша \"Хвиля зцілення\" також перестрибує на цілі неподалік, з кожним стрибком зцілюючи на $s2% менше. Максимум до ${$m1-1} стрибків.",
        [1219898] = "Назавжди насичує ваші наплічники Душею Водохода:\r\n\r\nВаші неперіодичні критичні ефекти шкоди та зцілення з ймовірністю $h% активують ефект \"Водяного щита\", але не поглинають його та не починають його відновлення.",
        [1219899] = "Назавжди насичує ваші наплічники Душею Доглядача бурі:\r\n\r\n\"Ланцюгова блискавка\" також зцілює останню ціль вашого \"Щита землі\" на $s1% від завданої шкоди.",
        [1219900] = "Назавжди насичує ваші наплічники Душею Стихійного провидця:\r\n\r\nЗбільшує ефективність \"Ланцюгового зцілення\" та шкоду \"Ланцюгової блискавки\" на $s1%.",
        [1219901] = "Назавжди насичує ваші наплічники Душею Життєзнавця:\r\n\r\nВаша \"Бистрина\" також збільшує ефективність \"Ланцюгового зцілення\" на $s1%.",
        [1219902] = "Назавжди насичує ваші наплічники Душею Цілителя духів:\r\n\r\nЗменшує час вимовляння «Ланцюгового зцілення» на ${$m1/-1000}.1 с.",
        [1219903] = "Назавжди насичує ваші наплічники Душею Витонченого:\r\n\r\nЗбільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1219904] = "Назавжди насичує ваші наплічники Душею Вождя:\r\n\r\nТалант \"Шквал\" збільшує вашу швидкість атаки ще на $s1%.",
        [1219905] = "Назавжди насичує ваші наплічники Душею Зарядженого люттю:\r\n\r\nШанс спрацювання \"Електростатики\" збільшується на $m1% (на ${$m1/2}% якщо тримаєте по зброї в кожній руці).",
        [1219906] = "Назавжди насичує ваші наплічники Душею Бурелома:\r\n\r\nЗбільшує шкоду зброї в правій руці для \"Штормового удару\" на $s1%.",
        [1219907] = "Назавжди насичує ваші наплічники Душею Бурі:\r\n\r\nПоки ви мажєте активну руну \"Електростатика\", ваш \"Блискавковий щит\" отримує заряд щоразу, коли ви вражаєте ціль \"Блискавкою\" чи \"Ланцюговою блискавкою\", накопичуючи до ${$432134m1+3} зарядів, а його шкода може бути критичною.",
        [1219908] = "Назавжди насичує ваші наплічники Душею Сейсмічного трощителя:\r\n\r\nЗбільшує шкоду \"Штормового удару\" та \"Удару лавою\" на $s1%. Збільшує шкоду на $s2% при використанні дворучної зброї.",
        [1219909] = "Назавжди насичує ваші наплічники Душею Вогненосця:\r\n\r\nКритичні удари «Ударом бурі», «Лавовим батогом» і «Виверженням лави» змушують ціль горіти, отримуючи $s1% завданої шкоди протягом $1213915d.",
        [1219910] = "Назавжди насичує ваші наплічники Душею Вулкана:\r\n\r\nКритичні удари «Блискавкою» мають $h% шанс скинути час відновлення «Виверження лави» та «Ланцюгової блискавки» й зробити наступне «Виверження лави» або «Ланцюгову блискавку» протягом $415105d миттєвим.\r\n",
        [1219911] = "Назавжди насичує ваші наплічники Душею Лютого полум’я:\r\n\r\n«Виверження лави» тепер також поновлює тривалість «Вогняного шоку» на цілі до $29228d.\r\n",
        [1219912] = "Назавжди насичує ваші наплічники Душею Володаря стихій:\r\n\r\nКритичні удари ваших заклять з ймовірністю $h% спричинять ефект таланту \"Стихійна зосередженість\".",
        [1219913] = "Назавжди насичує ваші наплічники Душею Племінника:\r\n\r\nЕфект \"Вірний бета\" вашої здібності \"Дух альфа-вовка\" тепер збільшує шкоду від вогню, криги та природи на $s1%.",
        [1219914] = "Назавжди насичує ваші наплічники Душею Провідника духів:\r\n\r\nПоки діє ефект \"Ясномови\" ви завдаєте на $s2% більше нефізичної шкоди.",
        [1219915] = "Назавжди насичує ваші наплічники Душею Старійшини:\r\n\r\nЗ ймовірністю $s1% ви уникнете затримки вимови заклять \"Блискавка\", \"Ланцюгова блискавка\" та \"Виверження лави\" при отриманні шкоди, а шанс спрацювання таланту \"Стихійна зосередженість\" збільшується на $s2%.",
        [1219916] = "Назавжди насичує ваші наплічники Душею Стихій:\r\n\r\nЗбільшує додаткову шкоду від критичних ударів заклять вогню, криги та природи на $s1%.",
        [1219918] = "Назавжди насичує ваші наплічники Душею Вартового предків:\r\n\r\nЗбільшує шанс блокувати атаки щитом на $s1%.",
        [1219919] = "Назавжди насичує ваші наплічники Душею Оскверненого:\r\n\r\nЗбільшує ймовірність спрацювання руни \"Сплеск сили\" на $s1%.",
        [1219921] = "Назавжди насичує ваші наплічники Душею Лютого:\r\n\r\n\"Несамовитість\" має на ${$m1/-1000} секунд зменшений час відновлення і більше не зменшує вашу броню.",
        [1219922] = "Назавжди насичує ваші наплічники Душею Перевертня:\r\n\r\nУ подобах ведмедя та жахливого ведмедя ви спричиняєте на $s1% більше загрози, а \"Зіщулювання\" тепер прибирає всю вашу загрозу цілі але має на ${$m2/1000} с більший час відновлення.",
        [1219923] = "Назавжди насичує ваші наплічники Душею Територіального:\r\n\r\n«Розмах (ведмідь)» також змушує ваш «Трощення» уражати ще $467217s1 додаткову ціль протягом наступних $467217d.",
        [1219924] = "Назавжди насичує ваші наплічники Душею Звіра:\r\n\r\nЗдібності \"Нівечення (ведмідь)\", \"Розмах (ведмідь)\", \"Терзання\" та \"Розірвати\" мають на $s1% більшу ймовірність завдання критичного удару цілям під ефектом здібності \"Розірвати\".",
        [1219926] = "Назавжди насичує ваші наплічники Душею Лютого:\r\n\r\nЩоразу, коли ви ухиляєтеся у формі лютого ведмедя, шкода вашого наступного «Калічення» або «Розмаху» збільшується на $1213190s1%; ефект накопичується до $1213190u разів.",
        [1219927] = "Назавжди насичує ваші наплічники Душею Калічника:\r\n\r\nЗменшує час відновлення «Калічення (ведмідь)» на ${$m1/-1000}.1 с.",
        [1219929] = "Назавжди насичує ваші наплічники Душею Піклувальника:\r\n\r\nПісля вимови \"Цілющого дотику\" або \"Підживлення\" ви з ймовірністю $h% відновите ману в обсязі $s1% від базової вартості закляття.",
        [1219930] = "Назавжди насичує ваші наплічники Душею Спокійного:\r\n\r\nЗменшує час відновлення \"Спокою\" на $s1% та збільшує його зцілення на $s2%.",
        [1219931] = "Назавжди насичує ваші наплічники Душею Сноходця:\r\n\r\nКритичні ефекти ваших заклять зцілення спричиняють «Стан сну», дозволяючи $408261s1% відновлення мани тривати під час вимовляння заклять протягом $408261d. ",
        [1219932] = "Назавжди насичує ваші наплічники Душею Доглядача гаю:\r\n\r\nНеперіодичні критичні ефекти заклять зменшують час вимовляння вашого наступного «Цілющого дотику», «Відновлення» або «Живлення» на ${$467204m1/-1000}.1 с.",
        [1219933] = "Назавжди насичує ваші наплічники Душею Пернатого мудреця:\r\n\r\nЗбільшує зцілення «Дикого зростання» на $s1%. Крім того, «Дике зростання» тепер можна використовувати у формі місячного совозвіра, де його зцілення додатково збільшується на $467206s2%.",
        [1219934] = "Назавжди насичує ваші наплічники Душею Доброзичливого провидця:\r\n\r\nЗменшує час відновлення заклять \"Переродження\" та \"Осяяння\" на $s1%.",
        [1219935] = "Назавжди насичує ваші наплічники Душею Ткача життя:\r\n\r\nКритичні ефекти \"Цілющого дотику\", \"Розростання\" та \"Підживлення\" миттєво відновлюють цілі ще $s1% від первинного ефекту зцілення.",
        [1219936] = "Назавжди насичує ваші наплічники Душею Осяйника:\r\n\r\n«Чарівний вогонь (дикий)» також збільшує ймовірність влучання всіх атак по цілі на $455868s1% протягом $455868d.",
        [1219938] = "Назавжди насичує ваші наплічники Душею Різника:\r\n\r\n«Розрив» і «Лютий укус» мають $455903s1% шанс за кожне витрачене очко серії поновити тривалість «Дикого реву» до початкового значення.",
        [1219939] = "Назавжди насичує ваші наплічники Душею Кігтя:\r\n\r\nЗбільшує тривалість ефекту \"Роздирання\" на ${$m2/1000} с та збільшує його періодичну шкоду на $m1%.",
        [1219940] = "Назавжди насичує ваші наплічники Душею Гордого:\r\n\r\nПоки діє «Лють тигра», ваша ймовірність критичного удару збільшується на $467209s1%.",
        [1219941] = "Назавжди насичує ваші наплічники Душею Варвара:\r\n\r\nЗдібності \"Шматування\", \"Безжалісний укус\" та \"Нівечення (кіт)\" завдають на $s1% більше шкоди за кожен ваш ефект кровотечі, максимум до $s2%.",
        [1219942] = "Назавжди насичує ваші наплічники Душею Несамовитого:\r\n\r\n\"Шматування\" більше не має вимоги до позиціонування, але завдає на $s1% більше шкоди, якщо ви знаходитесь за спиною цілі.",
        [1219943] = "Назавжди насичує ваші наплічники Душею Знекровлювача:\r\n\r\nКритичні удари «Каліченням», «Шматуванням» і «Лютим укусом» спричиняють кровотечу, що завдає $s1% завданої шкоди протягом наступних $1213176d с.",
        [1219944] = "Назавжди насичує ваші наплічники Душею Хранителя шипів:\r\n\r\nШкоду \"Шипів\" збільшено на $s1%, а тривалість збільшено на $s2%.",
        [1219945] = "Назавжди насичує ваші наплічники Душею Безумця:\r\n\r\nЗбільшує ймовірність завдання удару закляттями та атаками на $s1%.",
        [1219946] = "Назавжди насичує ваші наплічники Душею Заклинача зірок:\r\n\r\nЗменшує час відновлення \"Зорепаду\" на $s1%.",
        [1219947] = "Назавжди насичує ваші наплічники Душею Ночі:\r\n\r\nЗбільшує шкоду та радіус шкоди зірок \"Зорепаду\" та \"Урагану\" на $s1%.",
        [1219948] = "Назавжди насичує ваші наплічники Душею Хранителів:\r\n\r\nВаші застосування «Гніву» мають $h% шанс прикликати групу з $s1 древнів, які атакуватимуть вашу ціль протягом $467079d.",
        [1219949] = "Назавжди насичує ваші наплічники Душею Гнівного:\r\n\r\nКритичні удари «Гнівом» мають $h% шанс збільшити шкоду вашого наступного «Зоряного вогню» на $467088s1%; ефект накопичується до $467088u разів.",
        [1219951] = "Назавжди насичує ваші наплічники Душею Астрального Вознесеного:\r\n\r\nЗбільшує додаткову шкоду від критичних ударів заклять \"Зоряний вогонь\", \"Зоряний сплеск\" та \"Гнів\" на $s1%.",
        [1219952] = "Назавжди насичує ваші наплічники Душею Заклинача комет:\r\n\r\nЗменшує час вимовляння та глобальний час відновлення «Зоряного вогню» на ${$m1/-1000}.1 с.",
        [1219953] = "Назавжди насичує ваші наплічники Душею Лісу:\r\n\r\nЗбільшує ймовірність завдання критичного удару \"Гнівом\" на $s1%.",
        [1219954] = "Назавжди насичує ваші наплічники Душею Звіриної майстерності:\r\n\r\nЙмовірність ухилення та парирування ваших атак ближнього бою зменшено на $s1%.",
        [1219958] = "Протягом $457699d після виходу зі стійки ви можете використовувати здібності, що потребують цієї стійки, ніби все ще перебуваєте в ній.",
        [1219960] = "Протягом перших $457816d після активації стійки ви отримуєте додаткову перевагу:\r\n\r\nБойова стійка/Стійка гладіатора: завдана шкода збільшується на $457816s1%.\r\n\r\nСтійка берсерка: ймовірність критичного удару збільшується на $457817s1%.\r\n\r\nЗахисна стійка: отримувана фізична шкода зменшується на $457814s1%.",
        [1219980] = "«Помста» також надає вам «Шквал», збільшуючи швидкість атаки на $12970s1% протягом наступних $12970n ударів.",
        [1219982] = "Коли ваша ціль парирує атаку, ви миттєво завдаєте їй «Відплати» на $468071s2% шкоди зброєю. Від «Відплати» не можна ухилитися, її не можна заблокувати чи парирувати, і вона може спрацювати лише раз на $468071d для кожної цілі.",
        [1219994] = "«Відволікання» також надає «Уникнення» на $457331d, зменшуючи всю шкоду від атак по області від негравців на $457331s1%.",
        [1220016] = "Поки активні «Лише подряпина» та «Танець клинків», «Багряна буря», «Мушкетон» і «Віяло ножів» коштують на $457351s1 менше енергії та створюють на $457351s2% більше загрози.",
        [1220018] = "«Зникнення» тепер зменшує всю отримувану магічну шкоду на $457437s1% на час дії, але більше не надає непомітності й не знімає ефекти обмеження руху.",
        [1220020] = "Ваші завершальні прийоми мають $b1% шанс за кожне очко серії зменшити фізичну шкоду від наступної атаки ближнього бою на $457469s1%, якщо вона влучить у вас протягом $457469d.",
        [1220046] = "Щоразу, коли ви вражаєте ціль «Спалахом», ваша шкода від вогню збільшується на $1214088s1% протягом $1214088d; ефект накопичується до $1214088u разів.",
        [1220056] = "Влучання «Тіньового розсічення» мають $h% шанс надати вам уламок душі, скинути час відновлення «Вогню душі» та зробити наступний «Вогонь душі» протягом $457643d миттєвим.",
        [1220058] = "Поки ви націлені на ворога в межах $468029r ярдів, «Витік життя» надає вам ману за рахунок здоров’я цілі, але завдає їй на $s1% менше шкоди. Кількість отриманої мани не змінюється.",
        [1220060] = "Поки діє «Метаморфоза», ваші атакувальні здібності та прикликання демонів не витрачають уламків душі. Крім того, коли ви завдаєте цілі шкоди «Опіком тіні», ви зцілюєтеся на $468062s1% максимального запасу здоров’я.",
        [1220064] = "Зменшує час відновлення «Тіньового розсічення» на ${$m1/-1000}.1 с.",
        [1220068] = "Протягом $1214156d після використання «Тіньового розсічення» ваш «Пекучий біль» уражає ще $1214156s1 ціль у радіусі ближнього бою.",
        [1220070] = "Після використання «Відволікаючого пострілу» ви створюєте на $456339s1% більше загрози протягом $456339d.",
        [1220072] = "Під час вистежування певного типу істот ви завдаєте їм на $s1% більше шкоди.",
