        [1243088] = "$@spelldesc<1243081>",
        [1243089] = "$@spelldesc<1243081>\r\n",
        [1243090] = "$@spelldesc<1243081>\r\n",
        [1243312] = "$@spelldesc<1243318>",
        [1243318] = "Прикликає біса.",
        [1243339] = "Уражає ціль на $1225228d, змушуючи $1225228s1% усієї шкоди, яку чорнокнижник завдає іншим цілям, також завдаватися проклятій цілі. «Прокляття спустошення» може діяти лише на 1 ціль, і від одного чорнокнижника на одній цілі може діяти лише одне прокляття.",
        [1243356] = "Викопує скарб.",
        [1243845] = "Посилює ефект «Мокрого снігу» на $d.",
        [1243846] = "Посилює ефект «Пилової бурі» на $d.",
        [1243847] = "Посилює ефект «Спекотної жарини» на $d.",
        [1243960] = "Прикликає Век’зола.",
        [1243969] = "$?pc142418[Крім того, досвід, отриманий за вбивства, збільшується на $s1%.][]",
        [1244245] = "Відновлює $o1 здоров’я протягом $d.  Під час їжі потрібно залишатися сидячи. Якщо їсти щонайменше 10 секунд, ви насититеся й отримаєте $s1 витривалості та духу на $d. $@spelldesc1243969",
        [1244396] = "Вражає ворога блискавкою, що перескакує на іншого ворога поблизу. Закляття вражає до $x1 цілей, завдаючи кожній наступній цілі більшої шкоди від сил природи.\r\n",
        [1244493] = "Поглинає незвичайні сили Клоберта, змінюючи певні здібності.",
        [1244625] = "Висмоктує магію з розлому лей-лінії.",
        [1244951] = "Зцілює ціль на 100% її максимального здоров’я.",
        [1245095] = "Поглинає незвичайні сили Клоберта, змінюючи певні здібності.",
        [1245119] = "Зменшує завдану шкоду на $s1% протягом $d.\r\n",
        [1245154] = "Видає могутній рев, приголомшуючи всіх гравців у межах $R1 на $d. ",
        [1245158] = "Намагається отримати інформацію про цільовий предмет. DNT",
        [1245249] = "Збільшує фізичну шкоду на $s1 протягом $d.",
        [1245320] = "Розділяє 1 купку дивного пилу на $s1 частинок магії.",
        [1245338] = "Прикликає двох духовних вовків.",
        [1245340] = "$@spelldesc<1245338>",
        [1245608] = "Збільшує вашу навичку гірництва на $m1. Не може підвищити навичку гірництва понад $m2. Ви вивчите гірництво, якщо ще не навчені й не знаєте двох інших професій.",
        [1245609] = "Збільшує вашу навичку травництва на $m1. Не може підвищити навичку травництва понад $m2. Ви вивчите травництво, якщо ще не навчені й не знаєте двох інших професій.",
        [1245610] = "Збільшує вашу навичку зняття шкур на $m1. Не може підвищити навичку зняття шкур понад $m2. Ви вивчите зняття шкур, якщо ще не навчені й не знаєте двох інших професій.\r\n",
        [1245705] = "Клацніть правою кнопкою, щоб прикликати або відкликати Мінімуса Тентакулуса. Мінімус Тентакулус полюбляє пожирати інших крихітних істот, щоб поглинати їхню силу.",
        [1245883] = "Приголомшує ворога, не даючи йому рухатися або діяти протягом $d. Також знімає з ураженого ворога один випадковий корисний ефект.",
        [1245940] = "Збільшує швидкість на $S1%. ",
        [1245956] = "Завдає поточній цілі $S1 шкоди від вогню.",
        [1246026] = "Допомагає зціленню та росту пишної рослинності.",
        [1246031] = "Показує на вашій мапі сліди кобольдів поблизу.",
        [1246453] = "Змушує гравців іти до місця перебування заклинача.",
        [1246456] = "$@spelldesc<1246453>",
        [1247168] = "Прочитайте етикетку, щоб визначити вантаж.",
        [1247169] = "Несприйнятливість до шкоди з усіх джерел.",
        [1247237] = "Магія нечестивих тотемів захищає Невільний Дух, зменшуючи шкоду на $S1%.",
        [1247252] = "Очищає тотем, роблячи його вразливим і завдаючи значної шкоди протягом часу.\r\n",
        [1247426] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\n- $M3 мироцвіту\n- $M4 срібнолисту\n- $M5 земляного кореня\n- $M6 магокоролівської крові\n- $M7 гострошипу|r",
        [1247427] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 мідної руди\r\n- $M4 олов’яної руди|r",
        [1247428] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 лляної тканини\r\n- $M4 легкої шкіри",
        [1247429] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 дивного пилу\r\n- $M4 великої магічної сутності\r\n- $M5 малого мерехтливого уламка\r\n- $M6 великого мерехтливого уламка|r",
        [1247430] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 душного зілля\r\n- $M4 синецвіту\r\n- $M5 дикого сталецвіту\r\n- $M6 могильного моху\r\n- $M7 королівської крові",
        [1247431] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 срібної руди\r\n- $M4 залізної руди",
        [1247432] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 вовняної тканини\r\n- $M4 шовкової тканини\r\n- $M5 середньої шкіри",
        [1247433] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 пилу душі\r\n- $M4 великої астральної сутності\r\n- $M5 малого сяйливого уламка\r\n- $M6 великого сяйливого уламка",
        [1247434] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 життєкореня\r\n- $M4 блідолисту\r\n- $M5 золотошипу\r\n- $M6 вуса Кадґара",
        [1247435] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 зимокусю\r\n- $M4 вогнецвіту\r\n- $M5 пурпурового лотоса\r\n- $M6 сліз Артаса",
        [1247436] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 золотої руди\r\n- $M4 мітрилової руди",
        [1247437] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 маготканини\r\n- $M4 важкої шкіри",
        [1247438] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 пилу видінь\r\n- $M4 великої містичної сутності\r\n- $M5 малого сяйливого уламка\r\n- $M6 великого сяйливого уламка",
        [1247439] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 золотого сансаму\r\n- $M4 сонцетрави\r\n- $M5 сліпозілля\r\n- $M6 примарного гриба\r\n- $M7 ґромокрову",
        [1247440] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 сновиднолисту\r\n- $M4 гірського срібношалфею\r\n- $M5 чумоцвіту\r\n- $M6 кригошапки",
        [1247441] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 руди щиросрібла\r\n- $M4 торієвої руди\r\n- $M5 руди темного заліза",
        [1247442] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 рунічної тканини\r\n- $M4 товстої шкіри\r\n- $M5 міцної шкіри",
        [1247443] = "Наповніть ящик будь-яким набором із наведеного списку:|cnIQ1:\r\n- $M3 пилу снів\r\n- $M4 великої сутності Підсвіття\r\n- $M5 малого блискучого уламка\r\n- $M6 великого блискучого уламка",
