        [1293184] = "Надає змогу купувати й виготовляти на вибір рецепти класових рукавичок, наплічників або чобіт комплекту рівня 1 у Айсарри Нічнолуг.",
        [1293228] = "Маґматус підпалює ціль, завдаючи $s1 шкоди від вогню та додаткової шкоди від вогню кожні $t2 с протягом $d.",
        [1293241] = "Наказує яструбу пікірувати на вибраного ворога, завдаючи ${$s1+($rap*($s4/100))} фізичної шкоди й продовжуючи атаку протягом $1293248d. Одночасно можуть бути активні лише $s3 яструби. «Виклик яструба» має спільний час відновлення з «Арканічним пострілом».",
        [1293242] = "Розтрощіть цільовий предмет на брухт, щоб отримати невелику кількість придатних ремісничих матеріалів. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1293248] = "Викликає яструба.",
        [1293327] = "Завдає шкоди від природи ворогам поблизу, сповільнюючи їх щонайбільше на $d.",
        [1293329] = "Розмістіть на пагорбах уздовж північно-західного хребта вершини.",
        [1293331] = "Ваші атаки зброєю ближнього бою завдають $1293333s1 шкоди від природи і вам, і вашій цілі.\r\n",
        [1293333] = "Атаки зброєю ближнього бою завдають $1293333s1 шкоди від природи і вам, і вашій цілі.",
        [1293342] = "Після отримання шкоди є шанс надати вам $1293345s1 броні протягом $1293345d.",
        [1293354] = "Кравецтво +$s1.",
        [1293359] = "Занурте отруйне серце в Колодязь Вічності. Зачекайте мить...",
        [1293361] = "Перемога!",
        [1293424] = "+$s1 сили атаки проти гуманоїдів.",
        [1293433] = "Атаки ближнього бою цією зброєю катують ціль, завдаючи $1293429s1 шкоди від вогню та збільшуючи вашу шкоду від цього ефекту по цілі на $1293429s1. Накопичується до $1293451u разів.",
        [1293518] = "Уражає ціль небезпечним токсином, завдаючи $s1 шкоди від природи. Рослинам завдає у $s2 разів більше шкоди.",
        [1293525] = "Наказує яструбу пікірувати на вибраного ворога, завдаючи ${$s1+($rap*($s4/100))} фізичної шкоди й продовжуючи атаку протягом $1293248d. Одночасно можуть бути активні лише $s3 яструби. «Виклик яструба» має спільний час відновлення з «Арканічним пострілом».",
        [1293526] = "Наказує яструбу пікірувати на вибраного ворога, завдаючи ${$s1+($rap*($s4/100))} фізичної шкоди й продовжуючи атаку протягом $1293248d. Одночасно можуть бути активні лише $s3 яструби. «Виклик яструба» має спільний час відновлення з «Арканічним пострілом».",
        [1293527] = "Наказує яструбу пікірувати на вибраного ворога, завдаючи ${$s1+($rap*($s4/100))} фізичної шкоди й продовжуючи атаку протягом $1293248d. Одночасно можуть бути активні лише $s3 яструби. «Виклик яструба» має спільний час відновлення з «Арканічним пострілом».",
        [1293539] = "Завдає $s1 шкоди від святості щоразу, коли ви блокуєте.",
        [1293540] = "Зменшує час вимови заклять і ефектів, що воскрешають цілі, на $s1%.",
        [1293542] = "Дає вам $s1% шанс уникнути переривання від шкоди під час вимови «Швидкого зцілення».",
        [1293544] = "Збільшує ймовірність критичного ефекту вашого «Спалаху Світла» на $s1%.\r\n",
        [1293568] = "Уражає ціль небезпечним токсином, завдаючи $s1 шкоди від природи. Рослинам завдає у $s2 разів більше шкоди.",
        [1293657] = "Ви вільно володієте такими мовами:$?s668[\r\n$@spellname668][]$?s669[\r\n$@spellname669][]$?s670[\r\n$@spellname670][]$?s671[\r\n$@spellname671][]$?s672[\r\n$@spellname672][]$?s813[\r\n$@spellname813][]$?s814[\r\n$@spellname814][]$?s815[\r\n$@spellname815][]$?s816[\r\n$@spellname816][]$?s817[\r\n$@spellname817][]$?s7340[\r\n$@spellname7340][]$?s7341[\r\n$@spellname7341][]$?s17737[\r\n$@spellname17737][]$?s25674[\r\n$@spellname25674][]$?s462134[\r\n$@spellname462134][]",
        [1293674] = "Отримання шкоди має $h% шанс надати «Люте Світло» на $1293673d, через що ваші атаки ближнього бою завдають $1293675s1 шкоди від святості. Невмерлим завдає у $s1 разів більше шкоди.",
        [1293675] = "Завдає $s1 шкоди від святості.",
        [1293695] = "Ваш «Пекучий біль» створює на $s1% менше загрози й таврує ціль на $1293696d. Наступні $m2 атаки вашого вихованця по цілі створюють велику загрозу та завдають від $<minDam> до $<maxDam> шкоди від вогню або тіні залежно від вихованця.",
        [1293697] = "Поглинання тавра завдає від $<minDam> до $<maxDam> шкоди від тіні.",
        [1293699] = "Поглинання тавра завдає $s1 фізичної шкоди.",
        [1293701] = "Під час отримання удару в бою є $h% шанс отримувати $1293700s1 мани кожні 5 с протягом $1293700d.",
        [1293712] = "Ви вмієте користуватися такими типами обладунків:$?s9078[\r\n$@spellname9078][]$?s9077[\r\n$@spellname9077][]$?s8737[\r\n$@spellname8737][]$?s750[\r\n$@spellname750][]",
        [1293714] = "Випускає магічний розсікальний заряд у ціль, завдаючи $s1 фізичної шкоди й перериваючи вимовляння закляття на $d.",
        [1293736] = "Збільшує досвід за вбивство невмерлих на $s1% протягом $d.",
        [1293740] = "Збільшує вашу витривалість на $s1. У Гіджалі, на Вершині Гіджалу та в Курганних глибинах ви також отримуєте $s2% ймовірності влучання.\r\n\r\nТриває $d. Одночасно може діяти ефект лише одного настою. Цей ефект зберігається після смерті.",
        [1293741] = "Збільшує вашу витривалість на $s1. У Гіджалі, на Вершині Гіджалу та в Курганних глибинах ви також отримуєте $s2% ймовірності критичного удару.\r\n\r\nТриває $d. Одночасно може діяти ефект лише одного настою. Цей ефект зберігається після смерті.",
        [1293742] = "Збільшує вашу витривалість на $s1. У Гіджалі, на Вершині Гіджалу та в Курганних глибинах ви також отримуєте $s2% зменшення ймовірності ухилення або парирування ваших атак.\r\n\r\nТриває $d. Одночасно може діяти ефект лише одного настою. Цей ефект зберігається після смерті.",
        [1293743] = "Збільшує вашу витривалість на $s1. У Гіджалі, на Вершині Гіджалу та в Курганних глибинах ви також отримуєте $s2% швидкості.\r\n\r\nТриває $d. Одночасно може діяти ефект лише одного настою. Цей ефект зберігається після смерті.",
        [1293782] = "Закляття й атаки проти свиней завдають $1292675s1 шкоди від природи.",
        [1293783] = "Закляття й атаки проти свиней завдають $1292675s1 шкоди від природи.",
        [1293787] = "Завдає могутнього удару на $s1 шкоди від святості. Невмерлим і свиням завдає у $s2 разів більше шкоди.",
        [1293800] = "Вилийте вміст обтягнутого шкірою флакона на мілководдя водойми всередині лігва Мертвого Лісу.",
        [1293801] = "Від цієї істоти йде дивний туман, приховуючи всіх гравців та істот поблизу.",
        [1293802] = "+$s1 сили атаки проти гуманоїдів.",
        [1293805] = "Закликає щойно пробуджену силу, щоб збільшити ліміт споряджених предметів рівня Ремісника до $s2.",
        [1293806] = "Назавжди зачаровує предмет для голови, надаючи $ec1 сили атаки.",
