        [1302206] = "Зменшує інтелект на $s1.",
        [1302217] = "Насичує посох магією на 1 годину, через що він іноді випускає арканічний снаряд у цілі, яким ви завдаєте шкоди закляттям.",
        [1302219] = "Насичує посох магією на 1 годину, зменшуючи опір вогню цілей ваших заклять на $1306572s1.",
        [1302229] = "Відновлює $s1 здоров'я.\r\n",
        [1302247] = "Завдає цілі додатково $s1 шкоди від аркани.",
        [1302248] = "Додає $1302247s1 шкоди від аркани вашим атакам ближнього бою.",
        [1302264] = "Збільшує вашу ймовірність ухилення на $s1% протягом $d або доки ви не ухилитеся від $n атак.",
        [1302279] = "Розбиває ціль, завдаючи $s1 фізичної шкоди. Елементалям землі, ґолемам і титанокованим завдає у $s2 разів більше шкоди.",
        [1302283] = "Насичує посох магією на 1 годину, збільшуючи шкоду від крижаних заклять та ефектів на величину до $1306518s1.",
        [1302284] = "Насичує кинджал магією на 1 годину, через що він іноді заморожує ворогів при влучанні.",
        [1302285] = "Викликає вірну жабу-фамільяра на $d. Її присутність збільшує ваш інтелект на $s2.",
        [1302286] = "Використайте на Гіпнотичному клинку, щоб створити могутню зброю.",
        [1302293] = "Використайте на Клинку Сільверлейна, щоб створити могутню зброю.",
        [1302294] = "Використайте на Відьомському клинку, щоб створити могутню зброю.",
        [1302297] = "Магічно відкриває замок складності $s1 або нижчої.",
        [1302303] = "Викликає вірного кота-фамільяра на $d. Його присутність збільшує ваш інтелект на $s2.",
        [1302304] = "Насичує посох магією на 1 годину, збільшуючи шкоду від вогняних заклять та ефектів на величину до $1306579s1.",
        [1302305] = "Насичує посох магією на 1 годину, зменшуючи опір кризі цілей ваших заклять на $1306580s1.",
        [1302307] = "Насичує посох магією на 1 годину, надаючи вашим закляттям шкоди шанс збільшити швидкість атак жезлом.",
        [1302311] = "Насичує посох магією на 1 годину, збільшуючи шкоду від вогняних заклять та ефектів на величину до $1306581s1.",
        [1302312] = "Насичує посох магією на 1 годину, збільшуючи шкоду від крижаних заклять та ефектів на величину до $1306582s1.",
        [1302341] = "Після влучання закляттям, що завдає шкоди, є шанс атакувати розум цілі, збільшуючи час вимови всіх заклять на $1302342s1% протягом $1302342d. Накопичується до $1302342u разів.",
        [1302342] = "Після влучання закляттям, що завдає шкоди, є шанс атакувати розум цілі, збільшуючи час вимови всіх заклять на $s1% протягом $d. Накопичується до $u разів.",
        [1302343] = "Завдає $o1 шкоди від вогню протягом $d.",
        [1302344] = "Розсікає ціль із магічно посиленою точністю, завдаючи $s1 шкоди від аркани. Рослинам завдає у $s2 разів більше шкоди.",
        [1302348] = "При влучанні є шанс відновити $s1 мани.",
        [1302353] = "Піднесіть смолоскип Вічного Полум'я.",
        [1302354] = "Завдає $s1 шкоди від вогню. Рослинам завдає у $s2 разів більше шкоди.",
        [1302372] = "Імперська дисципліна не дає вашій швидкості руху впасти нижче $s1%.",
        [1302374] = "Залізотканина твердне під тиском, зменшуючи шкоду, отриману під час приголомшення, на $s1%.",
        [1302378] = "Повертає наступне вороже закляття відправникові.",
        [1302502] = "Викликає книжкову полицю до табору, дозволяючи йому працювати як бібліотека. Поблизу потрібне багаття.",
        [1302508] = "Проводить дослідження заклять, отримуючи в'язку сувоїв. Потрібна придатна бібліотека.",
        [1302545] = "Збільшує вашу шкоду проти невмерлих на $s1%.",
        [1302650] = "Клацніть правою кнопкою, щоб викликати або відкликати свого примарного ведмежа.",
        [1302661] = "Викликає або відкликає верхового примарного ведмедя.",
        [1302700] = "Знімає ефект сповільнення.",
        [1302707] = "Швидкість руху збільшено на $s1%.",
        [1302711] = "Знімає ефект укорінення.",
        [1302720] = "Знімає ефект роззброєння.",
        [1302764] = "Викликає кількох Гниючих Роївців поблизу.",
        [1302780] = "Маса істот звивається всередині плоті В'ялопащі, викликаючи Плотського Черв'яка кожні $t1 с.",
        [1302783] = "$@spelldesc<1302780>",
        [1302785] = "$@spelldesc<1302780>",
        [1302787] = "Отримує шкоду в обсязі $S1% максимального здоров'я кожні $t1 с.\r\n",
        [1302834] = "$@spelldesc1302833",
        [1302874] = "Приголомшує вас і відновлює $o1 здоров'я протягом $d. У лісових і трав'янистих місцевостях надає $1302875s1 витривалості протягом $1302875d.",
        [1302875] = "$@spelldesc1302874",
        [1302929] = "|cff9d9d9dНа ймовірність ковзного удару не впливає навичка зброї понад ваш максимум.|r",
        [1302937] = "Використайте кристал, щоб тимчасово приголомшити Володаря Посудин.",
        [1302939] = "Ви маєте $sk55/$<sc> навички $@spellname1302939.\r\n\r\nЦіль рівня $PL:\r\nВлучання, ухилення та парирування: ${$<hdp>}.1%\r\nКритичний удар: ${$<cr>}.1%\r\nШтраф ковзного удару: ${$<gp>}%\r\nЙмовірність ковзного удару: ${$<gc>}%\r\n$@expandkey[\r\nLevel ${$PL+1} target:\r\nHit, Dodge, and Parry: ${$<hdp1>}.1%\r\nCritical Hit: ${$<cr1>}.1%\r\nGlancing Blow Penalty: ${$<gp1>}%\r\nGlancing Blow Chance: ${$<gc1>}%\r\n\r\nLevel ${$PL+2} target:\r\nHit, Dodge, and Parry: ${$<hdp2>}.1%\r\nCritical Hit: ${$<cr2>}.1%\r\nGlancing Blow Penalty: ${$<gp2>}%\r\nGlancing Blow Chance: ${$<gc2>}%\r\n\r\nLevel ${$PL+3} target:\r\nHit, Dodge, and Parry: ${$<hdp3>}.1%\r\nCritical Hit: ${$<cr3>}.1%\r\nGlancing Blow Penalty: ${$<gp3>}%\r\nGlancing Blow Chance: ${$<gc3>}%\r\n\r\n$@spelldesc1302929\r\n]",
        [1302968] = "Ваші ефекти «Ситості» засвоюються на $s2% повільніше. У пустельних землях цей ефект додатково збільшується на $s1%.",
