        [1303011] = "Ви маєте $sk228/$<sc> навички $@spellname1303011.\r\n\r\nЦіль рівня $PL:\r\nВлучання: ${$<hdp>}.1%\r\nКритичний удар: ${$<cr>}.1%\r\n$@expandkey[\r\nLevel ${$PL+1} target:\r\nHit: ${$<hdp1>}.1%\r\nCritical Hit: ${$<cr1>}.1%\r\n\r\nLevel ${$PL+2} target:\r\nHit: ${$<hdp2>}.1%\r\nCritical Hit: ${$<cr2>}.1%\r\n\r\nLevel ${$PL+3} target:\r\nHit: ${$<hdp3>}.1%\r\nCritical Hit: ${$<cr3>}.1%\r\n\r\n]",
        [1303013] = "Ви маєте $sk229/$<sc> навички $@spellname1303013.\r\n\r\nЦіль рівня $PL:\r\nВлучання, ухилення та парирування: ${$<hdp>}.1%\r\nКритичний удар: ${$<cr>}.1%\r\nШтраф ковзного удару: ${$<gp>}%\r\nЙмовірність ковзного удару: ${$<gc>}%\r\n$@expandkey[\r\nLevel ${$PL+1} target:\r\nHit, Dodge, and Parry: ${$<hdp1>}.1%\r\nCritical Hit: ${$<cr1>}.1%\r\nGlancing Blow Penalty: ${$<gp1>}%\r\nGlancing Blow Chance: ${$<gc1>}%\r\n\r\nLevel ${$PL+2} target:\r\nHit, Dodge, and Parry: ${$<hdp2>}.1%\r\nCritical Hit: ${$<cr2>}.1%\r\nGlancing Blow Penalty: ${$<gp2>}%\r\nGlancing Blow Chance: ${$<gc2>}%\r\n\r\nLevel ${$PL+3} target:\r\nHit, Dodge, and Parry: ${$<hdp3>}.1%\r\nCritical Hit: ${$<cr3>}.1%\r\nGlancing Blow Penalty: ${$<gp3>}%\r\nGlancing Blow Chance: ${$<gc3>}%\r\n\r\n$@spelldesc1302929\r\n]",
        [1303015] = "Ви маєте $sk473/$<sc> навички $@spellname1303015.\r\n\r\nЦіль рівня $PL:\r\nВлучання, ухилення та парирування: ${$<hdp>}.1%\r\nКритичний удар: ${$<cr>}.1%\r\nШтраф ковзного удару: ${$<gp>}%\r\nЙмовірність ковзного удару: ${$<gc>}%\r\n$@expandkey[\r\nLevel ${$PL+1} target:\r\nHit, Dodge, and Parry: ${$<hdp1>}.1%\r\nCritical Hit: ${$<cr1>}.1%\r\nGlancing Blow Penalty: ${$<gp1>}%\r\nGlancing Blow Chance: ${$<gc1>}%\r\n\r\nLevel ${$PL+2} target:\r\nHit, Dodge, and Parry: ${$<hdp2>}.1%\r\nCritical Hit: ${$<cr2>}.1%\r\nGlancing Blow Penalty: ${$<gp2>}%\r\nGlancing Blow Chance: ${$<gc2>}%\r\n\r\nLevel ${$PL+3} target:\r\nHit, Dodge, and Parry: ${$<hdp3>}.1%\r\nCritical Hit: ${$<cr3>}.1%\r\nGlancing Blow Penalty: ${$<gp3>}%\r\nGlancing Blow Chance: ${$<gc3>}%\r\n\r\n$@spelldesc1302929\r\n]",
        [1303075] = "Викликає або відкликає верхового лавандового кодо.",
        [1303215] = "Викликає або відкликає верхового караванного кодо.",
        [1303286] = "Повністю не може бачити через пов'язку на очах, що зменшує її ймовірність влучання атаками на $S1%.",
        [1303317] = "Підіймає прапор Залізогарта.",
        [1303350] = "Збільшує час між атаками ворогів поблизу на $s1% і сповільнює їхню швидкість руху та вимови заклять на $s2% протягом $d.",
        [1303457] = "Надає гору ремісничих матеріалів для тестування професій, а також гроші й жетони, необхідні для придбання рецептів і матеріалів.",
        [1303505] = "Вивільняє залишки мани елементаля в область, що відновлює істотам поблизу $1303505s1 мани кожні $1303505t1 с.",
        [1303509] = "Розвійте пахощі над південним урвищем Верхів’я мисливців.",
        [1303520] = "Поєднайте в’язку трав, в’язку сухих кедрових гілочок, сухожильну нитку та обрядове кресало, щоб створити підготовлені пахощі.",
        [1303543] = "Підніміть Багряний прапор у таборі. Потребує багаття поблизу.",
        [1303634] = "Зцілює ціль від недуг.",
        [1303755] = "Киньте камінь повернення пораненому рабові-робітнику.",
        [1303869] = "Киньте камінь повернення пораненому рабові-робітнику, попередньо привівши його до тями.",
        [1304751] = "Ймовірність критичного удару всіма закляттями й атаками збільшено на $s1%.",
        [1305116] = "Киньте нещільно зав’язаний мішечок із могильним пилом у Велике море.",
        [1305136] = "Ще кухоль, еге ж.",
        [1305189] = "Збільшує шкоду союзників поблизу на $s1% протягом $d.",
        [1305400] = "Відкриває складний замок.",
        [1305416] = "Обманює ворогів двійником, змушуючи істот поблизу атакувати його протягом $d.",
        [1305424] = "Відновлює $1305426s1 мани, коли ви вбиваєте драконіда, за якого отримуєте досвід. Цей ефект не може спрацьовувати частіше ніж раз на $proccooldown с.",
        [1305426] = "Відновлено $s1 мани.",
        [1305718] = "Під час бою ваші закляття зцілення можуть викликати дракончика Оніксії, який захищатиме вас у бою протягом $d.",
        [1305732] = "Закляття зцілення можуть викликати дракончика Оніксії, який захищатиме вас у бою протягом $1305718d.",
        [1305855] = "Очі Карґри бачать за межі світу смертних, зменшуючи її шанс влучити атаками на $S1%.",
        [1306076] = "Швидкість руху збільшено на $s1% у лісових і степових місцевостях.",
        [1306126] = "Дає змогу гірникові виплавити шматок важкої торієвої руди у важкий торієвий зливок. Для виплавки важкого торію потрібна розплавлена ливарня.",
        [1306128] = "Збирає зовнішні вигляди цього комплекту обладунків.",
        [1306158] = "Збільшує зцілення заклять і ефектів на величину до $s1, а їхню шкоду — на величину до $s2. Уночі ефект подвоюється.",
        [1306160] = "Збільшує зцілення заклять і ефектів на величину до $s1, а їхню шкоду — на величину до $s2.",
        [1306267] = "Встановлює знак мандрівника на 1 хв. На знаку можна написати повідомлення, через що він існуватиме 1 годину та стане видимим для інших гравців.",
        [1306362] = "Зменшує ймовірність влучання по вас ефектами укорінення та сповільнення на $s1%.",
        [1306384] = "Поєднує 20 уламків амулета Матистраля у відновлений амулет Матистраля.",
        [1306396] = "Прикликає істоту, що охороняє руїни Матистраля біля Каменя глибин.",
        [1306410] = "Поєднує 20 уламків амулета Матистраля у відновлений амулет Матистраля.",
        [1306411] = "Прикликає істоту, що охороняє руїни Матистраля біля Каменя глибин.",
        [1306429] = "Збільшує ймовірність критичного ефекту вашого закляття «Святий шок» на $s1%.",
        [1306433] = "Поки діє «Святий щит», величина блокування вашого щита збільшується на $1306749s1%.",
        [1306438] = "Відкидає ціль назад і зменшує її загрозу до нуля.",
        [1306459] = "В образі ведмедя, лютого ведмедя або совуха ви отримуєте додаткову базову броню в обсязі ${$m1*100}% від вашої навички захисту.",
        [1306483] = "Влучання «Роздиранням» з імовірністю $h% завершують відновлення «Нівечення (ведмідь)».",
        [1306572] = "Зменшує опір вогню вашої цілі на $s1.",
        [1306580] = "Зменшує опір кризі вашої цілі на $s1.",
        [1306607] = "Зменшує тривалість усіх ефектів хвороб на вас на $m1%.",
        [1306608] = "Викликає вартового для нагляду за областю.",
        [1306622] = "Завдає цілі та її найближчому союзнику $s1 шкоди від природи. Завдає рослинам і невмерлим у $s2 рази більше шкоди.",
        [1306628] = "Наберіть снігу з перевалу Південної Брами в керамічний глечик.",
        [1306632] = "Відновлює $s1 мани кожні 5 с у пустельних місцевостях.",
        [1306650] = "Зменшує витрати мани на закляття на $s1%.",
        [1306660] = "Зменшує витрати мани на закляття на $s1%.",
        [1306662] = "Зменшує витрати мани на закляття на $s1%.",
        [1306665] = "Викликає вартового для нагляду за областю.",
        [1306672] = "Відновлює $s1 здоров’я кожні 5 с у болотистих місцевостях.",
        [1306676] = "Завдає $1306675s1 шкоди щоразу, коли ви блокуєте. Діапазон шкоди та її школа змінюються залежно від пори року.",
        [1306682] = "Промахи «Роздумів» з імовірністю $h% завдають повторного удару.",
        [1306683] = "«Роздуми» намагаються виправити минуле й завдають повторного удару.",
        [1306684] = "«Роздуми» намагаються виправити минуле й завдають повторного удару.",
        [1306689] = "Шкода, яка мала б убити вас, натомість залишає 1 здоров’я та надає несприйнятливість до шкоди на $1306691d. Спрацьовує раз на $1306690d.",
        [1306693] = "Принесіть до бухгалтерського столу ратуші Гіллзбрада. ",
        [1306695] = "Доставте на нижній поверх Дун-Ґарока.",
        [1306699] = "Збільшує зцілення заклять і ефектів на величину до $s1, а їхню шкоду — на величину до $s2 у гірських місцевостях.",
        [1306700] = "Відкрийте флакон і поставте його на землю у високій оглядовій точці.",
        [1306759] = "Зменшує отриману шкоду від дальніх атак на $s1.",
        [1306765] = "Вражає ціль дальнього бою «Буревим пострілом», завдаючи $s1 шкоди від природи.",
        [1306900] = "Збільшує вашу ймовірність критичного удару або зцілення на ${$s1}.1% проти цілей із запасом здоров’я нижче $s2%.",
        [1306905] = "Збільшує зцілення заклять і ефектів на величину до $s1, а їхню шкоду — на величину до $s2 у засніжених місцевостях.",
        [1306933] = "Вражає ціль, завдаючи $s1 шкоди від криги. У засніжених місцевостях додатково завдає $1306934s1 шкоди від вогню.",
        [1306956] = "Періодично викликає допомогу Пакту Чорноколючки.",
        [1307008] = "Наповнює блискавкою, завдаючи $1307008S1 шкоди від природи у випадкових місцях поблизу кожні $t1 с.",
        [1307014] = "Збільшує ваш ефективний рівень виявлення непомітності на ${$s1/5} протягом $d.",
        [1307050] = "Назавжди встановлює приціл на лук, рушницю або арбалет, збільшуючи ймовірність критичного удару на $s2%.",
        [1307066] = "У спалаху сталі заклинач обертає зброю, завдаючи звичайної шкоди плюс $1307066s1 усім гравцям у межах $1307066A1 м.",
        [1307172] = "Розміщує алхімічну лабораторію для рецептів, які її потребують, і надає всі переваги криниці мани. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх криниці мани, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307174] = "Розміщує верстак анархіста для рецептів, які його потребують. Потребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307175] = "Розміщує ковадло й надає всі переваги точильного круга. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх точильного круга, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307176] = "Розміщує арканічне горно для рецептів, які його потребують, і надає всі переваги зачарованої лютні. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх зачарованої лютні, замінивши її. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307223] = "Розміщує арканічний утилізатор, що дає змогу ефективніше розпорошувати предмети, і надає всі переваги зачарованої лютні. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх зачарованої лютні, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307226] = "Розміщує залізну піч, потрібну для найскладніших кулінарних рецептів. Потребує кухонного вогнища поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307227] = "Будує звичайне багаття, що дає змогу готувати їжу та розмістити до $s1 додаткових табірних споруд. Гравці, які сидять або займаються ремеслом поблизу протягом $1229739d, отримують переваги інших табірних споруд.",
        [1307230] = "Будує намет, який дає вам та іншим гравцям, що сидять поблизу, змогу збільшити запас відпочилого досвіду до $s2% рівня. Не діє, якщо запас відпочилого досвіду вже перевищує це значення.\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307237] = "Будує експертне багаття, що дає змогу готувати їжу та розмістити до $s1 додаткових табірних споруд. Гравці, які сидять або займаються ремеслом поблизу протягом $1229739d, отримують переваги інших табірних споруд.",
        [1307242] = "Розміщує ферментатор, який дає змогу створювати певні реагенти, і надає всі переваги криниці мани. Потребує багаття поблизу. Можна розмістити поверх криниці мани, замінивши її. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307248] = "Розміщує теплицю, у якій із посадженого насіння з часом виростають трави, і надає всі переваги пахощової свічки. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх пахощової свічки, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307252] = "Будує багаття підмайстра, що дає змогу готувати їжу та розмістити до $s1 додаткових табірних споруд. Гравці, які сидять або займаються ремеслом поблизу протягом $1229739d, отримують переваги інших табірних споруд.",
        [1307255] = "Розміщує ткацький верстат для рецептів, які його потребують, і надає всі переваги прапора фракції. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх прапора фракції, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307257] = "Викладає «Бенкет Пиріжка» з їжею, що підвищує витривалість. Потребує кухонного вогнища поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307261] = "Розміщує майстерне горно для рецептів, які його потребують, і надає всі переваги точильного круга. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх точильного круга, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307264] = "Розміщує розплавлену ливарню для рецептів, які її потребують, і надає всі переваги магнітного каменя. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх магнітного каменя, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307266] = "Викликає робота-реагентника, у якого ви та інші гравці поблизу можете купувати реагенти. Потребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307315] = "Шкідливе закляття з певною ймовірністю завдає цілі $1307288s1 шкоди від тіні та висмоктує $1307288s3 мани. Завдає невмерлим у $1307288s2 рази більше шкоди.\r\n",
        [1307334] = "Збільшує зцілення заклять і ефектів на величину до $s1, а їхню шкоду — на величину до $s2 у примарних місцевостях.",
        [1307385] = "Викликає ремонтного робота, у якого ви та інші гравці поблизу можете купувати реагенти й ремонтувати спорядження. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх робота-реагентника, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307386] = "Розміщує сад каміння, де з часом з’являється звичайна гірнича жила, і надає всі переваги магнітного каменя. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх магнітного каменя, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307387] = "Розміщує гібридизатор насіння, що дає змогу розмножувати насіння або поєднувати його у рідкісніші сорти, і надає всі переваги пахощової свічки. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх пахощової свічки, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307391] = "Розміщує швейну машину для рецептів, які її потребують, і надає всі переваги табірного намету. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх табірного намету, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307393] = "Розміщує прядку, що дає змогу створювати певні реагенти, і надає всі переваги прапора фракції. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх прапора фракції, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307395] = "Розміщує козли для дублення, що дають змогу створювати певні реагенти, і надає всі переваги табірного намету. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх табірного намету, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307400] = "Критичні удари «Гніву» подовжують тривалість вашого «Рою комах» на цілі на ${$s1/1000} с. Проти звірів тривалість додатково збільшується на ${$s2/1000} с.",
        [1307423] = "Активує вартового Ґоаза.",
        [1307426] = "Активує вартового Ґоаза.",
        [1307519] = "Закликає захист природи на $d. Перший ворог, що вразить вас атакою ближнього бою, буде укорінений на $1307520d.",
        [1307644] = "Атаки ворогів ближнього бою можуть завершити відновлення вашого «Вогняного вибуху».",
        [1307694] = "[DNT] Завдає $s1% від максимального запасу здоров’я шкоди кожні $t1 с. Не може вбити ціль.\r\n\r\nЦе налагоджувальне закляття.",
        [1307696] = "Завдає цілі $s1 шкоди від природи. Завдає драконідам і крилатим ворогам у $s2 рази більше шкоди.",
